import socket
import time
import logging
import signal
import sys
import atexit

try:
    from gpiozero import DigitalOutputDevice, PWMOutputDevice
except ImportError:
    DigitalOutputDevice = None
    PWMOutputDevice = None

try:
    from gpiozero.pins.lgpio import LGPIOFactory
    _GPIOZERO_PINFactory = LGPIOFactory
except ImportError:
    _GPIOZERO_PINFactory = None

try:
    import spidev
except ImportError:
    spidev = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

MOTOR_A_FORWARD_PIN = 27
MOTOR_A_BACKWARD_PIN = 22
MOTOR_B_CLOCKWISE_PIN = 24
MOTOR_B_COUNTERCLOCKWISE_PIN = 25
MOTOR_A_ENABLE_PIN = 17
MOTOR_B_ENABLE_PIN = 23
MCP3008_CHANNEL_0 = 0
MCP3008_CHANNEL_1 = 1
SPI_CLK_PIN = 11
SPI_MOSI_PIN = 10
SPI_MISO_PIN = 9
SPI_CS_1_PIN = 8
SPI_CS_2_PIN = 7
PWM_FREQUENCY = 1000
NUM_READINGS = 5
READING_DELAY = 0.02
HEALTH_CHECK_INTERVAL = 60
SOCKET_PORT = 12345

_running = True
_motor_a_forward = None
_motor_a_backward = None
_motor_b_clockwise = None
_motor_b_counterclockwise = None
_motor_a_enable = None
_motor_b_enable = None
_spi = None
_sensor_data = {'sensor1': None, 'sensor2': None}
_last_health_check = 0


def _signal_handler(signum, frame):
    global _running
    _running = False
    logger.info(f"Signal {signum} received, shutting down...")


def _cleanup():
    global _motor_a_forward, _motor_a_backward, _motor_b_clockwise, _motor_b_counterclockwise, _motor_a_enable, _motor_b_enable, _spi
    for name, dev in [('motor_a_forward', _motor_a_forward), ('motor_a_backward', _motor_a_backward),
                      ('motor_b_clockwise', _motor_b_clockwise), ('motor_b_counterclockwise', _motor_b_counterclockwise),
                      ('motor_a_enable', _motor_a_enable), ('motor_b_enable', _motor_b_enable)]:
        if dev is not None:
            try:
                dev.close()
            except Exception:
                pass
    if _spi is not None:
        try:
            _spi.close()
        except Exception:
            pass
    logger.info("Cleanup complete.")


def _init_gpio():
    global _motor_a_forward, _motor_a_backward, _motor_b_clockwise, _motor_b_counterclockwise, _motor_a_enable, _motor_b_enable
    if DigitalOutputDevice is None:
        logger.warning("gpiozero not available; running in simulation mode.")
        return False
    try:
        _motor_a_forward = DigitalOutputDevice(MOTOR_A_FORWARD_PIN)
        _motor_a_backward = DigitalOutputDevice(MOTOR_A_BACKWARD_PIN)
        _motor_b_clockwise = DigitalOutputDevice(MOTOR_B_CLOCKWISE_PIN)
        _motor_b_counterclockwise = DigitalOutputDevice(MOTOR_B_COUNTERCLOCKWISE_PIN)
        _motor_a_enable = PWMOutputDevice(MOTOR_A_ENABLE_PIN, frequency=PWM_FREQUENCY)
        _motor_b_enable = PWMOutputDevice(MOTOR_B_ENABLE_PIN, frequency=PWM_FREQUENCY)
        _motor_a_enable.value = 0
        _motor_b_enable.value = 0
        return True
    except Exception as e:
        logger.error(f"GPIO initialization failed: {e}")
        return False


def _init_spi():
    global _spi
    if spidev is None:
        logger.warning("spidev not available; running in simulation mode.")
        return False
    try:
        _spi = spidev.SpiDev()
        _spi.open(0, 0)
        _spi.max_speed_hz = 1000000
        _spi.mode = 0
        return True
    except Exception as e:
        logger.error(f"SPI initialization failed: {e}")
        return False


def _read_mcp3008(channel):
    if _spi is None:
        return None
    try:
        adc = _spi.xfer2([1, (8 + channel) << 4, 0])
        return ((adc[1] & 3) << 8) + adc[2]
    except Exception as e:
        logger.error(f"SPI read error on channel {channel}: {e}")
        return None


def _set_motor_direction(motor, direction, enable):
    if motor not in (_motor_a_forward, _motor_a_backward, _motor_b_clockwise, _motor_b_counterclockwise):
        return
    try:
        if direction == _motor_a_forward:
            enable.value = 0.5
            motor.on()
        elif direction == _motor_a_backward:
            enable.value = 0.5
            motor.off()
        elif direction == _motor_b_clockwise:
            enable.value = 0.5
            motor.on()
        elif direction == _motor_b_counterclockwise:
            enable.value = 0.5
            motor.off()
    except Exception as e:
        logger.error(f"Motor control error: {e}")


def _move_motor(motor, direction, duration):
    if motor not in (_motor_a_forward, _motor_a_backward, _motor_b_clockwise, _motor_b_counterclockwise):
        return
    if _motor_a_forward is None or _motor_a_backward is None or _motor_b_clockwise is None or _motor_b_counterclockwise is None:
        return
    _set_motor_direction(motor, direction, _motor_a_enable if motor == _motor_a_forward or motor == _motor_a_backward else _motor_b_enable)
    start_time = time.time()
    while _running and (time.time() - start_time) < duration:
        time.sleep(0.01)


def _read_sensor_data(channel):
    if _spi is None:
        return None
    try:
        adc = _read_mcp3008(channel)
        if adc is None:
            return None
        voltage = adc * 3.3 / 1023.0
        return voltage
    except Exception as e:
        logger.error(f"Sensor reading error on channel {channel}: {e}")
        return None


def _average_sensor_data(sensor_id, num_readings, delay):
    readings = []
    for _ in range(num_readings):
        voltage = _read_sensor_data(sensor_id)
        if voltage is not None:
            readings.append(voltage)
        time.sleep(delay)
    if not readings:
        return None
    return sum(readings) / len(readings)


def _set_threshold(threshold):
    global _sensor_data
    _sensor_data['threshold'] = threshold
    logger.info(f"Threshold set to: {threshold}")


def _set_watering_duration(duration):
    global _sensor_data
    _sensor_data['watering_duration'] = duration
    logger.info(f"Watering duration set to: {duration}")


def _get_sensor_data():
    return _sensor_data


def _water_plant(sensor_id):
    if sensor_id == 'sensor1':
        _move_motor(_motor_a_forward, _motor_a_forward, 5)
        _move_motor(_motor_b_clockwise, _motor_b_clockwise, 5)
    elif sensor_id == 'sensor2':
        _move_motor(_motor_a_backward, _motor_a_backward, 5)
        _move_motor(_motor_b_counterclockwise, _motor_b_counterclockwise, 5)
    else:
        logger.warning(f"Unknown sensor: {sensor_id}")
    _move_motor(_motor_a_forward, _motor_a_forward, 0)
    _move_motor(_motor_b_clockwise, _motor_b_clockwise, 0)
    logger.info(f"Watering {sensor_id} for {int(_sensor_data['watering_duration'])} seconds.")


def _health_check():
    global _last_health_check
    if time.time() - _last_health_check > HEALTH_CHECK_INTERVAL:
        logger.info("Performing health check...")
        if _motor_a_forward is None or _motor_a_backward is None or _motor_b_clockwise is None or _motor_b_counterclockwise is None:
            logger.error("Motor driver not initialized.")
            return False
        if _spi is None:
            logger.error("SPI not initialized.")
            return False
        logger.info("Health check complete.")
        _last_health_check = time.time()
        return True
    return False


def _tcp_server():
    global _sensor_data
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        server_socket.bind(('0.0.0.0', SOCKET_PORT))
        server_socket.listen(5)
        server_socket.settimeout(1.0)
        logger.info(f"TCP server listening on port {SOCKET_PORT}")
        while _running:
            try:
                client_socket, client_address = server_socket.accept()
                logger.info(f"Connection from {client_address}")
                try:
                    data = client_socket.recv(1024).decode('utf-8')
                    logger.info(f"Received: {data}")
                    if 'WATER_PLANT_1' in data:
                        _water_plant('sensor1')
                    elif 'WATER_PLANT_2' in data:
                        _water_plant('sensor2')
                    elif 'GET_SENSOR_DATA' in data:
                        sensor_data = _get_sensor_data()
                        if sensor_data['sensor1'] is not None and sensor_data['sensor2'] is not None:
                            client_socket.sendall(str(sensor_data).encode('utf-8'))
                        else:
                            logger.warning("Sensor data unavailable.")
                            client_socket.sendall(b"Error: Sensor data unavailable.")
                    elif 'SET_THRESHOLD' in data:
                        try:
                            threshold = int(data.split()[-1])
                            _set_threshold(threshold)
                        except ValueError:
                            logger.warning("Invalid threshold value.")
                            client_socket.sendall(b"Error: Invalid threshold value.")
                    elif 'SET_WATERING_DURATION' in data:
                        try:
                            duration = int(data.split()[-1])
                            _set_watering_duration(duration)
                        except ValueError:
                            logger.warning("Invalid duration value.")
                            client_socket.sendall(b"Error: Invalid duration value.")
                    else:
                        client_socket.sendall(b"Error: Invalid command.")
                except socket.timeout:
                    logger.warning("Timeout receiving data.")
                except Exception as e:
                    logger.error(f"Error processing command: {e}")
            except socket.timeout:
                continue
            except Exception as e:
                logger.error(f"Error accepting connection: {e}")
    finally:
        server_socket.close()
    logger.info("TCP server stopped.")


def main():
    global _last_health_check
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    atexit.register(_cleanup)
    _init_gpio()
    _init_spi()
    _last_health_check = time.time()
    _tcp_server()


if __name__ == '__main__':
    main()

