            print(f"Error: Failed to open SPI device {bus}.{device}: {e}", file=sys.stderr)
            raise

    def read_raw_data(self, channel=0):
        """Reads raw 10-bit data from the specified channel (0-7)."""
        if not 0 <= channel <= 7:
            raise ValueError("Channel must be between 0 and 7")
        try:
            # MCP3002 command: start bit (1), single-ended mode (1), channel bits (3)
            # Byte 1: 0x01 (start), 0x80 (single-ended) | (channel << 4)
            # Byte 2: 0x00 (dummy)
            # Byte 3: 0x00 (dummy)
            response = self.spi.xfer2([0x01, (0x80 | (channel << 4)), 0x00])
            # response[0] is ignored, response[1] low 2 bits + response[2] = 10-bit result
            raw_data = ((response[1] & 0x03) << 8) | response[2]
            return raw_data
        except (OSError, IOError) as e:
            print(f"Error: SPI read failed on channel {channel}: {e}", file=sys.stderr)
            raise

    def convert_to_weight(self, raw_data):
        """Converts raw 10-bit ADC value to weight in kilograms."""
        # Map 0-1023 to 0-2.45 kg (adjust per sensor)
        weight = raw_data * 2.45 / 1023.0
        return weight

    def close(self):
        """Closes the SPI device."""
        if self.spi is not None:
            try:
                self.spi.close()
            except (OSError, IOError) as e:
                print(f"Warning: Error closing SPI device: {e}", file=sys.stderr)
            finally:
                self.spi = None


def main():
    """Main loop: read weight every 0.5 s and print."""
    reader = None
    try:
        reader = LoadCellReader(bus=0, device=0, max_speed_hz=50000, mode=0, bits=8)
        print("Load cell reader started. Press Ctrl+C to stop.")

        while True:
            try:
                raw_data = reader.read_raw_data(channel=0)
                weight = reader.convert_to_weight(raw_data)
                print(f"Weight: {weight:.2f} kg")
            except (OSError, IOError) as e:
                print(f"Warning: Read error: {e}", file=sys.stderr)
            time.sleep(0.5)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    except Exception as e:
        print(f"Fatal error: {e}", file=sys.stderr)
    finally:
        if reader is not None:
            reader.close()
        print("SPI device closed. Exiting.")


if __name__ == "__main__":
    def signal_handler(signum, frame):
        print(f"\nReceived signal {signum}, shutting down...")
        sys.exit(0)

    signal.signal(signal.SIGTERM, signal_handler)
    main()

