import time
import signal
import sys
import smbus2

# Constants
I2C_BUS = 1
ADS1115_ADDRESS = 0x01
ADS1115_CONVERSION_REGISTER = 0x00
ADS1115_CONFIG_REGISTER = 0x01
ADS1115_CONFIG_BASE = {
    0: 0x8000,  # AIN0 vs GND
    1: 0x4000,  # AIN1 vs GND
    2: 0x2000,  # AIN2 vs GND
    3: 0x1000,  # AIN3 vs GND
}
NUM_CHANNELS = 4
CONVERSION_DELAY = 0.01  # 10 ms
POLL_INTERVAL = 1.0      # 1 s
PERCENTAGE_THRESHOLD = 1.0

running = True
i2c_bus = None


def signal_handler(signum, frame):
    global running
    running = False


def initialize_i2c():
    global i2c_bus
    try:
        i2c_bus = smbus2.SMBus(I2C_BUS)
        return True
    except FileNotFoundError:
        print(f"Error: I2C bus {I2C_BUS} not found. Enable I2C via raspi-config.")
        return False
    except PermissionError:
        print(f"Error: Permission denied on I2C bus {I2C_BUS}. Run as root or add user to i2c group.")
        return False
    except Exception as e:
        print(f"Error initializing I2C bus {I2C_BUS}: {e}")
        return False


def configure_ads1115(channel):
    config = ADS1115_CONFIG_BASE.get(channel, 0x0000)
    try:
        i2c_bus.write_word_data(ADS1115_ADDRESS, ADS1115_CONFIG_REGISTER, config)
    except OSError as e:
        print(f"Error configuring ADS1115 channel {channel}: {e}")
        return False
    return True


def read_ads1115(channel):
    if not configure_ads1115(channel):
        return None
    try:
        i2c_bus.write_byte_data(ADS1115_ADDRESS, ADS1115_CONFIG_REGISTER, 0x8000 | ADS1115_CONFIG_BASE[channel])
        time.sleep(CONVERSION_DELAY)
        raw = i2c_bus.read_word_data(ADS1115_ADDRESS, ADS1115_CONVERSION_REGISTER)
        # smbus2 reads little-endian; ADS1115 is big-endian
        raw = ((raw << 8) & 0xFFFF) | ((raw >> 8) & 0xFFFF)
        return raw
    except OSError as e:
        print(f"Error reading ADS1115 channel {channel}: {e}")
        return None


def calculate_voltage(raw):
    if raw is None:
        return None
    # ADS1115: 16-bit two's complement, signed
    if raw & 0x8000:
        raw = raw - 0x10000
    return raw * 4.096 / 32768.0


def calculate_percentage(voltage):
    if voltage is None:
        return None
    if voltage <= 0:
        return None
    return ((voltage - 3.0) / (4.096 - 3.0)) * 100.0


def cleanup():
    global i2c_bus
    if i2c_bus is not None:
        try:
            i2c_bus.close()
        except Exception:
            pass
        i2c_bus = None


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not initialize_i2c():
        sys.exit(1)

    previous_percentage = None

    try:
        while running:
            for channel in range(NUM_CHANNELS):
                if not running:
                    break
                raw = read_ads1115(channel)
                voltage = calculate_voltage(raw)
                percentage = calculate_percentage(voltage)

                if voltage is not None and percentage is not None:
                    if previous_percentage is None or abs(percentage - previous_percentage) > PERCENTAGE_THRESHOLD:
                        print(f"Battery Voltage: {voltage:.2f} V | Charge: {percentage:.2f}%")
                        previous_percentage = percentage

            time.sleep(POLL_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

