import smbus
import time
import signal
import sys

# ADS1115 constants
I2C_BUS = 1
ADS1115_ADDR = 0x01
REG_CONVERSION = 0x00
REG_CONFIG = 0x01

# Config register bit fields
OS_START = 0x8000
MUX_BASE = 0x4000
FSR_4_096V = 0x0200
MODE_SINGLE = 0x0100
DR_128SPS = 0x0080
COMP_QUE_DISABLE = 0x0003

# Timing
CONV_TIMEOUT_S = 0.1
SAMPLE_INTERVAL_S = 0.05

# Global handle for cleanup
_bus = None
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _write_config(bus, config):
    bus.write_word_data(ADS1115_ADDR, REG_CONFIG, config)


def _read_conversion(bus):
    return bus.read_word_data(ADS1115_ADDR, REG_CONVERSION)


def _read_channel(bus, channel):
    if not 0 <= channel <= 3:
        raise ValueError(f"Invalid channel {channel}; must be 0-3")
    _write_config(bus, OS_START | (channel << 12) | FSR_4_096V | MODE_SINGLE | DR_128SPS | COMP_QUE_DISABLE)
    deadline = time.monotonic() + CONV_TIMEOUT_S
    while True:
        status = _read_conversion(bus)
        if status & OS_START:
            break
        if time.monotonic() > deadline:
            raise TimeoutError(f"Conversion timeout on channel {channel}")
        time.sleep(0.001)
    return _read_conversion(bus)


def main():
    global _bus
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _bus = smbus.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                values = [_read_channel(_bus, ch) for ch in range(4)]
                print(" ".join(f"{v:6d}" for v in values))
            except TimeoutError as e:
                print(f"Error: {e}", file=sys.stderr)
            except OSError as e:
                print(f"Error: I2C bus error: {e}", file=sys.stderr)
            time.sleep(SAMPLE_INTERVAL_S)
    finally:
        if _bus is not None:
            _bus.close()


if __name__ == "__main__":
    main()

