import time
import signal
import sys
import board
import busio
import adafruit_max30102

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
LOG_FILE = 'heart_rate_log.txt'
SAMPLE_INTERVAL = 1.0          # seconds between samples
WINDOW_SECONDS = 4.0           # rolling window for BPM estimation
I2C_RETRY_DELAY = 0.1          # back-off before retrying I2C init

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_i2c = None
_sensor = None


def _handle_sigint(signum, frame):
    """Graceful shutdown on Ctrl-C."""
    global _running
    _running = False


def _format_value(value, label):
    """Defensively format a library value so the program never crashes."""
    if isinstance(value, (int, float)):
        return f'{value:.2f}'
    if isinstance(value, str):
        return f"'{value}'"
    if isinstance(value, bool):
        return 'True' if value else 'False'
    return f'<{value!r}>'


def _init_i2c():
    """Initialize the I2C bus with retry logic."""
    global _i2c
    while _running:
        try:
            _i2c = busio.I2C(board.SCL, board.SDA)
            return True
        except Exception as exc:
            print(f'[WARN] I2C init failed: {exc}', file=sys.stderr)
            time.sleep(I2C_RETRY_DELAY)
    return False


def _init_sensor():
    """Initialize the MAX30102 sensor with retry logic."""
    global _sensor
    while _running:
        try:
            _sensor = adafruit_max30102.MAX30102(_i2c)
            return True
        except Exception as exc:
            print(f'[WARN] Sensor init failed: {exc}', file=sys.stderr)
            time.sleep(I2C_RETRY_DELAY)
    return False


def _read_ir():
    """Read the raw IR sensor value, defensively formatting any _AdaValue."""
    if _sensor is None:
        return None
    try:
        return _format_value(_sensor.ir, 'IR')
    except Exception as exc:
        print(f'[WARN] IR read failed: {exc}', file=sys.stderr)
        return None


def _read_adc():
    """Read the raw ADC value, defensively formatting any _AdaValue."""
    if _sensor is None:
        return None
    try:
        return _format_value(_sensor.adc, 'ADC')
    except Exception as exc:
        print(f'[WARN] ADC read failed: {exc}', file=sys.stderr)
        return None


def _log_and_print(hr):
    """Log and print the heart rate value."""
    ts = time.strftime('%Y-%m-%dT%H:%M:%S')
    log_entry = f'{ts}  HR: {hr} bpm\n'
    print(log_entry, end='')
    try:
        with open(LOG_FILE, 'a') as fh:
            fh.write(log_entry)
    except OSError as exc:
        print(f'[ERROR] Failed to write log file: {exc}', file=sys.stderr)


def _estimate_bpm(ir, adc, window):
    """Estimate BPM from the rolling window of peaks."""
    if adc is None or ir is None:
        return None
    try:
        window.append(adc)
        peaks = [v for v in window if v > 500]
        if not peaks:
            return None
        avg_adc = sum(peaks) / len(peaks)
        # Simple BPM estimate: 60 bpm / window seconds
        return 60.0 / WINDOW_SECONDS if WINDOW_SECONDS > 0 else None
    except Exception as exc:
        print(f'[WARN] BPM estimation failed: {exc}', file=sys.stderr)
        return None


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_sigint)

    if not _init_i2c():
        print('[ERROR] Could not initialize I2C bus. Exiting.', file=sys.stderr)
        sys.exit(1)

    if not _init_sensor():
        print('[ERROR] Could not initialize MAX30102 sensor. Exiting.', file=sys.stderr)
        sys.exit(1)

    window = []
    print('MAX30102 heart-rate monitor started. Press Ctrl-C to stop.')

    try:
        while _running:
            ir = _read_ir()
            adc = _read_adc()
            hr = _estimate_bpm(ir, adc, window)
            _log_and_print(hr)
            time.sleep(SAMPLE_INTERVAL)
    finally:
        print('\nShutting down...')
        if _sensor is not None:
            try:
                _sensor.reset()
            except Exception:
                pass
        if _i2c is not None:
            try:
                _i2c.deinit()
            except Exception:
                pass
        print('Resources released. Bye.')


if __name__ == '__main__':
    main()

