import cv2
import time
import signal
import sys
import atexit

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
CAMERA_INDEX = 0
CAMERA_DEVICE = "/dev/video0"

CASCADE_PATH = "/home/raspberry/RaspPi_CV/haarcascade_frontalface_default.xml"

LED_PIN = 14
BUTTON_PIN = 15
SERVO_PIN = 18

WINDOW_TITLE = "Human Detection"

FACE_WIDTH = 32
FACE_HEIGHT = 32

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_camera = None
_window = None
_led = None
_button = None
_servo = None
_running = True


def _cleanup():
    """Release every resource we own."""
    global _camera, _window, _led, _button, _servo
    if _window is not None:
        try:
            _window.destroy()
        except Exception:
            pass
        _window = None
    if _camera is not None:
        try:
            _camera.release()
        except Exception:
            pass
        _camera = None
    if GPIO is not None:
        try:
            GPIO.cleanup()
        except Exception:
            pass
    _led = None
    _button = None
    _servo = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _init_gpio():
    """Initialise GPIO pins; return True on success, False on failure."""
    if GPIO is None:
        return False
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(SERVO_PIN, GPIO.OUT)
        return True
    except Exception as exc:
        print(f"GPIO init warning: {exc}", file=sys.stderr)
        return False


def _init_camera():
    """Open the camera; return the VideoCapture object or None."""
    try:
        cap = cv2.VideoCapture(CAMERA_INDEX, CAMERA_DEVICE)
        if not cap.isOpened():
            print(f"Error: could not open camera {CAMERA_INDEX} on {CAMERA_DEVICE}",
                  file=sys.stderr)
            return None
        return cap
    except Exception as exc:
        print(f"Error: camera init failed: {exc}", file=sys.stderr)
        return None


def _init_face_detector(cascade_path):
    """Load the Haar cascade; return the classifier or None."""
    try:
        detector = cv2.CascadeClassifier(cascade_path)
        if detector.empty():
            print(f"Error: failed to load cascade classifier from {cascade_path}",
                  file=sys.stderr)
            return None
        return detector
    except Exception as exc:
        print(f"Error: cascade load failed: {exc}", file=sys.stderr)
        return None


def _init_servo(pin):
    """Create a 50 Hz PWM servo driver; return the object or None."""
    if GPIO is None:
        return None
    try:
        GPIO.setup(pin, GPIO.OUT)
        pwm = GPIO.PWM(pin, 50)
        pwm.start(0)
        return pwm
    except Exception as exc:
        print(f"Servo init warning: {exc}", file=sys.stderr)
        return None


def _set_servo_angle(pwm, angle):
    """Drive the servo to *angle* degrees (0-180)."""
    if pwm is None:
        return
    try:
        angle = max(0, min(180, angle))
        pwm.ChangeDutyCycle(angle)
        time.sleep(0.02)
    except Exception as exc:
        print(f"Servo write warning: {exc}", file=sys.stderr)


def _update_servo(pwm, face_center_x):
    """Increment or decrement servo angle based on face position."""
    if pwm is None:
        return
    try:
        if face_center_x > FACE_WIDTH / 2:
            pwm.ChangeDutyCycle(90)
        else:
            pwm.ChangeDutyCycle(0)
        time.sleep(0.02)
    except Exception as exc:
        print(f"Servo update warning: {exc}", file=sys.stderr)


def _process_frame(frame, detector, pwm, led, button):
    """Resize, detect faces, draw rectangles, update GPIO, and display."""
    if frame is None:
        return
    try:
        h0, w0 = frame.shape[:2]
        if h0 == 0 or w0 == 0:
            return
        scale_x = FACE_WIDTH / float(w0)
        scale_y = FACE_HEIGHT / float(h0)
        new_h = max(1, int(scale_y * h0))
        new_w = max(1, int(scale_x * w0))
        frame = cv2.resize(frame, (new_w, new_h))
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        faces = detector.detectMultiScale(gray, 1.3, 5)
        cv2.rectangle(frame, (0, 0), (FACE_WIDTH, FACE_HEIGHT),
                      (255, 0, 0), 2)
        for (x, y, w, h) in faces:
            cv2.rectangle(frame, (x, y), (x + w, y + h),
                          (0, 255, 0), 2)
            face_cx = x + w / 2
            _update_servo(pwm, face_cx)
            if button is not None and button.is_pressed:
                _set_servo_angle(pwm, 90)
            else:
                _set_servo_angle(pwm, 0)
        cv2.imshow(WINDOW_TITLE, frame)
    except Exception as exc:
        print(f"Display error: {exc}", file=sys.stderr)
        try:
            cv2.destroyWindow(WINDOW_TITLE)
        except Exception:
            pass


def main():
    global _camera, _window, _led, _button, _servo

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    atexit.register(_cleanup)

    _led = GPIO if GPIO is not None else None
    _button = GPIO if GPIO is not None else None
    _servo = GPIO if GPIO is not None else None

    if _led is not None:
        try:
            GPIO.output(LED_PIN, GPIO.LOW)
        except Exception:
            pass

    if _button is not None:
        try:
            GPIO.wait_for_edge(BUTTON_PIN, GPIO.RISING, timeout=1000)
        except Exception:
            pass

    detector = _init_face_detector(CASCADE_PATH)
    if detector is None:
        print("Face detection unavailable; continuing without GUI.", file=sys.stderr)

    camera = _init_camera()
    if camera is None:
        print("Camera unavailable; continuing without GUI.", file=sys.stderr)

    pwm = _init_servo(SERVO_PIN)
    if pwm is None:
        print("Servo unavailable; continuing without GPIO control.", file=sys.stderr)

    _window = None
    try:
        _window = cv2.namedWindow(WINDOW_TITLE, cv2.WINDOW_NORMAL)
    except Exception as exc:
        print(f"Window init warning: {exc}", file=sys.stderr)

    try:
        while _running:
            ret, frame = camera.read()
            if not ret or frame is None:
                print("Error: failed to read frame from camera.", file=sys.stderr)
                break
            _process_frame(frame, detector, pwm, _led, _button)
            if _window is not None:
                try:
                    key = cv2.waitKey(1) & 0xFF
                    if key == ord("q"):
                        break
                except Exception:
                    pass
    except KeyboardInterrupt:
        print("Program stopped by user.")
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

