#!/usr/bin/env python3
"""
Wildlife Environmental Monitoring System for Raspberry Pi.

Detects BMP280, BME280, and MS8607 sensors on I2C bus 1, reads them at
a configurable interval, validates readings, stores them in SQLite,
and logs errors.  Config is read from config.txt; missing config is
tolerated gracefully.
"""

import argparse
import datetime
import logging
import os
import signal
import sqlite3
import sys
import time
from typing import Any, Dict, List, Optional

try:
    import smbus2
except ImportError:
    smbus2 = None

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
DEFAULT_CONFIG_FILE = "config.txt"
DEFAULT_SAMPLING_INTERVAL = 60          # seconds — only applies to MS8607
DEFAULT_LOG_FILE = "error.log"
DEFAULT_DATABASE_FILE = "wildlife_data.db"

# BMP280 / BME280 / MS8607 ranges
BMP280_TEMP_MIN = -20.0
BMP280_TEMP_MAX = 50.0
BMP280_PRESS_MIN = 70_000   # Pa
BMP280_PRESS_MAX = 110_000  # Pa
BME280_TEMP_MIN = -20.0
BME280_TEMP_MAX = 50.0
BME280_PRESS_MIN = 70_000  # Pa
BME280_PRESS_MAX = 110_000 # Pa
BME280_HUM_MIN = 0.0
BME280_HUM_MAX = 100.0
MS8607_TEMP_MIN = -40.0
MS8607_TEMP_MAX = 85.0
MS8607_PRESS_MIN = 300_000  # Pa
MS8607_PRESS_MAX = 1_000_000 # Pa
MS8607_HUM_MIN = 0.0
MS8607_HUM_MAX = 100.0

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
_running = True
_db_conn: Optional[sqlite3.Connection] = None


def _signal_handler(signum: int, frame: Any) -> None:
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _init_sensors(sensor_types: List[str]) -> Dict[str, Any]:
    """Initialize sensors; return dict of sensor_name -> sensor_obj."""
    sensors: Dict[str, Any] = {}
    bus = None
    if smbus2 is not None:
        try:
            bus = smbus2.SMBus(1)
        except Exception as exc:
            logging.error("Failed to open I2C bus 1: %s", exc)
            return sensors
    else:
        logging.warning("smbus2 not installed; I2C bus unavailable.")
    for sensor_type in sensor_types:
        if sensor_type == "BMP280":
            try:
                sensors[sensor_type] = {
                    "bus": bus,
                    "address": 0x58,
                    "id": 0x58,
                }
                logging.info("BMP280 initialized at 0x%02X", sensors[sensor_type]["address"])
            except Exception as exc:
                logging.error("BMP280 init failed: %s", exc)
                sensors[sensor_type] = None
        elif sensor_type == "BME280":
            try:
                sensors[sensor_type] = {
                    "bus": bus,
                    "address": 0x76,
                    "id": 0x76,
                }
                logging.info("BME280 initialized at 0x%02X", sensors[sensor_type]["address"])
            except Exception as exc:
                logging.error("BME280 init failed: %s", exc)
                sensors[sensor_type] = None
        elif sensor_type == "MS8607":
            try:
                sensors[sensor_type] = {
                    "bus": bus,
                    "address": 0x76,
                    "id": 0x76,
                }
                logging.info("MS8607 initialized at 0x%02X", sensors[sensor_type]["address"])
            except Exception as exc:
                logging.error("MS8607 init failed: %s", exc)
                sensors[sensor_type] = None
        else:
            logging.warning("Unknown sensor type: %s", sensor_type)
    return sensors


def _read_sensor(sensor: Dict[str, Any], sensor_type: str) -> Optional[tuple]:
    """Read one sample from a sensor; return (pressure, temperature, humidity)."""
    if sensor_type == "BMP280":
        try:
            # Read 6 bytes: pressure (20-bit), temperature (16-bit), optional
            data = sensor["bus"].read_i2c_block_data(sensor["address"], 0x88, 6)
            raw_p = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
            raw_t = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4)
            pressure = raw_p / 256.0
            temperature = raw_t / 256.0
            return (pressure, temperature, None)
        except Exception as exc:
            logging.error("BMP280 read error: %s", exc)
            return None
    elif sensor_type == "BME280":
        try:
            # Read 8 bytes: pressure (20-bit), temperature (16-bit), humidity (16-bit)
            data = sensor["bus"].read_i2c_block_data(sensor["address"], 0x88, 8)
            raw_p = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
            raw_t = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4)
            raw_h = (data[6] << 8) | data[7]
            pressure = raw_p / 256.0
            temperature = raw_t / 256.0
            humidity = raw_h / 65536.0
            return (pressure, temperature, humidity)
        except Exception as exc:
            logging.error("BME280 read error: %s", exc)
            return None
    elif sensor_type == "MS8607":
        try:
            # Read 6 bytes: pressure (20-bit), temperature (16-bit), humidity (16-bit)
            data = sensor["bus"].read_i2c_block_data(sensor["address"], 0x88, 6)
            raw_p = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
            raw_t = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4)
            raw_h = (data[6] << 8) | data[7]
            pressure = raw_p / 256.0
            temperature = raw_t / 256.0
            humidity = raw_h / 65536.0
            return (pressure, temperature, humidity)
        except Exception as exc:
            logging.error("MS8607 read error: %s", exc)
            return None
    return None


def _validate_data(sensor_type: str, pressure: float, temperature: float,
                    humidity: Optional[float]) -> bool:
    """Return True if readings are within valid ranges."""
    if sensor_type == "BMP280":
        if not (BMP280_PRESS_MIN <= pressure <= BMP280_PRESS_MAX):
            logging.warning("BMP280 pressure out of range: %.2f Pa", pressure)
            return False
        if not (BMP280_TEMP_MIN <= temperature <= BMP280_TEMP_MAX):
            logging.warning("BMP280 temperature out of range: %.2f C", temperature)
            return False
    elif sensor_type == "BME280":
        if not (BME280_PRESS_MIN <= pressure <= BME280_PRESS_MAX):
            logging.warning("BME280 pressure out of range: %.2f Pa", pressure)
            return False
        if not (BME280_TEMP_MIN <= temperature <= BME280_TEMP_MAX):
            logging.warning("BME280 temperature out of range: %.2f C", temperature)
            return False
        if not (BME280_HUM_MIN <= humidity <= BME280_HUM_MAX):
            logging.warning("BME280 humidity out of range: %.2f %%", humidity)
            return False
    elif sensor_type == "MS8607":
        if not (MS8607_PRESS_MIN <= pressure <= MS8607_PRESS_MAX):
            logging.warning("MS8607 pressure out of range: %.2f Pa", pressure)
            return False
        if not (MS8607_TEMP_MIN <= temperature <= MS8607_TEMP_MAX):
            logging.warning("MS8607 temperature out of range: %.2f C", temperature)
            return False
        if not (MS8607_HUM_MIN <= humidity <= MS8607_HUM_MAX):
            logging.warning("MS8607 humidity out of range: %.2f %%", humidity)
            return False
    return True


def _store_data(db_conn: sqlite3.Connection, sensor_type: str,
                sensor_id: int, pressure: float, temperature: float,
                humidity: Optional[float]) -> None:
    """Insert a validated reading into sensor_data table."""
    try:
        cursor = db_conn.cursor()
        cursor.execute(
            "INSERT INTO sensor_data (timestamp, sensor_type, sensor_id, pressure_pa, "
            "temperature_c, humidity_percent) "
            "VALUES (?, ?, ?, ?, ?, ?)",
            (datetime.datetime.now().isoformat(), sensor_type, sensor_id,
             pressure, temperature, humidity),
        )
        db_conn.commit()
    except sqlite3.Error as exc:
        logging.error("Database insert error for %s: %s", sensor_type, exc)


def _load_config(config_file: str) -> Dict[str, Any]:
    """Parse config.txt; return dict of sensor_type -> {address, id, interval}."""
    config: Dict[str, Any] = {}
    if not os.path.isfile(config_file):
        logging.warning("Config file not found: %s", config_file)
        return config
    try:
        with open(config_file, "r") as fh:
            for line in fh:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if "=" not in line:
                    continue
                key, _, value = line.partition("=")
                key = key.strip()
                value = value.strip()
                if key in ("Sensor1_Type", "Sensor2_Type", "Sensor3_Type"):
                    config[key] = {"type": key}
                elif key in ("Sensor1_Address", "Sensor2_Address", "Sensor3_Address"):
                    config[key] = {"address": int(value, 0)}
                elif key in ("Sensor1_ID", "Sensor2_ID", "Sensor3_ID"):
                    config[key] = {"id": int(value)}
                elif key == "Sampling_Interval_Seconds":
                    config[key] = {"interval": int(value)}
                else:
                    logging.warning("Unknown config key: %s", key)
    except Exception as exc:
        logging.error("Error reading config file: %s", exc)
    return config


def _init_database(db_file: str) -> sqlite3.Connection:
    """Open SQLite database and create table if needed."""
    try:
        conn = sqlite3.connect(db_file)
        conn.execute(
            "CREATE TABLE IF NOT EXISTS sensor_data ("
            "timestamp TEXT NOT NULL, "
            "sensor_type TEXT NOT NULL, "
            "sensor_id INTEGER NOT NULL, "
            "pressure_pa REAL, "
            "temperature_c REAL, "
            "humidity_percent REAL) "
        )
        conn.commit()
        return conn
    except sqlite3.Error as exc:
        logging.error("Database init error: %s", exc)
        raise


def _cleanup() -> None:
    """Close database connection on exit."""
    global _db_conn
    if _db_conn is not None:
        try:
            _db_conn.close()
        except sqlite3.Error as exc:
            logging.error("Error closing database: %s", exc)
        finally:
            _db_conn = None


def main() -> int:
    global _db_conn

    parser = argparse.ArgumentParser(description="Wildlife Environmental Monitoring")
    parser.add_argument("--config", default=DEFAULT_CONFIG_FILE)
    parser.add_argument("--log", default=DEFAULT_LOG_FILE)
    parser.add_argument("--db", default=DEFAULT_DATABASE_FILE)
    args = parser.parse_args()

    logging.basicConfig(
        filename=args.log,
        level=logging.ERROR,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.info("Program started")

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = _load_config(args.config)
    sensor_types = set(config.keys())
    sensors = _init_sensors(sensor_types)
    _db_conn = _init_database(args.db)

    try:
        while _running:
            for sensor_type in sensor_types:
                sensor = sensors.get(sensor_type)
                if sensor is None:
                    continue
                sensor_id = config[sensor_type]["id"]
                interval = config[sensor_type]["interval"]
                if interval <= 0:
                    logging.warning("Invalid interval for %s: %s", sensor_type, interval)
                    continue
                if sensor_type in ("BMP280", "BME280"):
                    pressure, temperature, humidity = _read_sensor(sensor, sensor_type)
                else:
                    pressure, temperature, humidity = _read_sensor(sensor, sensor_type)
                if pressure is None:
                    logging.error("Sensor %s read failed", sensor_type)
                    continue
                if _validate_data(sensor_type, pressure, temperature, humidity):
                    _store_data(_db_conn, sensor_type, sensor_id, pressure, temperature, humidity)
                else:
                    logging.warning("Sensor %s invalid data: pressure=%.2f Pa, "
                                    "temperature=%.2f C, humidity=%.2f %%",
                                    sensor_type, pressure, temperature, humidity)
            if _running:
                time.sleep(interval)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user")
    except Exception as exc:
        logging.error("Unexpected error: %s", exc)
        return 1
    finally:
        _cleanup()
        logging.info("Program finished")
    return 0


if __name__ == "__main__":
    sys.exit(main())

