import time
import signal
import sys
import RPi.GPIO as GPIO

I2C_BUS = 1
PCF8574_ADDR = 0x27
SENSOR_BITS = 8
SENSOR_PIN = 17
DEBOUNCE_MS = 50

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _read_sensors(i2c, addr):
    """Read one byte from the PCF8574 and return a list of 8 bit-level readings."""
    try:
        data = i2c.read_i2c_block_data(addr, 0x00, 1)
    except OSError as exc:
        print(f"I2C read error: {exc}", file=sys.stderr)
        return None
    if len(data) < 1:
        return None
    return [bool(data[0] & (1 << i)) for i in range(SENSOR_BITS)]

def _sensor_callback(channel):
    """Falling-edge interrupt handler with 50 ms debounce."""
    time.sleep(DEBOUNCE_MS / 1000.0)
    if not _running:
        return
    readings = _read_sensors(i2c, PCF8574_ADDR)
    if readings is None:
        return
    for bit_num, reading in enumerate(readings):
        if reading:
            print(f"Obstacle detected by sensor {bit_num}")

def main():
    global i2c
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.add_event_detect(SENSOR_PIN, GPIO.FALLING, callback=_sensor_callback, bouncetime=DEBOUNCE_MS)
    except Exception as exc:
        print(f"GPIO initialization error: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        i2c = GPIO.I2C()
        i2c.set_mode(I2C_BUS, GPIO.I2C_MODE)
        i2c.set_clock_freq(100000)
    except Exception as exc:
        print(f"I2C initialization error: {exc}", file=sys.stderr)
        GPIO.cleanup()
        sys.exit(1)

    print("PCF8574 proximity sensor monitor started. Press Ctrl+C to exit.")
    try:
        while _running:
            time.sleep(1)
    except KeyboardInterrupt:
        pass
    finally:
        try:
            i2c.deinit()
        except Exception:
            pass
        GPIO.cleanup()
        print("Program terminated.")

if __name__ == "__main__":
    main()

