import signal
import sys
import time
from typing import Optional

import serial

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
LOG_FILE = "distance_log.txt"
READ_INTERVAL = 1.0  # seconds between readings

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def open_serial_port(port: str, baud: int) -> Optional[serial.Serial]:
    try:
        return serial.Serial(
            port=port,
            baudrate=baud,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1.0,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {port}: {exc}", file=sys.stderr)
        return None


def read_distance(serial_port: serial.Serial) -> Optional[float]:
    try:
        raw = serial_port.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None

    if not raw:
        return None

    line = raw.decode("ascii", errors="replace").strip()
    if not line:
        return None

    try:
        return float(line)
    except ValueError:
        print(f"Warning: malformed data (not a float): {line!r}", file=sys.stderr)
        return None


def log_distance(distance_cm: float, log_file: str) -> None:
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp},{distance_cm}\n"
    try:
        with open(log_file, "a", encoding="utf-8") as fh:
            fh.write(log_entry)
            fh.flush()
    except OSError as exc:
        print(f"Error writing to log file: {exc}", file=sys.stderr)
    print(f"Timestamp: {timestamp}, Distance: {distance_cm} cm")


def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    serial_connection = open_serial_port(SERIAL_PORT, BAUD_RATE)
    if serial_connection is None:
        return 1

    try:
        while _running:
            distance = read_distance(serial_connection)
            if distance is not None:
                log_distance(distance, LOG_FILE)
            time.sleep(READ_INTERVAL)
    finally:
        try:
            serial_connection.close()
        except Exception:
            pass
        print("Serial port closed. Exiting.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

