import cv2
import numpy as np
import serial
import serial.tools.list_ports
import signal
import sys

# Constants
CAMERA_INDEX = 0
ROI_SIZE = 10
MIN_CONTOUR_AREA = 500
SERIAL_PORT_PREFERRED = '/dev/ttyACM0'
SERIAL_PORT_FALLBACK = '/dev/ttyUSB0'
SERIAL_BAUDRATE = 9600
DEAD_ZONE = 50

# Global state
cap = None
serial_port = None
running = True


def signal_handler(signum, frame):
    global running
    running = False


def initialize_camera():
    global cap
    cap = cv2.VideoCapture(CAMERA_INDEX)
    if not cap.isOpened():
        print("Error: Could not open camera.")
        return False
    return True


def initialize_serial(port, baudrate):
    global serial_port
    try:
        serial_port = serial.Serial(port, baudrate, timeout=1)
        print(f"Serial port {port} opened at {baudrate} baud.")
        return True
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}")
        serial_port = None
        return False


def get_available_serial_ports():
    return [p.device for p in serial.tools.list_ports.comports()]


def get_preferred_serial_port():
    available = get_available_serial_ports()
    if available:
        print(f"Available serial ports: {available}")
        return SERIAL_PORT_PREFERRED
    return SERIAL_PORT_FALLBACK


def draw_rectangle(frame, x, y, w, h, color, thickness):
    cv2.rectangle(frame, (x, y), (x + w, y + h), color, thickness)


def classify_ball_position(x, y, cx, cy):
    if cx > x + w and cy > y + h:
        return "1"  # Bottom Right
    if cx > x + w and cy < y:
        return "2"  # Top Right
    if cx < x and cy > y + h:
        return "3"  # Bottom Left
    if cx < x and cy < y:
        return "4"  # Top Left
    return "5"  # Center


def main():
    global running, cap, serial_port

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not initialize_camera():
        sys.exit(1)

    serial_port = initialize_serial(get_preferred_serial_port(), SERIAL_BAUDRATE)

    try:
        while running:
            ret, frame = cap.read()
            if not ret:
                print("Error: Could not read frame from camera.")
                break

            hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)

            if cv2.waitKey(1) & 0xFF == ord('s'):
                h_min = 0
                h_max = 180
                s_min = 100
                s_max = 255
                v_min = 100
                v_max = 255

                cx = int(ROI_SIZE * frame.shape[1] / 2) - ROI_SIZE // 2
                cy = int(ROI_SIZE * frame.shape[0] / 2) - ROI_SIZE // 2

                mask = cv2.inRange(hsv, np.array([h_min, s_min, v_min]), np.array([h_max, s_max, v_max]))
                contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

                for contour in contours:
                    if cv2.contourArea(contour) > MIN_CONTOUR_AREA:
                        x, y, w, h = cv2.boundingRect(contour)
                        draw_rectangle(frame, x, y, w, h, (255, 0, 0), 2)
                        ball_x = x + w // 2
                        ball_y = y + h // 2

                        if ball_x > cx + DEAD_ZONE and ball_y > cy + DEAD_ZONE:
                            ball_x, ball_y = cx, cy
                        if ball_x < cx - DEAD_ZONE and ball_y > cy + DEAD_ZONE:
                            ball_x, ball_y = cx, cy
                        if ball_x > cx + DEAD_ZONE and ball_y < cy - DEAD_ZONE:
                            ball_x, ball_y = cx, cy
                        if ball_x < cx - DEAD_ZONE and ball_y < cy - DEAD_ZONE:
                            ball_x, ball_y = cx, cy

                        position = classify_ball_position(ball_x, ball_y, cx, cy)
                        try:
                            if serial_port and serial_port.is_open:
                                serial_port.write(position.encode('utf-8'))
                        except serial.SerialException as e:
                            print(f"Error writing to serial port: {e}")

            cv2.imshow("Frame", frame)

            if cv2.waitKey(1) & 0xFF == 27:
                break

    except Exception as e:
        print(f"An error occurred: {e}")

    finally:
        if cap is not None and cap.isOpened():
            cap.release()
        if serial_port is not None and serial_port.is_open:
            serial_port.close()
        cv2.destroyAllWindows()


if __name__ == "__main__":
    main()

