import json
import logging
import signal
import statistics
import sys
import time
from typing import List, Optional, Tuple

try:
    import RPi.GPIO as GPIO
except Exception:  # pragma: no cover - hardware-specific
    GPIO = None

DEFAULT_CONFIG = {
    "gpio": {
        "trigger1": 17,
        "trigger2": 22,
        "trigger3": 24,
        "echo1": 18,
        "echo2": 23,
        "echo3": 25,
    },
    "water_level": {
        "offset": 0.0,
        "max_distance": 200.0,
        "low": 10.0,
        "high": 180.0,
        "alert_repeat_delay": 60,
        "log_file": "water_level.log",
    },
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file: str) -> dict:
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logging.warning(f"Config file '{config_file}' not found; using defaults.")
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in '{config_file}': {e}; using defaults.")
    return DEFAULT_CONFIG


def setup_gpio(config: dict) -> bool:
    if GPIO is None:
        logging.warning("RPi.GPIO not available; running in mock mode.")
        return False
    try:
        GPIO.setmode(GPIO.BCM)
        for trig, echo in config["gpio"].items():
            GPIO.setup(echo, GPIO.IN)
            GPIO.setup(trig, GPIO.OUT)
            GPIO.output(trig, GPIO.LOW)
        logging.info("GPIO initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"GPIO setup failed: {e}")
        return False


def read_distance(trigger: int, echo: int, timeout: float = 0.05) -> Optional[float]:
    if GPIO is None:
        return None
    try:
        GPIO.output(trigger, GPIO.HIGH)
        time.sleep(0.00001)
        GPIO.output(trigger, GPIO.LOW)

        deadline = time.time() + timeout
        while GPIO.input(echo) == GPIO.LOW:
            if time.time() > deadline:
                return None
        start = time.time()

        deadline = time.time() + timeout
        while GPIO.input(echo) == GPIO.HIGH:
            if time.time() > deadline:
                return None
        end = time.time()

        elapsed = end - start
        distance = (elapsed * 34300) / 2
        return distance
    except Exception as e:
        logging.error(f"Error reading distance from trigger {trigger}, echo {echo}: {e}")
        return None


def calculate_median_distance(
    distances: List[Optional[float]], max_distance: float
) -> Optional[float]:
    valid = [d for d in distances if d is not None]
    if not valid:
        return None
    return statistics.median(valid)


def check_water_level(
    median_distance: Optional[float],
    config: dict,
) -> Tuple[bool, bool, bool]:
    low_threshold = config["water_level"]["low"]
    high_threshold = config["water_level"]["high"]
    alert_repeat_delay = config["water_level"]["alert_repeat_delay"]
    log_file = config["water_level"]["log_file"]

    if median_distance is None:
        logging.warning("No valid distance reading; water level check skipped.")
        return False, False, False

    if median_distance < low_threshold:
        logging.warning(
            f"Water level LOW: {median_distance:.2f} cm (threshold {low_threshold} cm)"
        )
        return True, False, False
    elif median_distance > high_threshold:
        logging.warning(
            f"Water level HIGH: {median_distance:.2f} cm (threshold {high_threshold} cm)"
        )
        return False, True, False
    else:
        return False, False, False


def log_alert(
    timestamp: str,
    message: str,
    log_file: str,
) -> None:
    try:
        with open(log_file, "a") as f:
            f.write(f"{timestamp} - {message}\n")
    except Exception as e:
        logging.error(f"Failed to write to log file '{log_file}': {e}")


def cleanup_gpio() -> None:
    if GPIO is not None:
        try:
            GPIO.cleanup()
            logging.info("GPIO cleaned up.")
        except Exception as e:
            logging.error(f"GPIO cleanup error: {e}")


def main() -> int:
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = load_config("config.json")
    config = {**DEFAULT_CONFIG, **config}

    if not setup_gpio(config):
        logging.error("GPIO initialization failed; exiting.")
        return 0

    trigger_pins = config["gpio"].values()
    trigger_pins_set = set(trigger_pins)
    trigger_pins_missing = set(trigger_pins) - trigger_pins_set
    echo_pins = config["gpio"].values()
    echo_pins_set = set(echo_pins)
    echo_pins_missing = set(echo_pins) - echo_pins_set

    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )

    last_alert_times: dict = {}
    last_error_times: dict = {}

    try:
        while _running:
            distances = []
            for i, trigger in enumerate(trigger_pins):
                if trigger in trigger_pins_set:
                    distance = read_distance(trigger, echo_pins[i])
                    if distance is not None:
                        distances.append(distance)
                    else:
                        last_error_times[trigger] = time.time()
                        if time.time() - last_error_times[trigger] > 5:
                            logging.error(
                                f"Sensor {trigger} failed for 5 consecutive polls; excluded."
                            )
                            trigger_pins_set.remove(trigger)
                            echo_pins_set.remove(echo_pins[i])
                            logging.warning(
                                f"Sensor {trigger} excluded due to consecutive errors."
                            )
                else:
                    logging.warning(f"Trigger pin {trigger} not configured.")

            if not distances:
                logging.warning("No valid distance readings from any sensor.")
                time.sleep(5)
                continue

            median_distance = calculate_median_distance(distances, config["water_level"]["max_distance"])
            if median_distance is None:
                logging.warning("Cannot calculate median due to no valid readings.")
                time.sleep(5)
                continue

            low_alert, high_alert, alert_repeat = check_water_level(
                median_distance, config
            )

            if low_alert:
                logging.info(
                    f"ALERT: Water level LOW - {median_distance:.2f} cm"
                )
                log_alert(
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    f"ALERT: Water level LOW - {median_distance:.2f} cm",
                    config["water_level"]["log_file"],
                )
                last_alert_times["low"] = time.time()
            elif high_alert:
                logging.info(
                    f"ALERT: Water level HIGH - {median_distance:.2f} cm"
                )
                log_alert(
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    f"ALERT: Water level HIGH - {median_distance:.2f} cm",
                    config["water_level"]["log_file"],
                )
                last_alert_times["high"] = time.time()
            elif alert_repeat:
                logging.info(
                    f"ALERT: Water level LOW (repeat) - {median_distance:.2f} cm"
                )
                log_alert(
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    f"ALERT: Water level LOW (repeat) - {median_distance:.2f} cm",
                    config["water_level"]["log_file"],
                )
                last_alert_times["repeat"] = time.time()

            time.sleep(5)

    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
        return 0
    finally:
        cleanup_gpio()
        logging.info("Program terminated.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

