    )

    last_alert_times: dict = {}
    last_error_times: dict = {}

    try:
        while _running:
            distances = []
            for i, trigger in enumerate(trigger_pins):
                if trigger in trigger_pins_set:
                    distance = read_distance(trigger, echo_pins[i])
                    if distance is not None:
                        distances.append(distance)
                    else:
