# Constants for GPIO pins
INPUT_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]
POLL_INTERVAL = 0.05

# Global state
output_state = False
last_toggle_state = False
running = True


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False


def setup_gpio():
    """Initialize GPIO pins with error handling."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for pin in INPUT_PINS + OUTPUT_PINS:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.output(OUTPUT_PINS[0], GPIO.LOW)
        GPIO.output(OUTPUT_PINS[1], GPIO.LOW)
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        GPIO.cleanup()
        sys.exit(1)


def read_input(pin):
    """Read a GPIO input with error handling."""
    try:
        return GPIO.input(pin)
    except Exception as e:
        print(f"Error reading GPIO {pin}: {e}")
        return None


def set_output(pin, state):
    """Set a GPIO output with error handling."""
    try:
        GPIO.output(pin, state)
    except Exception as e:
        print(f"Error setting GPIO {pin} to {state}: {e}")


def main():
    """Main loop for GPIO polling and output control."""
    global output_state, last_toggle_state

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    setup_gpio()

    try:
        while running:
            input_states = [read_input(pin) for pin in INPUT_PINS]

            if input_states[0] is None:
                continue

            if input_states[0] == GPIO.LOW:
                set_output(OUTPUT_PINS[0], GPIO.HIGH)
                output_state = True
            elif input_states[0] == GPIO.HIGH:
                set_output(OUTPUT_PINS[0], GPIO.LOW)
                output_state = False

            if input_states[1] is None:
                continue

            if input_states[1] == GPIO.LOW:
                if output_state == last_toggle_state:
                    set_output(OUTPUT_PINS[1], not GPIO.HIGH)
                    last_toggle_state = not last_toggle_state
                else:
                    set_output(OUTPUT_PINS[1], GPIO.HIGH)
                    last_toggle_state = True
            elif input_states[1] == GPIO.HIGH:
                set_output(OUTPUT_PINS[1], GPIO.LOW)
                last_toggle_state = False

            time.sleep(POLL_INTERVAL)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

