import sys
import time
import signal
import os
import select
import logging
import threading

import cv2
import numpy as np
import RPi.GPIO as GPIO
import pyaudio

try:
    import config
except ImportError:
    print("Error: config.py not found. Please create it with the necessary configurations.")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

BUTTON_PIN = 5
LOCK_PIN = 17
CAMERA_INDEX = 0
CAMERA_GETTER = cv2.CAP_V4L2

running = True
camera = None
audio = None
button_pin = None
lock_pin = None


def signal_handler(signum, frame):
    global running
    logger.info(f"Signal {signum} received, shutting down...")
    running = False


def cleanup():
    global camera, audio, button_pin, lock_pin
    logger.info("Cleaning up resources...")
    if camera is not None:
        try:
            camera.release()
        except Exception as e:
            logger.error(f"Error releasing camera: {e}")
        camera = None
    if audio is not None:
        try:
            audio.terminate()
        except Exception as e:
            logger.error(f"Error terminating audio: {e}")
        audio = None
    if button_pin is not None:
        try:
            GPIO.output(button_pin, GPIO.HIGH)
            GPIO.cleanup(button_pin)
        except Exception as e:
            logger.error(f"Error cleaning up button pin: {e}")
        button_pin = None
    if lock_pin is not None:
        try:
            GPIO.output(lock_pin, GPIO.HIGH)
            GPIO.cleanup(lock_pin)
        except Exception as e:
            logger.error(f"Error cleaning up lock pin: {e}")
        lock_pin = None
    logger.info("Cleanup complete.")


def load_model():
    if not os.path.exists(config.TRAINING_FILE):
        logger.error(f"Training file not found: {config.TRAINING_FILE}")
        sys.exit(1)
    try:
        logger.info("Loading face recognition model...")
        model = cv2.face.EigenFaceRecognizer_create()
        model.read(config.TRAINING_FILE)
        logger.info("Face recognition model loaded successfully.")
        return model
    except Exception as e:
        logger.error(f"Error loading face recognition model: {e}")
        sys.exit(1)


def initialize_camera():
    global camera
    try:
        camera = cv2.VideoCapture(CAMERA_GETTER, CAMERA_INDEX)
        if not camera.isOpened():
            raise IOError("Cannot open webcam")
        logger.info("Camera initialized successfully.")
        return True
    except Exception as e:
        logger.error(f"Error initializing camera: {e}")
        return False


def initialize_audio():
    global audio
    try:
        audio = pyaudio.PyAudio()
        audio.set_blocksize(1024)
        audio.set_input_buffer(audio.get_input_buffer())
        audio.set_output_buffer(audio.get_output_buffer())
        audio.start_stream()
        logger.info("Audio initialized successfully.")
        return True
    except Exception as e:
        logger.error(f"Error initializing audio: {e}")
        return False


def initialize_gpio():
    global button_pin, lock_pin
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(LOCK_PIN, GPIO.OUT, initial=GPIO.HIGH)
        logger.info("GPIO initialized successfully.")
        return True
    except Exception as e:
        logger.error(f"Error initializing GPIO: {e}")
        return False


def capture_image():
    global camera
    if camera is None:
        logger.error("Camera not initialized.")
        return None
    try:
        ret, frame = camera.read()
        if not ret or frame is None:
            logger.error("Failed to capture image from camera.")
            return None
        return frame
    except Exception as e:
        logger.error(f"Error capturing image: {e}")
        return None


def detect_single(image):
    try:
        gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
        face_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_frontalface_default.xml')
        if face_cascade.empty():
            raise IOError("Failed to load face cascade classifier.")
        faces = face_cascade.detectMultiScale(gray, 1.3, 5)
        if len(faces) == 1:
            return faces[0]
        return None
    except Exception as e:
        logger.error(f"Error detecting single face: {e}")
        return None


def crop_and_resize(image, x, y, w, h):
    try:
        cropped = image[y:y + h, x:x + w]
        resized = cv2.resize(cropped, (160, 160))
        return resized
    except Exception as e:
        logger.error(f"Error cropping and resizing face: {e}")
        return None


def recognize_face(image, model):
    try:
        gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
        face_coords = detect_single(gray)
        if face_coords is None:
            return None, None
        x, y, w, h = face_coords
        cropped = gray[y:y + h, x:x + w]
        label, confidence = model.predict(cropped)
        return label, confidence
    except Exception as e:
        logger.error(f"Error recognizing face: {e}")
        return None, None


def play_sound(channel, sound):
    try:
        if audio is None:
            logger.warning("Audio not initialized, skipping sound playback.")
            return
        if channel == 0:
            logger.info("Playing welcome sound...")
            audio.play(sound)
        elif channel == 1:
            logger.info("Playing wait sound...")
            audio.play(sound)
        elif channel == 2:
            logger.info("Playing error sound...")
            audio.play(sound)
    except Exception as e:
        logger.error(f"Error playing sound: {e}")


def handle_button_press():
    global running
    logger.info("Button pressed, looking for face...")
    while running:
        rlist, _, _ = select.select([sys.stdin], [], [], 0.1)
        if rlist:
            try:
                button_input = sys.stdin.read(1)
            except Exception as e:
                logger.error(f"Error reading input: {e}")
                break
            if button_input.lower() == 'l':
                logger.info("Manual lock requested...")
                play_sound(2, config.ERROR_SOUND)
                GPIO.output(lock_pin, GPIO.HIGH)
                return
    logger.info("Button press cancelled.")


def main():
    global running, camera, audio, button_pin, lock_pin

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not initialize_gpio():
        sys.exit(1)

    model = load_model()
    if not initialize_camera():
        sys.exit(1)
    if not initialize_audio():
        cleanup()
        sys.exit(1)

    button_thread = threading.Thread(target=handle_button_press, daemon=True)
    button_thread.start()

    try:
        while running:
            try:
                image = capture_image()
                if image is None:
                    time.sleep(0.1)
                    continue

                face_coords = detect_single(image)
                if face_coords is None:
                    time.sleep(0.1)
                    continue

                x, y, w, h = face_coords
                cropped = image[y:y + h, x:x + w]
                resized = cv2.resize(cropped, (160, 160))

                label, confidence = recognize_face(resized, model)

                if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                    logger.info("Recognized face! Unlocking door...")
                    GPIO.output(lock_pin, GPIO.LOW)
                    play_sound(0, config.WELCOME_SOUND)
                else:
                    logger.info("Face not recognized. Locking door...")
                    GPIO.output(lock_pin, GPIO.HIGH)
                    play_sound(2, config.ERROR_SOUND)
                    play_sound(1, config.WAIT_SOUND)

            except Exception as e:
                logger.error(f"Error in main loop: {e}")
                time.sleep(0.1)

    finally:
        cleanup()


if __name__ == "__main__":
    main()

