import bluetooth

BLUETOOTH_PORT = "/dev/rfcomm4"
BAUD_RATE = 38400


def open_bluetooth_port():
    """Open the Bluetooth serial device with robust error handling."""
    try:
        return bluetooth.BluetoothSerial(
