import threading
import time
import signal
import sys
import zmq
import gpsd

DEFAULT_LAT = 22.483425
DEFAULT_LON = 88.455463
GPSD_RETRY_DELAY = 5
GPSD_MAX_RETRIES = 3
ZMQ_LINGER_MS = 0

shutdown_event = threading.Event()
gps_lock = threading.Lock()
lat = DEFAULT_LAT
lon = DEFAULT_LON
mag = 0.0
alt = 0.0
context = None
footage_socket = None


def restart_gpsd():
    print("Attempting to restart gpsd...")
    try:
        ret = os.system("sudo systemctl restart gpsd")
        if ret != 0:
            print(f"gpsd restart command failed with return code {ret}")
    except OSError as e:
        print(f"Error restarting gpsd: {e}")


def get_gps_data():
    global lat, lon, mag, alt
    gpsd.connect()
    while not shutdown_event.is_set():
        try:
            report = gpsd.get_current()
            if report and hasattr(report, 'class') and report.class == 'TPV':
                if hasattr(report, 'lat') and hasattr(report, 'lon'):
                    try:
                        lat = float(report.lat)
                        lon = float(report.lon)
                    except (TypeError, ValueError):
                        pass
            time.sleep(0.5)
        except Exception as e:
            print(f"Error reading GPS data: {e}")
            if shutdown_event.wait(1.0):
                break
    gpsd.close()


def send_footage(socket):
    while not shutdown_event.is_set():
        try:
            data = f"{lat},{lon},{mag},{alt}\n"
            socket.send_string(data, zmq.SNDMORE)
            socket.send(lat, zmq.NOBLOCK)
            socket.send(lon, zmq.NOBLOCK)
            socket.send(mag, zmq.NOBLOCK)
            socket.send(alt, zmq.NOBLOCK)
            time.sleep(0.1)
        except zmq.ZMQError as e:
            print(f"ZMQError in send_footage: {e}")
            shutdown_event.wait(1.0)
        except Exception as e:
            print(f"Error sending footage: {e}")
            shutdown_event.wait(1.0)
    try:
        socket.close(linger=ZMQ_LINGER_MS)
    except Exception:
        pass


def main():
    global context, footage_socket
    signal.signal(signal.SIGINT, lambda s, f: (shutdown_event.set(), sys.exit(0)))
    signal.signal(signal.SIGTERM, lambda s, f: (shutdown_event.set(), sys.exit(0)))
    try:
        context = zmq.Context()
        footage_socket = context.socket(zmq.PUB)
        footage_socket.setsockopt(zmq.LINGER, ZMQ_LINGER_MS)
        footage_socket.connect("tcp://*:5000")
    except zmq.ZMQError as e:
        print(f"ZMQError creating socket: {e}")
        sys.exit(1)
    try:
        gps_thread = threading.Thread(target=get_gps_data, daemon=True)
        footage_thread = threading.Thread(target=send_footage, args=(footage_socket,), daemon=True)
        gps_thread.start()
        footage_thread.start()
        while not shutdown_event.is_set():
            shutdown_event.wait(1.0)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        shutdown_event.set()
        if footage_socket is not None:
            try:
                footage_socket.close(linger=ZMQ_LINGER_MS)
            except Exception:
                pass
        if context is not None:
            try:
                context.term()
            except Exception:
                pass
        gps_thread.join(timeout=5)
        footage_thread.join(timeout=5)
        if gps_thread.is_alive():
            print("Warning: gps_thread did not exit cleanly.")
        if footage_thread.is_alive():
            print("Warning: footage_thread did not exit cleanly.")


if __name__ == "__main__":
    main()

