import signal
import sys
import time
import boto3
from botocore.exceptions import ClientError, EndpointConnectionError, BotoCoreError

try:
    from picamera2 import Picamera2
except ImportError:
    print("Error: picamera2 library is not installed. Install with: pip install picamera2")
    sys.exit(1)

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_camera():
    """Initializes the Raspberry Pi camera using picamera2."""
    try:
        picam2 = Picamera2()
        # Configure for a still capture
        config = picam2.create_still_configuration()
        picam2.configure(config)
        picam2.start()
        return picam2
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_image(picam2):
    """Captures an image from the camera and saves it to a file."""
    try:
        # Allow camera to warm up
        time.sleep(2)
        picam2.capture_file("image.jpg")
        return "image.jpg"
    except Exception as e:
        print(f"Error capturing image: {e}")
        return None

def check_image_file(filename):
    """Checks if the image file exists and is accessible."""
    try:
        import os
        if not os.path.isfile(filename):
            print(f"Error: Image file '{filename}' not found.")
            return False
        return True
    except Exception as e:
        print(f"Error checking file existence: {e}")
        return False

def check_rekognition_client():
    """Checks if the Rekognition client is available."""
    try:
        client = boto3.client('rekognition')
        return client
    except (ClientError, EndpointConnectionError, BotoCoreError) as e:
        print(f"Error checking Rekognition client: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error checking client: {e}")
        return None

def search_faces(client, image_path, collection_id, similarity_threshold):
    """Searches for faces in the given image using Rekognition."""
    try:
        with open(image_path, 'rb') as image_file:
            response = client.search_faces_by_image(
                Image={'Bytes': image_file.read()},
                CollectionId=collection_id,
                MaxFaces=1,
                FaceMatchThreshold=similarity_threshold
            )
        return response
    except (ClientError, EndpointConnectionError, BotoCoreError) as e:
        print(f"Error searching faces: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error searching faces: {e}")
        return None

def process_search_results(response, similarity_threshold):
    """Processes the search results and prints the matched face information."""
    if response is None:
        return

    try:
        if 'FaceMatches' in response and response['FaceMatches']:
            face = response['FaceMatches'][0]
            match = face['Face']
            similarity = round(face['Similarity'], 2)
            if similarity >= similarity_threshold:
                print(f"Match found! Similarity: {similarity}%")
                print(f"  Image ID: {match['ImageId']}")
            else:
                print(f"Match found! Similarity: {similarity}% (threshold: {similarity_threshold}%)")
        else:
            print("No face matches found.")
    except Exception as e:
        print(f"Error processing search results: {e}")

def main():
    """Main function to capture image and search for faces."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    picam2 = initialize_camera()
    if picam2 is None:
        sys.exit(1)

    client = check_rekognition_client()
    if client is None:
        picam2.close()
        sys.exit(1)

    image_path = capture_image(picam2)
    if image_path is None:
        picam2.close()
        sys.exit(1)

    if not check_image_file(image_path):
        try:
            os.remove(image_path)
        except OSError:
            pass
        picam2.close()
        sys.exit(1)

    try:
        response = search_faces(client, image_path, "home", 85)
        process_search_results(response, 85)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        try:
            picam2.close()
        except Exception:
            pass

if __name__ == "__main__":
    main()

