import signal
import sys
import time
import logging
import numpy as np

try:
    import audioop
    from audiostream import AudioStream
    from gpiozero import Button
except ImportError as exc:
    print(f"Missing dependency: {exc.name}", file=sys.stderr)
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("gain_control")

BUTTON_PIN = 5
SAMPLE_RATE = 44100
BLOCK_SIZE = 1024
GAIN_MIN = 1.0
GAIN_MAX = 2.0
BOUNCE_TIME = 0.2

_running = True
_button = None
_stream = None


def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received – shutting down.", signum)
    _running = False


def _button_pressed():
    global _audio_gain
    _audio_gain = max(_audio_gain + 0.1, GAIN_MIN)
    log.info("Gain -> %.2f", _audio_gain)


def _soft_clipping(x, gain):
    return np.tanh(x / gain)


def _audio_callback(outdata, frames, time_info, status):
    if status:
        log.warning("Audio callback status: %s", status)
    try:
        raw = audioop.get_raw_audio(outdata, SAMPLE_RATE)
        if raw is None or len(raw) != frames:
            log.warning("Audio block raw data invalid: %r", raw)
            return
        processed = np.empty_like(raw)
        for i in range(0, len(raw), BLOCK_SIZE):
            chunk = raw[i:i + BLOCK_SIZE]
            if len(chunk) < BLOCK_SIZE:
                chunk = np.pad(chunk, (0, BLOCK_SIZE - len(chunk)), mode="constant")
            processed[i:i + BLOCK_SIZE] = _soft_clipping(
                chunk.astype(np.float32), _audio_gain
            )
        outdata[:] = processed.astype(np.int16)
    except Exception as exc:
        log.error("Audio callback error: %s", exc)


def main():
    global _button, _audio_gain, _stream

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _button = Button(BUTTON_PIN, pull_up=True, bounce_time=BOUNCE_TIME)
        _button.when_pressed = _button_pressed
    except Exception as exc:
        log.error("Failed to initialize button on GPIO%d: %s", BUTTON_PIN, exc)
        sys.exit(1)

    _audio_gain = 1.0
    try:
        _stream = AudioStream(
            sample_rate=SAMPLE_RATE,
            block_size=BLOCK_SIZE,
            callback=_audio_callback,
        )
        _stream.start()
    except Exception as exc:
        log.error("Failed to initialize audio stream: %s", exc)
        _button.close()
        sys.exit(1)

    log.info("Listening on GPIO%d (pull_up=True, bounce=%.2fs). Press Ctrl+C to exit.", BUTTON_PIN, BOUNCE_TIME)

    try:
        while _running:
            time.sleep(0.1)
    finally:
        log.info("Cleaning up…")
        if _stream is not None:
            try:
                _stream.stop()
            except Exception:
                pass
        if _button is not None:
            try:
                _button.close()
            except Exception:
                pass
        log.info("Done.")


if __name__ == "__main__":
    main()

