TOPIC = "raspberrypi/camera"
CONTROL_TOPIC = "raspberrypi/control"
CAPTURE_TIMEOUT = 15
CAPTURE_INTERVAL = 0.5
QOS = 1

shutdown_event = threading.Event()


def signal_handler(signum, frame):
    logger.info("Signal %s received – initiating shutdown.", signum)
    shutdown_event.set()


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        logger.info("Connected to MQTT broker.")
    else:
        logger.error("Failed to connect to MQTT broker. Reason code: %s", reason_code)


def on_disconnect(client, userdata, flags, reason_code, properties):
    if reason_code != 0:
        logger.warning("Unexpected disconnect from MQTT broker. Reason code: %s", reason_code)
    else:
        logger.info("Disconnected from MQTT broker.")


def on_message(client, userdata, msg):
    try:
        payload = msg.payload.decode("utf-8", errors="replace")
        logger.info("Received message on %s: %s", msg.topic, payload)
    except Exception as e:
        logger.error("Error decoding message on %s: %s", msg.topic, e)


def on_publish(client, userdata, mid, reason_code, properties):
    if reason_code != 0:
        logger.error("Failed to publish message (mid=%s). Reason code: %s", mid, reason_code)


def create_mqtt_client(host, port):
    client = mqtt.Client(
        callback_api_version=CallbackAPIVersion.VERSION2,
        client_id="rpi-capture",
    )
    client.on_connect = on_connect
    client.on_disconnect = on_disconnect
    client.on_message = on_message
    client.on_publish = on_publish
    client.connect(host, port, keepalive=60)
    client.loop_start()
    return client


def capture_image(client):
    try:
        os.makedirs(IMAGE_DIR, exist_ok=True)
    except OSError as e:
        logger.error("Cannot create image directory '%s': %s", IMAGE_DIR, e)
        return None

    timestamp = int(round(time.time() * 1000))
    filename = f"image_{timestamp}.jpg"
    filepath = os.path.join(IMAGE_DIR, filename)

    try:
        result = subprocess.run(
            ["libcamera-still", "-w", str(IMAGE_WIDTH), "-h", str(IMAGE_HEIGHT),
             "-o", filepath],
            capture_output=True,
            text=True,
            timeout=CAPTURE_TIMEOUT,
        )
    except FileNotFoundError:
        logger.error("libcamera-still not found. Is libcamera installed?")
        return None
    except subprocess.TimeoutExpired:
        logger.error("libcamera-still timed out after %d seconds.", CAPTURE_TIMEOUT)
        return None
    except Exception as e:
        logger.error("Error capturing image: %s", e)
        return None

    if result.returncode != 0:
        logger.error("libcamera-still failed (rc=%d): %s", result.returncode, result.stderr.strip())
        return None

    if not os.path.isfile(filepath):
        logger.error("Image file not created: %s", filepath)
        return None

    try:
        with open(filepath, "rb") as fh:
            image_data = fh.read()
    except OSError as e:
        logger.error("Cannot read image file '%s': %s", filepath, e)
        return None

    try:
        info = client.publish(TOPIC, image_data, qos=QOS)
        info.wait_for_publish(timeout=5)
    except Exception as e:
        logger.error("Failed to publish image: %s", e)
        return None

    logger.info("Image saved: %s", filepath)
    return filepath


def capture_loop(client):
    while not shutdown_event.is_set():
        filepath = capture_image(client)
        if filepath:
            logger.info("Publishing image: %s", filepath)
            try:
                info = client.publish(TOPIC, client.publish(TOPIC, client.publish(TOPIC, b"", qos=QOS).wait_for_publish(timeout=5)).wait_for_publish(timeout=5))
            except Exception as e:
                logger.error("Failed to publish image: %s", e)
        else:
            logger.warning("Capture failed – skipping publish cycle.")
        shutdown_event.wait(CAPTURE_INTERVAL)


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    client1 = create_mqtt_client("localhost", 1883)
    client2 = create_mqtt_client("localhost", 1883)

    capture_thread = threading.Thread(target=capture_loop, args=(client1,), daemon=True)
    capture_thread.start()

    try:
        while not shutdown_event.is_set():
            try:
                client2.subscribe(CONTROL_TOPIC)
                logger.info("Subscribed to %s", CONTROL_TOPIC)
            except Exception as e:
                logger.error("Failed to subscribe to %s: %s", CONTROL_TOPIC, e)
            shutdown_event.wait(1.0)
    except Exception as e:
        logger.error("Unexpected error in control loop: %s", e)
    finally:
        logger.info("Cleaning up...")
        shutdown_event.set()
        capture_thread.join(timeout=5)
        client1.disconnect()
        client2.disconnect()
        logger.info("Shutdown complete.")


if __name__ == "__main__":
    main()

