import io
import logging
import signal
import sys
import time
from typing import Callable, Optional

import numpy as np

try:
    from picamera2 import Picamera2
except ImportError:
    logging.error("picamera2 is not installed. Install with: pip install picamera2")
    sys.exit(1)

logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Buffer that accumulates MJPEG frames from a Picamera2 driver and flushes them."""

    def __init__(self, c: Picamera2, output: Optional[io.BytesIO] = None):
        self.c = c
        self.output = output or io.BytesIO()
        self._frame_type = 0  # 0 = H.264, 1 = JPEG
        self._flushed = False

    def write(self, d: bytes) -> int:
        """Append bytes to the internal buffer and flush when a complete frame is received."""
        try:
            self.output.write(d)
        except OSError as exc:
            logger.error("I/O error while writing to buffer: %s", exc)
            return 0

        # Flush when a complete frame is received or when the H.264 frame type is not 1
        if (d.endswith(b'\x00') and
                self._frame_type == 0 or
                self._frame_type != 1):
            self._flushed = True
            try:
                self.output.flush()
            except OSError as exc:
                logger.error("I/O error while flushing buffer: %s", exc)
            return len(d)

        return len(d)


class MotionDetectionBuffer:
    """Buffer that decodes MJPEG frames and notifies a callback on motion detection."""

    def __init__(self, f: Callable[[np.ndarray, np.ndarray], None],
                 c: Picamera2, output: Optional[io.BytesIO] = None):
        self.f = f
        self.c = c
        self.output = output or io.BytesIO()
        self._previous: Optional[np.ndarray] = None
        self._current: Optional[np.ndarray] = None
        self._frame_type = 0  # 0 = H.264, 1 = JPEG
        self._flushed = False

    def write(self, d: bytes) -> int:
        """Parse JPEG start-of-image markers and invoke the motion callback."""
        try:
            self.output.write(d)
        except OSError as exc:
            logger.error("I/O error while writing to buffer: %s", exc)
            return 0

        if d.startswith(b'\xff\xd8'):
            try:
                self._current = self.c.imdecode(d)
                if self._current is None:
                    logger.warning("imdecode returned None; skipping frame")
                    return len(d)
            except Exception as exc:
                logger.error("Error decoding frame: %s", exc)
                return len(d)

        if self._current is not None:
            if self._previous is not None:
                self.f(self._previous.copy(), self._current.copy())
            self._previous = self._current
            self._current = None

        if (d.endswith(b'\x00') and
                self._frame_type == 0 or
                self._frame_type != 1):
            self._flushed = True
            try:
                self.output.flush()
            except OSError as exc:
                logger.error("I/O error while flushing buffer: %s", exc)
            return len(d)

        return len(d)


def _signal_handler(signum, frame):
    logger.info("Signal %s received, shutting down...", signum)
    raise SystemExit(0)


def main():
    logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    picam2 = Picamera2()
    try:
        config = picam2.create_video_configuration(
            main={"size": (640, 480), "format": "MJPEG"},
            lores={"size": (320, 240), "format": "YUV420"},
            encode="main",
        )
        picam2.configure(config)
        picam2.start()
        logger.info("Camera started successfully.")
    except Exception as exc:
        logger.error("Failed to initialize or start camera: %s", exc)
        sys.exit(1)

    buffer: Optional[CameraStreamBuffer] = None
    motion_buffer: Optional[MotionDetectionBuffer] = None

    try:
        buffer = CameraStreamBuffer(picam2)
        motion_buffer = MotionDetectionBuffer(
            lambda p, c: logger.info("Motion detected: p=%s, c=%s", p, c),
            picam2,
        )

        while True:
            try:
                data = picam2.capture_array()
            except Exception as exc:
                logger.error("Capture error: %s", exc)
                time.sleep(0.1)
                continue

            if data is None:
                continue

            if buffer is not None:
                buffer.write(data.tobytes())

            if motion_buffer is not None:
                motion_buffer.write(data.tobytes())

            time.sleep(0.05)

    except SystemExit:
        pass
    finally:
        if buffer is not None:
            try:
                buffer.output.close()
            except Exception:
                pass
        if motion_buffer is not None:
            try:
                motion_buffer.output.close()
            except Exception:
                pass
        try:
            picam2.stop()
        except Exception:
            pass
        logger.info("Resources released. Exiting.")


if __name__ == "__main__":
    main()

