import signal
import sys
import time
import logging
import numpy as np
import sounddevice as sd
from PIL import Image
from libcamera import Transform
from libcamera import Transform
import config
import face
import lock

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DOOR_PIN = 18
BUTTON_PIN = 17
SAMPLE_RATE = 48000
LOOP_DELAY = 0.1

running = True
door = None
button = None
mixer = None
recognizer = None

def cleanup(signum=None, frame=None):
    global running, door, button, mixer
    running = False
    logging.info("Cleaning up resources...")
    if mixer is not None:
        try:
            mixer.stop()
        except Exception:
            pass
    if door is not None:
        try:
            door.close()
        except Exception:
            pass
    if button is not None:
        try:
            button.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def init_mixer():
    global mixer
    try:
        mixer = sd.Mixer(samplerate=SAMPLE_RATE, channels=1, dtype='float32')
        mixer.start()
        logging.info("Mixer initialized successfully.")
    except Exception as e:
        logging.error(f"Error initializing mixer: {e}")
        raise

def init_camera():
    try:
        from libcamera import Transform
        from libcamera import Transform
        camera = face.get_camera()
        camera.configure(camera.create_video_configuration(
            main={"size": (640, 480), "format": "RGB888"},
            transform=Transform(vflip=True, hflip=True)
        ))
        logging.info("Camera initialized successfully.")
        return camera
    except Exception as e:
        logging.error(f"Error initializing camera: {e}")
        raise

def init_recognizer():
    global recognizer
    try:
        recognizer = face.create_recognizer(config.TRAINING_FILE)
        logging.info("Face recognizer model loaded successfully.")
    except Exception as e:
        logging.error(f"Error loading face recognizer model: {e}")
        raise

def init_input_devices():
    global door, button
    try:
        door = lock.Lock(DOOR_PIN)
        button = lock.Button(BUTTON_PIN, pull_up=True)
        logging.info("Input devices initialized successfully.")
    except Exception as e:
        logging.error(f"Error initializing input devices: {e}")
        raise

def process_face_image(image):
    try:
        face_data = face.extract_face_features(image)
        return face_data
    except Exception as e:
        logging.error(f"Error extracting face features: {e}")
        return None

def recognize_face(face_data):
    try:
        matches = recognizer.predict(face_data)
        if matches[1] < config.POSITIVE_THRESHOLD:
            return matches[0], matches[1]
        return None, None
    except Exception as e:
        logging.error(f"Error during face recognition: {e}")
        return None, None

def play_sound(sound, duration=None):
    try:
        if sound is None:
            return
        if duration is None:
            duration = 1.0
        mixer.write(sound.array[:int(duration * SAMPLE_RATE)].tobytes())
    except Exception as e:
        logging.error(f"Error playing sound: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    try:
        init_mixer()
        camera = init_camera()
        init_recognizer()
        init_input_devices()
        welcome_sound = face.load_sound("welcome.wav")
        wait_sound = face.load_sound("wait.wav")
        later_sound = face.load_sound("later.wav")
        while running:
            if button.is_button_up():
                image = camera.capture_array()
                if image is None:
                    logging.warning("Failed to capture image.")
                    time.sleep(LOOP_DELAY)
                    continue
                face_image = Image.fromarray(image)
                face_data = process_face_image(face_image)
                if face_data is None:
                    logging.warning("Failed to process face image.")
                    play_sound(wait_sound, duration=1.0)
                    time.sleep(LOOP_DELAY)
                    continue
                label, confidence = recognize_face(face_data)
                if label is not None and label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                    logging.info("Recognized face! Unlocking door.")
                    door.unlock()
                    play_sound(welcome_sound, duration=1.0)
                    time.sleep(LOOP_DELAY)
                else:
                    logging.info("Face not recognized.")
                    play_sound(wait_sound, duration=1.0)
                    time.sleep(LOOP_DELAY)
            else:
                time.sleep(LOOP_DELAY)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

