import signal
import sys
import time

import smbus2
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

I2C_BUS = 1
BH1750_ADDR = 0x23
CONVERSION_DELAY_S = 0.12
UPDATE_INTERVAL_S = 1.0

running = True
i2c_bus = None
display = None


def handle_signal(signum, frame):
    global running
    running = False


def cleanup():
    global i2c_bus, display
    if display is not None:
        try:
            with canvas(display) as draw:
                draw.rectangle((0, 0, display.width - 1, display.height - 1), fill="black")
        except Exception:
            pass
        try:
            display.cleanup()
        except Exception:
            pass
    if i2c_bus is not None:
        try:
            i2c_bus.close()
        except Exception:
            pass


def main():
    global i2c_bus, display

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        i2c_bus = smbus2.SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        serial = i2c(bus=I2C_BUS, address=BH1750_ADDR)
        display = ssd1306(serial)
    except Exception as exc:
        print(f"Warning: BH1750 not found at 0x{BH1750_ADDR:02X} on bus {I2C_BUS}: {exc}",
              file=sys.stderr)
        print("Retaining previous contrast value and continuing.", file=sys.stderr)
        try:
            display = ssd1306(i2c(bus=I2C_BUS))
        except Exception:
            display = None

    contrast = 0
    try:
        while running:
            try:
                raw = i2c_bus.read_i2c_block_data(BH1750_ADDR, 0x00, 2)
            except OSError as exc:
                print(f"Warning: I2C read error from BH1750: {exc}", file=sys.stderr)
                time.sleep(0.5)
                continue

            lux = (raw[0] << 8) | raw[1]
            contrast = max(0, min(255, int(lux / 1.2)))
            try:
                with canvas(display) as draw:
                    draw.rectangle((0, 0, display.width - 1, display.height - 1),
                                   fill="black")
                    draw.text((0, 0), f"Lux: {lux:5d}", fill="white")
                    draw.text((0, 16), f"Contrast: {contrast:3d}", fill="white")
            except OSError as exc:
                print(f"Warning: display write error: {exc}", file=sys.stderr)

            time.sleep(UPDATE_INTERVAL_S)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

