import signal
import sys
import time
import board
import busio
import adafruit_bme280
from adafruit_tsl2561 import TSL2561
from adafruit_ssd1306 import SSD1306_I2C
from PIL import Image, ImageDraw, ImageFont

# --- Configuration -----------------------------------------------------------
I2C_SCL = board.SCL
I2C_SDA = board.SDA
OLED_WIDTH = 128
OLED_HEIGHT = 64
UPDATE_INTERVAL_S = 1.0

# --- Globals for cleanup -----------------------------------------------------
i2c = None
bme280 = None
tsl2561 = None
oled = None
running = True


def cleanup():
    """Release all hardware resources and clear the OLED display."""
    global i2c, oled
    if oled is not None:
        try:
            oled.fill(0)
            oled.show()
        except Exception:
            pass
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass


def handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global running
    running = False


def init_i2c():
    """Initialize the I2C bus; return the bus object or None on failure."""
    try:
        return busio.I2C(I2C_SCL, I2C_SDA)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize I2C bus: {exc}", file=sys.stderr)
        return None


def init_bme280(i2c_bus):
    """Initialize the BME280 sensor; return the sensor object or None."""
    try:
        return adafruit_bme280.Adafruit_BME280_I2C(i2c_bus, address=0x76)
    except Exception as exc:
        print(f"[ERROR] BME280 not found at 0x76: {exc}", file=sys.stderr)
        return None


def init_tsl2561(i2c_bus):
    """Initialize the TSL2561 light sensor; return the sensor object or None."""
    try:
        return TSL2561(i2c_bus)
    except Exception as exc:
        print(f"[ERROR] TSL2561 not found: {exc}", file=sys.stderr)
        return None


def init_oled(i2c_bus):
    """Initialize the SSD1306 OLED display; return the display object or None."""
    try:
        return SSD1306_I2C(OLED_WIDTH, OLED_HEIGHT, i2c_bus)
    except Exception as exc:
        print(f"[ERROR] SSD1306 not found: {exc}", file=sys.stderr)
        return None


def read_bme280(bme):
    """Read temperature, humidity, and pressure from the BME280; return dict or None."""
    if bme is None:
        return None
    try:
        return {
            "temperature": bme.temperature,
            "humidity": bme.humidity,
            "pressure": bme.pressure,
        }
    except Exception as exc:
        print(f"[WARN] BME280 read error: {exc}", file=sys.stderr)
        return None


def read_tsl2561(tsl):
    """Read the light level from the TSL2561; return lux or None."""
    if tsl is None:
        return None
    try:
        return tsl.lux
    except Exception as exc:
        print(f"[WARN] TSL2561 read error: {exc}", file=sys.stderr)
        return None


def display_data(oled, bme_data, tsl_data):
    """Render sensor data on the OLED display."""
    if oled is None:
        return
    try:
        image = Image.new("1", (oled.width, oled.height))
        draw = ImageDraw.Draw(image)
        font = ImageFont.load_default()

        lines = [
            f"Temp: {bme_data['temperature']:.1f} C" if bme_data else "",
            f"Humidity: {bme_data['humidity']:.1f} %"
            if bme_data else "",
            f"Pressure: {bme_data['pressure']:.1f} hPa"
            if bme_data else "",
            f"Light: {tsl_data:.1f} lux" if tsl_data else "",
        ]
        for i, line in enumerate(lines):
            draw.text((0, i * 12), line, font=font, fill=255)
        oled.image(image)
        oled.show()
    except Exception as exc:
        print(f"[ERROR] Display update failed: {exc}", file=sys.stderr)


def main():
    global i2c, bme280, tsl2561, oled

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    i2c = init_i2c()
    if i2c is None:
        sys.exit(1)

    bme280 = init_bme280(i2c)
    tsl2561 = init_tsl2561(i2c)
    oled = init_oled(i2c)

    if bme280 is None or tsl2561 is None or oled is None:
        cleanup()
        sys.exit(1)

    print("BME280 + TSL2561 + SSD1306 ready. Press Ctrl+C to exit.")

    try:
        while running:
            bme_data = read_bme280(bme280)
            tsl_data = read_tsl2561(tsl2561)
            display_data(oled, bme_data, tsl_data)
            time.sleep(UPDATE_INTERVAL_S)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

