    if tsl is None:
        return None
    try:
        return tsl.lux
    except Exception as exc:
        print(f"[WARN] TSL2561 read error: {exc}", file=sys.stderr)
        return None


def display_data(oled, bme_data, tsl_data):
    """Render sensor data on the OLED display."""
    if oled is None:
        return
    try:
        image = Image.new("1", (oled.width, oled.height))
        draw = ImageDraw.Draw(image)
        font = ImageFont.load_default()

        lines = [
            f"Temp: {bme_data['temperature']:.1f} C" if bme_data else "",
            f"Humidity: {bme_data['humidity']:.1f} %"
            if bme_data else "",
            f"Pressure: {bme_data['pressure']:.1f} hPa"
            if bme_data else "",
            f"Light: {tsl_data:.1f} lux" if tsl_data else "",
        ]
        for i, line in enumerate(lines):
            draw.text((0, i * 12), line, font=font, fill=255)
        oled.image(image)
        oled.show()
    except Exception as exc:
        print(f"[ERROR] Display update failed: {exc}", file=sys.stderr)


def main():
    global i2c, bme280, tsl2561, oled

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    i2c = init_i2c()
    if i2c is None:
        sys.exit(1)

    bme280 = init_bme280(i2c)
    tsl2561 = init_tsl2561(i2c)
    oled = init_oled(i2c)

    if bme280 is None or tsl2561 is None or oled is None:
        cleanup()
        sys.exit(1)

    print("BME280 + TSL2561 + SSD1306 ready. Press Ctrl+C to exit.")

    try:
        while running:
            bme_data = read_bme280(bme280)
            tsl_data = read_tsl2561(tsl2561)
            display_data(oled, bme_data, tsl_data)
            time.sleep(UPDATE_INTERVAL_S)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

