import os
import logging
import signal
import time
from typing import List, Optional, Tuple

from PIL import Image

try:
    from driver import AnimatedGif
except ImportError as exc:
    raise ImportError(
        "The 'driver' module is required. Install with: pip install driver"
    ) from exc

logger = logging.getLogger(__name__)


class GifPlayer:
    """A class to manage GIF animations on a Raspberry Pi display."""

    def __init__(
        self,
        display: "AnimatedGif",
        folder: str,
        width: Optional[int] = None,
        height: Optional[int] = None,
    ) -> None:
        if not isinstance(display, AnimatedGif):
            raise TypeError("display must be an AnimatedGif instance")

        self.display = display
        self.folder = folder
        self.width: int = width if width is not None else display.width
        self.height: int = height if height is not None else display.height
        self._frames: List[Image.Image] = []
        self._loop_count: int = 0
        self._current_index: int = 0
        self._is_running: bool = False
        self._closed: bool = False

        self._install_signal_handlers()

    # ------------------------------------------------------------------
    # Signal handling
    # ------------------------------------------------------------------
    def _install_signal_handlers(self) -> None:
        for sig in (signal.SIGINT, signal.SIGTERM):
            try:
                signal.signal(sig, self._handle_signal)
            except (ValueError, OSError):
                # Not in main thread or signal not supported
                pass

    def _handle_signal(self, signum, frame) -> None:
        logger.info("Received signal %s, stopping animation", signum)
        self.stop()
        raise SystemExit(0)

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def play(self) -> bool:
        """Start playing the loaded GIF. Returns True if finished or error."""
        if self._closed or not self._frames:
            logger.warning("Cannot play: animation is closed or no frames loaded")
            return False

        self._is_running = True
        try:
            for loop_count in range(self._loop_count + 1):
                if not self._is_running:
                    break
                for frame_index in range(len(self._frames)):
                    if not self._is_running:
                        break
                    try:
                        self.display.set_frame(self._frames[frame_index])
                        elapsed = time.monotonic() - loop_count * 1000
                        sleep_time = max(0, self._frames[frame_index].duration / 1000 - elapsed)
                        self.display.sleep(sleep_time)
                    except Exception as exc:
                        logger.error("Error displaying frame %d: %s", frame_index, exc)
                        return False
                if loop_count < self._loop_count:
                    continue
                break
            return True
        except Exception as exc:
            logger.error("Error playing GIF: %s", exc)
            return False
        finally:
            self._is_running = False

    def run(self) -> None:
        """Continuously play the loaded GIF until stopped or no more files."""
        while self._is_running:
            for file_name in self._load_files():
                if not self._is_running:
                    break
                if not self.play():
                    break
            if not self._is_running:
                break

    def stop(self) -> None:
        """Stop the animation and release resources."""
        if self._closed:
            return
        self._is_running = False
        self._closed = True
        logger.info("Animation stopped")

    def close(self) -> None:
        """Release all resources."""
        self.stop()
        self._closed = True

    # ------------------------------------------------------------------
    # Internal helpers
    # ------------------------------------------------------------------
    def _install_folder(self) -> None:
        """Ensure the folder exists so os.listdir() is safe."""
        try:
            os.makedirs(self.folder, exist_ok=True)
        except OSError as exc:
            logger.error("Cannot create folder '%s': %s", self.folder, exc)
            raise

    def _load_files(self) -> List[str]:
        """Return a list of valid GIF files in the folder."""
        self._install_folder()
        valid_files: List[str] = []
        for file_name in os.listdir(self.folder):
            if not file_name.lower().endswith(".gif"):
                continue
            file_path = os.path.join(self.folder, file_name)
            if not os.path.isfile(file_path):
                continue
            try:
                with Image.open(file_path) as img:
                    if img.is_animated:
                        valid_files.append(file_path)
                    else:
                        logger.warning("Non-animated file: %s", file_path)
            except Exception as exc:
                logger.warning("Could not validate %s: %s", file_path, exc)
        return valid_files

    def preload(self) -> None:
        """Load all valid GIF files, read per-frame durations, and convert to RGB."""
        self._frames.clear()
        self._loop_count = 0

        for file_name in self._load_files():
            if not self._is_running:
                return
            try:
                with Image.open(file_name) as img:
                    loop_count = 0
                    if img.mode != "RGBA":
                        img = img.convert("RGBA")
                    for frame_index in range(img.n_frames):
                        duration = img.info.get("duration", 0)
                        img = img.convert("RGB")
                        self._frames.append(img)
                        self._loop_count += loop_count
                        if duration > 0:
                            loop_count = int(duration)
                        else:
                            loop_count = 0
            except Exception as exc:
                logger.error("Error preloading %s: %s", file_name, exc)
                continue
        logger.info("Preloaded %d frames from %d files", len(self._frames), len(self._load_files()))

    # ------------------------------------------------------------------
    # Context manager support
    # ------------------------------------------------------------------
    def __enter__(self) -> "GifPlayer":
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        self.close()

