import signal
import sys
import time

try:
    import smbus2 as smbus
except ImportError:
    import smbus

I2C_BUS = 1
LCD_ADDR = 0x27
EN = 0x04
RW = 0x02
RS = 0x01
BACKLIGHT = 0x08

i2c_bus = None
running = True


def signal_handler(signum, frame):
    global running
    running = False


def lcd_write_byte(bus, data, rs_mode):
    bus.write_byte(LCD_ADDR, data | BACKLIGHT | rs_mode)
    time.sleep(0.001)
    bus.write_byte(LCD_ADDR, data | BACKLIGHT | rs_mode | EN)
    time.sleep(0.001)
    bus.write_byte(LCD_ADDR, data | BACKLIGHT | rs_mode & ~EN)
    time.sleep(0.001)


def lcd_command(bus, cmd):
    lcd_write_byte(bus, cmd, RS)
    if cmd in (0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0C, 0x06, 0x0D):
        time.sleep(0.002)
    elif cmd == 0x18:
        time.sleep(0.0005)
    elif cmd == 0x1C:
        time.sleep(0.0005)
    elif cmd == 0x20:
        time.sleep(0.0005)
    elif cmd == 0x21:
