        time.sleep(0.0005)
    elif cmd == 0x42:
        time.sleep(0.0005)
    elif cmd == 0x43:
        time.sleep(0.0005)
    elif cmd == 0x45:
        time.sleep(0.0005)
    elif cmd == 0x4C:
        time.sleep(0.0005)
    elif cmd == 0x50:
        time.sleep(0.0005)
    elif cmd == 0x51:
        time.sleep(0.0005)
    elif cmd == 0x52:
        time.sleep(0.0005)
    elif cmd == 0x60:
        time.sleep(0.0005)
    elif cmd == 0x61:
        time.sleep(0.0005)
    elif cmd == 0x7E:
        time.sleep(0.0005)
    elif cmd == 0x7F:
        time.sleep(0.0005)


def lcd_init(bus):
    lcd_command(bus, 0x33)
    lcd_command(bus, 0x32)
    lcd_command(bus, 0x28)
    lcd_command(bus, 0x0C)
    lcd_command(bus, 0x06)
    lcd_command(bus, 0x01)
    time.sleep(0.002)


def lcd_display_text(bus, text):
    for char in text:
        lcd_write_byte(bus, ord(char), RS)
        time.sleep(0.05)


def main():
    global i2c_bus
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        i2c_bus = smbus.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        lcd_init(i2c_bus)
        lcd_display_text(i2c_bus, "Hello, Pi!")
        time.sleep(2)
        lcd_command(i2c_bus, 0x01)
        time.sleep(0.5)
        lcd_display_text(i2c_bus, "I2C LCD Ready")
    except OSError as e:
        print(f"Error: I2C communication failed: {e}", file=sys.stderr)
    finally:
        if i2c_bus is not None:
            try:
                i2c_bus.close()
            except OSError:
                pass


if __name__ == "__main__":
    main()

