import signal
import sys
import time

import smbus2

I2C_BUS = 1
PCF8574_ADDR = 0x27
POLL_INTERVAL = 0.1
ERROR_PAUSE = 1.0

running = True
i2c = None


def _handle_signal(signum, frame):
    global running
    running = False


def init_i2c():
    global i2c
    try:
        i2c = smbus2.SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)


def read_proximity_sensors(bus):
    try:
        data = bus.read_i2c_block_data(PCF8574_ADDR, 0x00, 8)
    except OSError as exc:
        print(f"Error: I2C read failed: {exc}", file=sys.stderr)
        return False

    for idx, val in enumerate(data):
        if val & 0x01:
            print(f"Obstacle detected by sensor {idx}")
            return True
    return False


def cleanup():
    global i2c
    if i2c is not None:
        try:
            i2c.close()
        except OSError:
            pass
        i2c = None


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    init_i2c()

    try:
        while running:
            ok = read_proximity_sensors(i2c)
            if not ok:
                time.sleep(ERROR_PAUSE)
                continue
            time.sleep(POLL_INTERVAL)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

