import time
import signal
import sys
import RPi.GPIO as GPIO

DHT_PIN = 4
RED_PIN = 17
GREEN_PIN = 27
BLUE_PIN = 22
PWM_FREQ = 100
DUTY_ACTIVE = 100
DUTY_INACTIVE = 0
SAMPLE_INTERVAL = 1.0
MAX_RETRIES = 3
RETRY_DELAY = 0.5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(RED_PIN, GPIO.OUT)
    GPIO.setup(GREEN_PIN, GPIO.OUT)
    GPIO.setup(BLUE_PIN, GPIO.OUT)
    GPIO.output(RED_PIN, DUTY_INACTIVE)
    GPIO.output(GREEN_PIN, DUTY_INACTIVE)
    GPIO.output(BLUE_PIN, DUTY_INACTIVE)
    return (GPIO, RED_PIN, GREEN_PIN, BLUE_PIN)

def set_color(pwm_objects, red, green, blue, r, g, b):
    pwm_objects[0].ChangeDutyCycle(r)
    pwm_objects[1].ChangeDutyCycle(g)
    pwm_objects[2].ChangeDutyCycle(b)

def cleanup_gpio(pwm_objects):
    for pwm in pwm_objects:
        try:
            pwm.stop()
        except Exception:
            pass
    GPIO.cleanup()

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    pwm_objects = []
    try:
        GPIO, red, green, blue = setup_gpio()
        pwm_objects.append(GPIO)
        pwm_objects.append(GPIO)
        pwm_objects.append(GPIO)
        while _running:
            temperature = None
            for attempt in range(MAX_RETRIES):
                try:
                    temperature = _read_dht11()
                    if temperature is not None:
                        break
                except Exception as e:
                    print(f"Warning: DHT11 read failed: {e}")
                if attempt < MAX_RETRIES - 1:
                    time.sleep(RETRY_DELAY)
            if temperature is not None:
                color = _map_temperature(temperature)
                set_color(pwm_objects, red, green, blue, color[0], color[1], color[2])
            else:
                print("Warning: DHT11 read failed after retries, retaining previous LED state.")
            time.sleep(SAMPLE_INTERVAL)
    except Exception as e:
        print(f"Error: {e}")
    finally:
        cleanup_gpio(pwm_objects)

def _read_dht11():
    # Placeholder for a real DHT11 driver (e.g. adafruit-circuitpython-dht)
    # This would read 10 bits from the 1-wire bus.
    return 25.0

def _map_temperature(temperature):
    if temperature < 0:
        return (0, 0, 0)
    elif temperature < 18:
        return (0, 0, 100)
    elif temperature < 27:
        return (0, 100, 0)
    elif temperature < 35:
        return (100, 0, 0)
    else:
        return (100, 100, 0)

if __name__ == "__main__":
    main()

