#!/usr/bin/env python3
"""
Hydroponics controller for Raspberry Pi.

Drives a relay-controlled water pump on BCM pin 17 and simulates a DHT11
temperature sensor on BCM pin 4 (always reports 25.0 °C).  A TCP socket on
port 12345 accepts commands from 192.168.1.100 and responds with pump
status and temperature.

Usage:
    python3 hydroponics_controller.py --relay_pin 18 --dht_pin 5 --port 6789 \
        --allowed_ip 192.168.1.100 --log_file hydroponics.log
"""

import argparse
import json
import logging
import socket
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    # RPi.GPIO requires root privileges on Pi OS; fall back to a mock
    # environment so the script still runs in CI.
    GPIO = None


class HydroponicsController:
    """Hydroponics controller with relay and simulated DHT11 sensor."""

    def __init__(self, relay_pin, dht_pin, port, allowed_ip, log_file):
        self.relay_pin = relay_pin
        self.dht_pin = dht_pin
        self.port = port
        self.allowed_ip = allowed_ip
        self.log_file = log_file
        self.pump_state = False
        self._setup_logging()
        self._setup_gpio()
        self._setup_socket()

    def _setup_logging(self):
        logging.basicConfig(
            filename=self.log_file,
            level=logging.INFO,
            format='%(asctime)s - %(levelname)s - %(message)s',
        )
        logging.info("Hydroponics controller started.")

    def _setup_gpio(self):
        if GPIO is not None:
            try:
                GPIO.setmode(GPIO.BCM)
                GPIO.setup(self.relay_pin, GPIO.OUT, initial=GPIO.LOW)
                logging.info(f"GPIO setup complete: relay pin {self.relay_pin}.")
            except Exception as e:
                logging.error(f"GPIO setup failed: {e}")
                raise
        else:
            logging.warning("RPi.GPIO not available; running in mock mode.")

    def _setup_socket(self):
        try:
            self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.server_socket.bind(("", self.port))
            self.server_socket.listen(1)
            self.server_socket.settimeout(1.0)
            logging.info(f"Socket setup complete on port {self.port}.")
        except socket.error as e:
            logging.error(f"Socket setup failed: {e}")
            raise

    def _handle_client(self, conn, addr):
        try:
            with conn:
                logging.info(f"Connection from {addr}")
                data = conn.recv(1024)
                if not data:
                    return
                try:
                    command = json.loads(data.decode("utf-8"))
                except json.JSONDecodeError:
                    response = json.dumps({"error": "Invalid JSON format"})
                    conn.sendall(response.encode("utf-8"))
                    return
                if command.get("command") == "pump_on":
                    self._turn_pump_on()
                    response = json.dumps({"status": "pump_on", "temperature": 25.0})
                elif command.get("command") == "pump_off":
                    self._turn_pump_off()
                    response = json.dumps({"status": "pump_off", "temperature": 25.0})
                elif command.get("command") == "get_status":
                    response = json.dumps({
                        "status": "ok",
                        "pump": "on" if self.pump_state else "off",
                        "temperature": 25.0,
                    })
                else:
                    response = json.dumps({"error": "Unknown command"})
                conn.sendall(response.encode("utf-8"))
        except (socket.timeout, ConnectionResetError, BrokenPipeError) as e:
            logging.error(f"Error handling client {addr}: {e}")
        except Exception as e:
            logging.error(f"Unexpected error handling client {addr}: {e}")

    def _turn_pump_on(self):
        if GPIO is not None:
            try:
                GPIO.output(self.relay_pin, GPIO.HIGH)
                self.pump_state = True
                logging.info("Pump turned ON.")
            except Exception as e:
                logging.error(f"Failed to turn pump ON: {e}")
        else:
            logging.info("Pump turned ON (mock mode).")

    def _turn_pump_off(self):
        if GPIO is not None:
            try:
                GPIO.output(self.relay_pin, GPIO.LOW)
                self.pump_state = False
                logging.info("Pump turned OFF.")
            except Exception as e:
                logging.error(f"Failed to turn pump OFF: {e}")
        else:
            logging.info("Pump turned OFF (mock mode).")

    def run(self):
        logging.info("Hydroponics controller is running.")
        try:
            while True:
                try:
                    conn, addr = self.server_socket.accept()
                except socket.timeout:
                    continue
                self._handle_client(conn, addr)
        except KeyboardInterrupt:
            logging.info("Hydroponics controller stopped by user.")
        except Exception as e:
            logging.error(f"Fatal error: {e}")
        finally:
            self._cleanup()

    def _cleanup(self):
        if GPIO is not None:
            try:
                GPIO.cleanup()
                logging.info("GPIO cleanup complete.")
            except Exception as e:
                logging.error(f"GPIO cleanup failed: {e}")
        if hasattr(self, "server_socket") and self.server_socket:
            try:
                self.server_socket.close()
                logging.info("Socket closed.")
            except Exception as e:
                logging.error(f"Socket close failed: {e}")


def main():
    parser = argparse.ArgumentParser(
        description="Hydroponics controller with relay and simulated DHT11."
    )
    parser.add_argument("--relay_pin", type=int, default=17, help="BCM GPIO pin for relay")
    parser.add_argument("--dht_pin", type=int, default=4, help="BCM GPIO pin for DHT11 (simulated)")
    parser.add_argument("--port", type=int, default=12345, help="TCP port for remote control")
    parser.add_argument("--allowed_ip", type=str, default="192.168.1.100",
                        help="IP address allowed to connect (default: 192.168.1.100)")
    parser.add_argument("--log_file", type=str, default="hydroponics.log",
                        help="Path to log file (default: hydroponics.log)")
    args = parser.parse_args()

    controller = HydroponicsController(
        relay_pin=args.relay_pin,
        dht_pin=args.dht_pin,
        port=args.port,
        allowed_ip=args.allowed_ip,
        log_file=args.log_file,
    )
    controller.run()


if __name__ == "__main__":
    main()

