import time
import signal
import sys

try:
    from gpiozero import CPUTemperature
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def get_cpu_temperature():
    """Read the CPU temperature from the Raspberry Pi.

    Returns the temperature in degrees Celsius, or None if the thermal
    sensor is unavailable (file missing) so that the caller can decide
    whether to retry or exit.
    """
    try:
        cpu = CPUTemperature()
        return float(cpu.temperature)
    except FileNotFoundError:
        print("Error: CPU temperature thermal file not found. Is this running on a Raspberry Pi?")
        return None
    except GPIOZeroError as e:
        print(f"Error: GPIOZero error reading CPU temperature: {e}")
        return None
    except Exception as e:
        print(f"Error: Unexpected error reading CPU temperature: {e}")
        return None

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    while _running:
        temp = get_cpu_temperature()
        if temp is not None:
            print(f"CPU Temperature: {temp:.2f} °C")
        time.sleep(5)

    print("Program terminated")

if __name__ == "__main__":
    main()

