import time
import logging
import signal
import sys
from typing import List, Optional

from bmp280 import BMP280, BMP280Error

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

I2C_BUS = 1
I2C_SDA = 2
I2C_SCL = 3
SEA_LEVEL_HPA = 1013.25
NUM_SAMPLES = 100
DISCARD_PERCENT = 0.25
SAMPLE_INTERVAL = 1.0

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False
    logger.info("Signal %s received, shutting down...", signum)


def _discard_top_bottom(samples: List[float], discard_pct: float) -> List[float]:
    if not samples:
        return samples
    n = len(samples)
    discard = int(n * discard_pct)
    if discard <= 0:
        return samples
    return samples[discard: -discard]


def _trimmed_mean(samples: List[float]) -> float:
    trimmed = _discard_top_bottom(samples, DISCARD_PERCENT)
    if not trimmed:
        raise ValueError("No valid samples after trimming")
    return sum(trimmed) / len(trimmed)


def _init_sensor() -> Optional[BMP280]:
    try:
        sensor = BMP280(i2c_dev=0, i2c_sda=I2C_SDA, i2c_scl=I2C_SCL)
        sensor.sea_level_pressure = SEA_LEVEL_HPA
        time.sleep(0.1)
        return sensor
    except (OSError, BMP280Error) as exc:
        logger.error("Failed to initialize BMP280 on bus %d: %s", I2C_BUS, exc)
        return None
    except Exception as exc:
        logger.error("Unexpected error during sensor init: %s", exc)
        return None


def _read_pressure(sensor: BMP280) -> Optional[float]:
    try:
        return sensor.pressure
    except (OSError, BMP280Error) as exc:
        logger.error("I2C read error: %s", exc)
        return None
    except Exception as exc:
        logger.error("Unexpected read error: %s", exc)
        return None


def main() -> int:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    sensor = _init_sensor()
    if sensor is None:
        logger.error("Cannot continue without BMP280. Using default sea-level pressure.")
        return 1

    logger.info("Collecting %d pressure samples for baseline...", NUM_SAMPLES)
    samples: List[float] = []
    try:
        for i in range(NUM_SAMPLES):
            if not _running:
                logger.info("Interrupted before completion.")
                break
            p = _read_pressure(sensor)
            if p is not None:
                samples.append(p)
            time.sleep(0.01)
    except OSError as exc:
        logger.error("I2C bus error during sampling: %s", exc)
        return 1
    except Exception as exc:
        logger.error("Unexpected error during sampling: %s", exc)
        return 1

    if not samples:
        logger.error("No valid pressure samples collected.")
        return 1

    try:
        baseline = _trimmed_mean(samples)
        logger.info("Baseline pressure: %.2f hPa")
        print(f"Baseline pressure: {baseline:.2f} hPa")
    except ValueError as exc:
        logger.error("Failed to compute baseline: %s", exc)
        return 1

    try:
        while _running:
            p = _read_pressure(sensor)
            if p is None:
                logger.warning("Sensor read failed; using fallback pressure.")
                p = SEA_LEVEL_HPA
            else:
                p = p - baseline
                logger.info("Altitude: %.2f m", p / 100.0)
                print(f"Altitude: {p:.2f} m")
            time.sleep(SAMPLE_INTERVAL)
    except OSError as exc:
        logger.error("I2C bus error during main loop: %s", exc)
        return 1
    except Exception as exc:
        logger.error("Unexpected error in main loop: %s", exc)
        return 1
    finally:
        try:
            sensor.close()
        except Exception:
            pass
        logger.info("Resources released. Exiting.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

