import signal
import sys
import time
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

DHT_PIN = 17
FAN_PIN = 18
LOG_FILE = "urban_data_log.txt"
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0
LOOP_COUNT = 5
LOOP_DELAY = 2.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def log_data(timestamp, temperature, humidity, fan_on):
    try:
        with open(LOG_FILE, "a", encoding="utf-8") as f:
            f.write(f"{timestamp} - Temperature: {temperature:.1f}C, Humidity: {humidity:.1f}%, Fan: {'ON' if fan_on else 'OFF'}\n")
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)


def read_dht11():
    if GPIO is None:
        return None, None
    try:
        import adafruit_dht
        import board
        pin_map = {17: board.D17, 18: board.D18}
        dht = adafruit_dht.DHT11(pin_map[DHT_PIN])
        temperature = dht.temperature
        humidity = dht.humidity
        dht.exit()
        return temperature, humidity
    except Exception as e:
        print(f"Error reading DHT11 sensor: {e}", file=sys.stderr)
        return None, None


def control_fan(temperature, humidity, fan_on):
    if temperature is not None and temperature > TEMP_THRESHOLD:
        GPIO.output(FAN_PIN, GPIO.HIGH)
        print("Fan ON: Temperature exceeds threshold.")
    elif humidity is not None and humidity > HUMIDITY_THRESHOLD:
        GPIO.output(FAN_PIN, GPIO.HIGH)
        print("Fan ON: Humidity exceeds threshold.")
    else:
        GPIO.output(FAN_PIN, GPIO.LOW)
        print("Fan OFF: Conditions normal.")


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    if GPIO is None:
        print("RPi.GPIO not available; running in degraded mode.", file=sys.stderr)
        _running = False

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(FAN_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"Error initializing GPIO: {e}", file=sys.stderr)
        _running = False

    try:
        for i in range(LOOP_COUNT):
            if not _running:
                break
            temperature, humidity = read_dht11()
            timestamp = datetime.now().isoformat(timespec="seconds")
            log_data(timestamp, temperature, humidity, GPIO.input(FAN_PIN) == GPIO.HIGH)
            control_fan(temperature, humidity, GPIO.input(FAN_PIN) == GPIO.HIGH)
            if i < LOOP_COUNT - 1 and _running:
                time.sleep(LOOP_DELAY)
    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

