import time
import logging
import signal
import sys
from typing import Optional, Tuple

try:
    from smbus2 import SMBus
except ImportError:
    logging.error("smbus2 is required: pip install smbus2")
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


class DHT20:
    """Driver for the Aosong DHT20 temperature/humidity sensor (I2C, 0x28)."""

    REG_STATUS = 0x00
    REG_DATA = 0x71

    def __init__(self, bus: int = 1, timeout: float = 0.8, retry_delay: float = 0.01):
        self._bus = bus
        self._timeout = timeout
        self._retry_delay = retry_delay
        self._bus_num: Optional[int] = None
        self._closed = False
        self._last_temp: Optional[float] = None
        self._last_hum: Optional[float] = None
        self._cached: bool = False
        self._cached_t: Optional[float] = None
        self._cached_h: Optional[float] = None
        self._init_bus()

    # ------------------------------------------------------------------
    # Bus lifecycle
    # ------------------------------------------------------------------
    def _init_bus(self) -> None:
        try:
