import subprocess
import time
import signal
import sys
import logging

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None

FAN_PIN = 14
PWM_FREQ = 100
POLL_INTERVAL = 5
DEFAULT_DUTY = 100

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("fanctl")

_running = True


def _handle_signal(signum, frame):
    global _running
    log.info("Received signal %s, shutting down...", signum)
    _running = False


def get_cpu_temp():
    """Return CPU temperature in degrees Celsius, or None on error."""
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            timeout=5,
        )
        if result.returncode != 0:
            log.error("vcgencmd failed (rc=%d): %s", result.returncode, result.stderr.strip())
            return None
        out = result.stdout.strip()
        # Expected format: temp=42.8'C
        if not out.startswith("temp="):
            log.error("Unexpected vcgencmd output: %r", out)
            return None
        return float(out.split("=")[1].split("'")[0])
    except FileNotFoundError:
        log.error("vcgencmd not found — is this running on a Raspberry Pi?")
        return None
    except subprocess.TimeoutExpired:
        log.error("vcgencmd timed out")
        return None
    except (IndexError, ValueError) as exc:
        log.error("Failed to parse vcgencmd output: %s", exc)
        return None
    except OSError as exc:
        log.error("OS error while calling vcgencmd: %s", exc)
        return None


def duty_for_temp(temp):
    """Map a CPU temperature to a PWM duty cycle (0–100)."""
    if temp is None:
        return DEFAULT_DUTY
    if temp < 45:
        return 20
    if temp < 50:
        return 30
    if temp < 55:
        return 40
    if temp < 60:
        return 50
    if temp < 65:
        return 60
    if temp < 70:
        return 70
    if temp < 75:
        return 80
    if temp < 80:
        return 90
    return 100


def main():
    global _running

    if GPIO is None:
        log.error("RPi.GPIO is not available — cannot run")
        sys.exit(1)

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(FAN_PIN, GPIO.OUT)

    pwm = None
    current_duty = DEFAULT_DUTY

    try:
        pwm = GPIO.PWM(FAN_PIN, PWM_FREQ)
        pwm.start(0)
        log.info("Fan PWM started on GPIO%d at %d Hz", FAN_PIN, PWM_FREQ)

        while _running:
            temp = get_cpu_temp()
            duty = duty_for_temp(temp)
            if duty != current_duty:
                try:
                    pwm.ChangeDutyCycle(duty)
                    current_duty = duty
                    log.info("CPU %.1f°C -> fan duty %.0f%%", temp, duty)
                except Exception as exc:
                    log.error("Failed to set duty cycle: %s", exc)
            time.sleep(POLL_INTERVAL)
    finally:
        if pwm is not None:
            try:
                pwm.stop()
            except Exception:
                pass
        if GPIO is not None:
            try:
                GPIO.cleanup()
            except Exception:
                pass
        log.info("Cleanup complete")


if __name__ == "__main__":
    main()

