import config
import signal
import sys
import time
import logging
import paho.mqtt.client as mqtt
import adafruit_dht
import board

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DEGREE_CELSIUS = '\u00B0C'
DHT_PIN = getattr(board, f'D{config.dhtgpiopin}', None)
running = True

def signal_handler(signum, frame):
    global running
    logger.info(f"Signal {signum} received, shutting down...")
    running = False

def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        logger.info("Connected to MQTT broker")
    else:
        logger.error(f"Failed to connect to MQTT broker, reason code: {reason_code}")

def on_disconnect(client, userdata, flags, reason_code, properties):
    logger.warning(f"Disconnected from MQTT broker, reason code: {reason_code}")

def on_publish(client, userdata, mid, reason_code, properties):
    logger.debug(f"Message {mid} published")

def connect_mqtt():
    try:
        client = mqtt.Client(
            callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid,
            protocol=mqtt.MQTTv311
        )
        if config.mqttusername and config.mqttpassword:
            client.username_pw_set(config.mqttusername, config.mqttpassword)
        client.on_connect = on_connect
        client.on_disconnect = on_disconnect
        client.on_publish = on_publish
        client.will_set(
            f"homie/{config.homieclientid}/$state", "lost",
            retain=config.mqttretainmessage, qos=config.mqttqos
        )
        client.connect(config.mqttbroker, config.mqttport, keepalive=60)
        client.loop_start()
        return client
    except Exception as e:
        logger.error(f"MQTT connection failed: {e}")
        return None

def read_dht22():
    try:
        sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as e:
        logger.error(f"Failed to initialize DHT22 on pin {config.dhtgpiopin}: {e}")
        return None, None

    for attempt in range(3):
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
        except RuntimeError as e:
            logger.warning(f"DHT22 read attempt {attempt + 1} failed: {e}")
        except Exception as e:
            logger.error(f"Unexpected DHT22 error: {e}")
        time.sleep(2)
    return None, None

def publish_data(client, temperature, humidity):
    if client is None:
        logger.warning("MQTT client not available, skipping publish")
        return
    try:
        client.publish(
            f"homie/{config.homieclientid}/{config.homienodes}/temperature", f"{temperature:.1f}",
            retain=config.mqttretainmessage, qos=config.mqttqos
        )
        client.publish(
            f"homie/{config.homieclientid}/{config.homienodes}/humidity", f"{humidity:.1f}",
            retain=config.mqttretainmessage, qos=config.mqttqos
        )
        logger.info(f"Published T={temperature:.1f}{DEGREE_CELSIUS}, H={humidity:.1f}%")
    except Exception as e:
        logger.error(f"Failed to publish data: {e}")

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    mqtt_client = connect_mqtt()
    if mqtt_client is None:
        logger.error("Cannot continue without MQTT connection")
        sys.exit(1)

    try:
        while running:
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
                publish_data(mqtt_client, temperature, humidity)
            else:
                logger.warning("Skipping publish due to sensor read failure")
            for _ in range(config.publishtime):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        logger.info("Cleaning up...")
        try:
            mqtt_client.loop_stop()
            mqtt_client.disconnect()
        except Exception:
            pass
        try:
            DHT_PIN.deinit()
        except Exception:
            pass
        logger.info("Cleanup complete")

if __name__ == "__main__":
    main()

