import signal
import sys
import logging
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
ALERT_PIN = 17
LOG_FILE = '/home/pi/sensor_log.txt'
TEMP_THRESHOLD = 28.0
HUMIDITY_THRESHOLD = 65.0
ALERT_DURATION = 5.0

_running = True
_serial_conn = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _setup_logging():
    logging.basicConfig(
        filename=LOG_FILE,
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
    )


def _init_gpio():
    if GPIO is None:
        logging.warning('RPi.GPIO not available; GPIO alerts disabled.')
        return False
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(ALERT_PIN, GPIO.OUT, initial=GPIO.LOW)
        return True
    except Exception as e:
        logging.error(f'GPIO init failed: {e}')
        return False


def _cleanup_gpio():
    if GPIO is not None:
        try:
            GPIO.output(ALERT_PIN, GPIO.LOW)
            GPIO.cleanup(ALERT_PIN)
        except Exception:
            pass


def _open_serial():
    try:
        conn = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1.0,
        )
        if not conn.is_open:
            conn.close()
            raise IOError(f'Port {SERIAL_PORT} did not open')
        logging.info(f'Opened {SERIAL_PORT} @ {BAUD_RATE} baud')
        return conn
    except serial.SerialException as e:
        logging.error(f'Serial init failed: {e}')
        return None
    except IOError as e:
        logging.error(f'IO error opening {SERIAL_PORT}: {e}')
        return None


def _read_line(conn):
    try:
        raw = conn.readline()
    except serial.SerialException as e:
        logging.error(f'Read error: {e}')
        return None
    except IOError as e:
        logging.error(f'IO error: {e}')
        return None
    if not raw:
        return None
    try:
        return raw.decode('ascii', errors='replace').strip()
    except Exception as e:
        logging.error(f'Decode error: {e}')
        return None


def _parse_reading(line):
    if not line:
        return None
    parts = line.split(',')
    if len(parts) != 2:
        logging.warning(f'Malformed line: {line!r}')
        return None
    try:
        temperature = float(parts[0])
        humidity = float(parts[1])
    except ValueError:
        logging.warning(f'Non-numeric data: {line!r}')
        return None
    return temperature, humidity


def _log_reading(temperature, humidity):
    if temperature is not None and humidity is not None:
        logging.info(f'Temp: {temperature:.2f} C, Humidity: {humidity:.2f} %')


def _trigger_alert():
    if GPIO is None:
        return
    try:
        GPIO.output(ALERT_PIN, GPIO.HIGH)
        logging.warning('ALERT: Temperature or humidity threshold exceeded!')
        time.sleep(ALERT_DURATION)
        GPIO.output(ALERT_PIN, GPIO.LOW)
    except Exception as e:
        logging.error(f'GPIO alert error: {e}')


def main():
    global _serial_conn
    _setup_logging()
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not _init_gpio():
        logging.warning('GPIO alerts disabled; continuing without alerts.')

    _serial_conn = _open_serial()
    if _serial_conn is None:
        logging.error('Cannot continue without serial connection.')
        _cleanup_gpio()
        sys.exit(1)

    try:
        while _running:
            line = _read_line(_serial_conn)
            if line is not None:
                parsed = _parse_reading(line)
                if parsed is not None:
                    temperature, humidity = parsed
                    _log_reading(temperature, humidity)
                    if temperature > TEMP_THRESHOLD or humidity > HUMIDITY_THRESHOLD:
                        _trigger_alert()
    except Exception as e:
        logging.error(f'Unexpected error: {e}')
    finally:
        if _serial_conn is not None and _serial_conn.is_open:
            try:
                _serial_conn.close()
                logging.info('Serial port closed.')
            except Exception as e:
                logging.error(f'Error closing serial port: {e}')
        _cleanup_gpio()
        logging.info('Program terminated.')


if __name__ == '__main__':
    main()

