import signal
import sys
import time
import logging

from ina219 import INA219, DeviceRangeError

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("ina219_ups")

I2C_BUS = 1
SUPPLY_SHUNT = 0.00725
BATT_SHUNT = 0.005
READ_INTERVAL = 2.0
MAX_RETRIES = 3

running = True
supplies = []
batteries = []
ups = []


def _handle_signal(signum, frame):
    global running
    log.info("Signal %s received – shutting down.", signum)
    running = False


def _open_ina219(shunt, label):
    try:
        return INA219(shunt, busnum=I2C_BUS, address=None)
    except Exception as exc:
        log.error("Failed to open INA219 '%s': %s", label, exc)
        return None


def _read_ina219(ina):
    if not INA219.is_available():
        log.error("INA219 library is not available.")
        return None
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            return INA219.read()
        except DeviceRangeError:
            log.warning("Current out of range for INA219 '%s' (attempt %d).", label, attempt)
        except Exception as exc:
            log.error("Error reading INA219 '%s': %s", label, exc)
            return None
    return None


def _format_supply(v, c):
    return f"Supply: {v:.3f} V, {c:.3f} mA"


def _format_battery(v, c):
    return f"Battery: {v:.3f} V, {c:.3f} mA"


def _format_ups(proc, batt, temp, cap):
    return (
        f"UPS: Proc {proc:.0f}mV, "
        f"Battery Port {batt:.0f}mV, "
        f"Temp {temp:.1f}C, "
        f"Capacity {cap:.1f}%"
    )


def main():
    global supplies, batteries, ups

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    supplies = [_open_ina219(SUPPLY_SHUNT, "Supply") if s is None else s
                for s in supplies]
    batteries = [_open_ina219(BATT_SHUNT, "Battery") if s is None else s
                for s in batteries]
    ups = [_open_ina219(0.0001, "UPS") if s is None else s
           for s in ups]

    if not any(s is not None for s in supplies + batteries + ups):
        log.error("No INA219 devices detected on bus %d.", I2C_BUS)
        sys.exit(1)

    while running:
        v = c = None
        bv = bc = None
        up = None

        for i, s in enumerate(supplies):
            v = _read_ina219(s)
            if v is not None:
                v = v.voltage
                c = v.current
                break

        if v is not None:
            print(_format_supply(v, c))
        else:
            log.error("Supply INA219 read failed after %d retries.", MAX_RETRIES)

        for i, s in enumerate(batteries):
            v = _read_ina219(s)
            if v is not None:
                v = v.voltage
                c = v.current
                break

        if v is not None:
            print(_format_battery(v, c))
        else:
            log.error("Battery INA219 read failed after %d retries.", MAX_RETRIES)

        for i, s in enumerate(ups):
            try:
                proc = s.read()
                batt = s.voltage
                temp = s.temperature
                cap = s.capacity
                break
            except Exception as exc:
                log.error("UPS read failed after %d retries: %s", MAX_RETRIES, exc)
                break

        if up is not None:
            print(_format_ups(proc, batt, temp, cap))

        for s in supplies + batteries + ups:
            if s is not None:
                try:
                    s.close()
                except Exception:
                    pass

        time.sleep(READ_INTERVAL)

    for s in supplies + batteries + ups:
        if s is not None:
            try:
                s.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

