import time
import signal
import sys
from datetime import datetime

try:
    import board
    import adafruit_dht
except ImportError:
    print("Missing dependency: install with 'pip install adafruit-circuitpython-dht board'", file=sys.stderr)
    sys.exit(1)

DATA_PIN = board.D17
READ_INTERVAL_S = 2.0
MAX_RETRIES = 3

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

signal.signal(signal.SIGINT, _handle_signal)
signal.signal(signal.SIGTERM, _handle_signal)

sensor = None
try:
    try:
        sensor = adafruit_dht.DHT22(DATA_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialize DHT22 on GPIO17: {exc}", file=sys.stderr)
        sys.exit(1)

    while _running:
        timestamp = datetime.now().isoformat(timespec="seconds")
        temp = None
        humidity = None

        for attempt in range(1, MAX_RETRIES + 1):
            try:
                temp = sensor.temperature
                humidity = sensor.humidity
                if temp is not None and humidity is not None:
                    break
            except RuntimeError as exc:
                print(f"Read attempt {attempt}/{MAX_RETRIES} failed: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Unexpected read error on attempt {attempt}/{MAX_RETRIES}: {exc}", file=sys.stderr)
            time.sleep(0.5)

        if temp is None or humidity is None:
            print(f"{timestamp} — sensor read failed after {MAX_RETRIES} attempts", file=sys.stderr)
        else:
            print(f"{timestamp} Temp: {temp:.1f}C Humidity: {humidity:.1f}%")

        for _ in range(int(READ_INTERVAL_S * 10)):
            if not _running:
                break
            time.sleep(0.1)

except Exception as exc:
    print(f"Fatal error: {exc}", file=sys.stderr)
finally:
    if sensor is not None:
        try:
            sensor.exit()
        except Exception:
            pass

