import signal
import sys
import time
from typing import List, Optional

import numpy as np
import matplotlib.pyplot as plt

try:
    from serial import Serial
except ImportError:
    Serial = None

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
READ_TIMEOUT = 1.0          # seconds per readline attempt
FRAME_WIDTH = 24
FRAME_HEIGHT = 32
NUM_PIXELS = FRAME_WIDTH * FRAME_HEIGHT
COMMA_DELIMITER = ","

# Matplotlib setup (done in main so cleanup can access it)
plt.ion()
fig, ax = plt.subplots()
im = ax.imshow(np.zeros((FRAME_HEIGHT, FRAME_WIDTH)), cmap="inferno", interpolation="nearest")
ax.set_title("Thermal Camera Stream")
ax.set_xlabel("X")
ax.set_ylabel("Y")
fig.colorbar(im, ax=ax, label="Temperature")
ax.set_xticks([])
ax.set_yticks([])
ax.set_xlim(0, FRAME_WIDTH)
ax.set_ylim(0, FRAME_HEIGHT)
ax.set_aspect("equal", adjustable="box")
ax.set_facecolor("black")
ax.grid(False, color="white", linewidth=0.5)
ax.set_facecolor("black")
last_frame: Optional[np.ndarray] = None
running = True


def cleanup() -> None:
    """Release all resources on exit."""
    global last_frame
    if last_frame is not None:
        try:
            plt.close(fig)
        except Exception:
            pass
        last_frame = None
    if Serial is not None:
        try:
            if hasattr(fig, "canvas") and fig.canvas:
                fig.canvas.close()
        except Exception:
            pass
        try:
            if hasattr(fig, "figure") and fig.figure:
                fig.figure.close()
        except Exception:
            pass
        try:
            if hasattr(fig, "close"):
                fig.close()
        except Exception:
            pass


def handle_signal(signum, frame) -> None:
    """Graceful shutdown on SIGINT / SIGTERM."""
    global running
    running = False


signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)


def parse_thermal_frame(raw_line: str) -> Optional[np.ndarray]:
    """
    Parse a comma-separated 24x32 frame from *raw_line*.

    Returns a 2-D float32 array of shape (FRAME_HEIGHT, FRAME_WIDTH) or
