import logging
import signal
import subprocess
import sys
import time

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

FAN_PIN = 14
PWM_FREQUENCY = 100
CHECK_INTERVAL = 5
DEGREE_SYMBOL = "\u00B0C"

_running = True


def _handle_signal(signum, frame):
    global _running
    logging.info("Received signal %s, shutting down...", signum)
    _running = False


def get_temperature():
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            check=True,
            timeout=5,
        )
        return result.stdout.strip().replace("temp=", "").replace("'C", "")
    except FileNotFoundError:
        logging.error("vcgencmd not found; is this running on a Raspberry Pi?")
    except subprocess.TimeoutExpired:
        logging.error("vcgencmd timed out")
    except subprocess.CalledProcessError as exc:
        logging.error("vcgencmd failed (rc=%s): %s", exc.returncode, exc.stderr.strip())
    except Exception as exc:
        logging.error("Unexpected error reading temperature: %s", exc)
    return None


def get_fan_speed():
    try:
        with open("/sys/class/gpio/gpio%d/direction", FAN_PIN) as f:
            if f.read().strip() != "out":
                logging.error("GPIO%d is not configured as output", FAN_PIN)
                return None
        with open("/sys/class/gpio/gpio%d/value", FAN_PIN) as f:
            return float(f.read().strip())
    except (OSError, ValueError) as exc:
        logging.error("Failed to read fan speed from GPIO%d: %s", FAN_PIN, exc)
        return None


def set_fan_speed(speed):
    try:
        with open("/sys/class/gpio/gpio%d/direction", FAN_PIN) as f:
            if f.read().strip() != "out":
                logging.error("GPIO%d is not configured as output", FAN_PIN)
                return
        with open("/sys/class/gpio/gpio%d/value", FAN_PIN) as f:
            f.write(str(int(speed)))
    except OSError as exc:
        logging.error("Failed to set fan speed to %s: %s", speed, exc)


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    fan_pwm = None
    try:
        try:
            import RPi.GPIO as GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(FAN_PIN, GPIO.OUT)
            fan_pwm = GPIO.PWM(FAN_PIN, PWM_FREQUENCY)
            fan_pwm.start(0)
            logging.info("PWM fan control started on GPIO%d at %d Hz", FAN_PIN, PWM_FREQUENCY)
        except (ImportError, RuntimeError, ValueError) as exc:
            logging.warning("RPi.GPIO unavailable (%s); falling back to software PWM", exc)
            fan_pwm = None
    except Exception as exc:
        logging.warning("Failed to initialize GPIO (%s); continuing in degraded mode", exc)
        fan_pwm = None

    fan_speed = get_fan_speed()
    if fan_speed is None:
        logging.warning("Could not read initial fan speed; starting at 0%%")
        fan_speed = 0.0

    logging.info("Initial fan speed: %.1f%%", fan_speed)

    try:
        while _running:
            temperature = get_temperature()
            if temperature is None:
                logging.warning("Temperature read failed; keeping last fan speed")
            else:
                logging.info("Temperature: %s", temperature)
                if fan_pwm is not None:
                    try:
                        fan_pwm.ChangeDutyCycle(fan_speed)
                    except Exception as exc:
                        logging.error("Failed to update PWM duty cycle: %s", exc)
                else:
                    logging.info("Software PWM duty cycle set to %.1f%%", fan_speed)
            for _ in range(CHECK_INTERVAL):
                if not _running:
                    break
                time.sleep(1)
    finally:
        if fan_pwm is not None:
            try:
                fan_pwm.stop()
            except Exception:
                pass
        if fan_pwm is not None:
            try:
                fan_pwm.close()
            except Exception:
                pass
        try:
            import RPi.GPIO as GPIO
            GPIO.cleanup()
        except Exception:
            pass
        logging.info("Cleanup complete")


if __name__ == "__main__":
    main()

