import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 2.0
ALERT_TEMP = 30.0
ALERT_HUM = 70.0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def read_sensor_data():
    try:
        data = sensor.read()
        if data is None:
            return None, None
        if len(data) < 6:
            return None, None
        try:
            temperature = float(data[0])
            humidity = float(data[2])
        except ValueError:
            return None, None
        return temperature, humidity
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected error reading sensor data: {e}")
        return None, None

def check_alerts(temperature, humidity):
    if temperature > ALERT_TEMP:
        print(f"ALERT: Temperature exceeds {ALERT_TEMP}°C!")
    if humidity > ALERT_HUM:
        print(f"ALERT: Humidity exceeds {ALERT_HUM}%!")

def main():
    global sensor
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        sensor = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}")
        sys.exit(1)

    try:
        while running:
            temperature, humidity = read_sensor_data()
            if temperature is not None and humidity is not None:
                try:
                    sensor.write(f"{temperature},{humidity}\n".encode('utf-8'))
                    sensor.flush()
                except serial.SerialException as e:
                    print(f"Error writing to serial port: {e}")
                check_alerts(temperature, humidity)
            time.sleep(1)
    finally:
        if sensor.is_open:
            sensor.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

