#!/usr/bin/env python3
"""
Air Quality Monitoring System for Raspberry Pi 5

Simulates an air quality sensor, logs data, and alerts when PPM exceeds threshold.
Uses gpiozero for the LED placeholder.
"""

import time
import logging
import random
import sys
from gpiozero import LED

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Constants
LED_PIN = 17
PPM_THRESHOLD = 500
SAMPLE_INTERVAL = 5  # seconds

# Global LED object for cleanup
led = None


def get_temperature():
    """Simulate temperature reading between 20.00°C and 30.00°C."""
    return round(random.uniform(20.0, 30.0), 2)


def get_humidity():
    """Simulate humidity reading between 40.00% and 60.00%."""
    return round(random.uniform(40.0, 60.0), 2)


def get_ppm():
    """Simulate PPM reading between 0 and 800."""
    return random.randint(0, 800)


def main():
    global led

    # Initialize LED
    try:
        led = LED(LED_PIN)
        logging.info(f"LED initialized on GPIO{LED_PIN}")
    except Exception as e:
        logging.error(f"Failed to initialize LED on GPIO{LED_PIN}: {e}")
        sys.exit(1)

    try:
        while True:
            temperature = get_temperature()
            humidity = get_humidity()
            ppm = get_ppm()

            logging.info(
                f"Temperature: {temperature}°C, Humidity: {humidity}%, PPM: {ppm}"
            )

            if ppm > PPM_THRESHOLD:
                logging.warning(
                    f"ALERT! PPM level exceeded threshold. "
                    f"Temperature: {temperature}°C, Humidity: {humidity}%, PPM: {ppm}"
                )

            time.sleep(SAMPLE_INTERVAL)

    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if led is not None:
            led.close()
            logging.info("LED resource released.")


if __name__ == "__main__":
    main()

