#!/usr/bin/env python3
"""
LED control program for Raspberry Pi.

Hardware:
  - LED (any colour) with a 330 ohm resistor connected between GPIO17 (BCM)
    and GND.

Behavior:
  - Reads keyboard input; toggles the LED state on each key press.
  - Prints the current LED state after each input.
  - Prints "Exiting program" when the user requests shutdown.
  - On any exit path (normal, interrupt, or error) drives the LED low
    and releases the GPIO pin.
"""

import sys
import time

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO is not installed. Install with: sudo apt install python3-rpi.gpio")
    sys.exit(1)

LED_PIN = 17
led_state = False
running = True


def cleanup_gpio():
    """Drive the LED low and release the GPIO pin."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception:
        pass
    try:
        GPIO.cleanup(LED_PIN)
    except Exception:
        pass


def handle_input(input_char):
    """Toggle the LED state based on the input character."""
    global led_state
    if input_char == "o":
        led_state = not led_state
    elif input_char == "q":
        running = False
    else:
        print("Invalid input")


def main():
    global led_state, running

    # --- GPIO setup with error handling -------------------------------------------------
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"Error: Failed to initialize GPIO: {e}")
        sys.exit(1)

    print("LED control program started. Press 'o' to toggle, 'q' to quit.")
    print("Press Ctrl+C to exit.")

    try:
