import sys
import time
import signal
import threading
import logging
from typing import Optional

from DOG import DOG  # Assuming DOG is a library with a receive() and send() API

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
DEFAULT_INTERVAL = 0.1  # seconds
DEFAULT_FILENAME = "data.log"

# Global state
_running = True
_log_file = None
_log_lock = threading.Lock()
_api_started = False


def _signal_handler(signum, frame):
    """Handle SIGINT and SIGTERM to ensure clean shutdown."""
    global _running
    logger.info(f"Received signal {signum}, shutting down...")
    _running = False


def _init_gpio() -> bool:
    """Initialize GPIO resources. Returns True on success, False on failure."""
    try:
        # Attempt to import RPi.GPIO to check for hardware availability
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        logger.info("GPIO initialized successfully.")
        return True
    except (ImportError, RuntimeError, ValueError) as e:
        logger.warning(f"GPIO initialization failed (not running on a Pi or hardware error): {e}")
        return False


def _cleanup_gpio() -> None:
    """Clean up GPIO resources."""
    try:
        import RPi.GPIO as GPIO
        if GPIO.getinit():
            GPIO.cleanup()
            logger.info("GPIO cleaned up.")
    except Exception as e:
        logger.warning(f"GPIO cleanup error: {e}")


def _start_logging(filename: str, interval: float = DEFAULT_INTERVAL) -> None:
    """Start logging to a file in a background thread."""
    global _log_file, _log_lock, _running
    if _running:
        return

    if not _init_gpio():
        logger.warning("Skipping file logging due to GPIO initialization failure.")
        return

    try:
        _log_file = open(filename, "a", encoding="utf-8")
        _log_lock.acquire()
        logger.info(f"Logging started to '{filename}' at {interval}s interval.")
        _running = True

        while _running:
            try:
                data = DOG.receive()
                if data is not None:
                    with _log_lock:
                        _log_file.write(str(data) + "\n")
                        _log_file.flush()
            except Exception as e:
                logger.error(f"Error receiving data: {e}")
                break
            time.sleep(interval)

    except IOError as e:
        logger.error(f"File I/O error: {e}")
    except Exception as e:
        logger.error(f"Unexpected error in logging thread: {e}")
    finally:
        with _log_lock:
            if _log_file:
                _log_file.close()
                logger.info(f"Log file closed: {DEFAULT_FILENAME}")
        _log_file = None
        _log_lock.release()
        _running = False
        _cleanup_gpio()


def _start_logging_thread(filename: str, interval: float = DEFAULT_INTERVAL) -> None:
    """Start the logging thread."""
    global _api_started
    if _api_started:
        logger.info("Logging thread already started.")
        return

    t = threading.Thread(target=_start_logging, args=(filename, interval), daemon=True)
    t.start()
    _api_started = True


def _stop_logging() -> None:
    """Stop logging and release resources."""
    global _log_file, _log_lock, _running
    if not _running:
        return

    with _log_lock:
        if _log_file:
            try:
                _log_file.close()
                logger.info("Log file closed.")
            except IOError as e:
                logger.error(f"Error closing log file: {e}")
            finally:
                _log_file = None
        _log_lock.release()
        _running = False
        _cleanup_gpio()
        _api_started = False


def _display_log() -> None:
    """Display the current contents of the log file."""
    global _log_file, _log_lock
    if not _log_file:
        logger.warning("No log file open. Use 'start <filename>' to begin logging.")
        return

    with _log_lock:
        if _log_file:
            try:
                content = _log_file.read()
                if content:
                    print(content, end="")
                else:
                    print("Log file is empty.")
            except IOError as e:
                logger.error(f"Error reading log file: {e}")
            except Exception as e:
                logger.error(f"Unexpected error displaying log: {e}")
        else:
            logger.warning("No log file open.")


def _write_to_log(data: str) -> None:
    """Write data directly to the log file with a newline."""
    global _log_file, _log_lock
    if not _log_file:
        logger.warning("No log file open. Use 'start <filename>' to begin logging.")
        return

    with _log_lock:
        if _log_file:
            try:
                _log_file.write(data + "\n")
                _log_file.flush()
            except IOError as e:
                logger.error(f"Error writing to log file: {e}")
            except Exception as e:
                logger.error(f"Unexpected error writing to log: {e}")


def _send_data(data: str) -> None:
    """Send data via DOG.send()."""
    global _api_started
    if not _api_started:
        logger.warning("DOG API not started. Use 'start <filename>' to begin logging.")
        return

    try:
        DOG.send(data)
        logger.info(f"Sent data: {data}")
    except Exception as e:
        logger.error(f"Error sending data: {e}")


def _help(command: str) -> None:
    """Display help information for a given command."""
    if not command:
        logger.warning("No command provided. Use 'help <command>' for information.")
        return

    help_messages = {
        "help": "Call 'help' without an argument for information.",
        "start": "Start logging data to a file. Usage: start <filename>",
        "stop": "Stop the logging process. Usage: stop",
        "display": "Display the current log file contents. Usage: display",
        "send": "Send data via DOG.send(). Usage: send <data>",
        "write": "Write data directly to the log file. Usage: write <data>",
        "exit": "Exit the logging application. Usage: exit",
    }

    if command in help_messages:
        print(help_messages[command])
    else:
        logger.warning(f"Unknown command: {command}. Try 'help <command>'")


def _process_command(command: str) -> None:
    """Process a single command from the user."""
    global _running, _log_file, _log_lock, _api_started

    if not command:
        return

    parts = command.split()
    if not parts:
        return

    cmd = parts[0].lower()
    args = parts[1:]

    if cmd == "help":
        _help(" ".join(args))
        return

    if cmd == "start":
        if len(args) < 2:
            logger.warning("Usage: start <filename>")
            return
        filename = args[0]
        _start_logging_thread(filename, DEFAULT_INTERVAL)
        return

    if cmd == "stop":
        _stop_logging()
        return

    if cmd == "display":
        _display_log()
        return

    if cmd == "send":
        if len(args) < 1:
            logger.warning("Usage: send <data>")
            return
        _send_data(" ".join(args))
        return

    if cmd == "write":
        if len(args) < 1:
            logger.warning("Usage: write <data>")
            return
        _write_to_log(" ".join(args))
        return

    if cmd == "exit":
        _stop_logging()
        return

    logger.warning(f"Unknown command: {command}")


def main() -> None:
    """Main entry point for the command-line interface."""
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    logger.info("Starting DOG command-line interface...")

    try:
        while _running:
            try:
                command = input("Enter command: ").strip()
            except EOFError:
                logger.info("EOF received, exiting.")
                break

            if not command:
                continue

            _process_command(command)

    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        _stop_logging()
        logger.info("Exiting DOG command-line interface.")


if __name__ == "__main__":
    main()

