import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO can only run on a Raspberry Pi.", file=sys.stderr)
    sys.exit(1)

PIR_PIN = 4
MONITOR_SECONDS = 20
DEBOUNCE_DELAY = 0.3

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as exc:
        print(f"Error: failed to initialize GPIO pin {PIR_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    motion_count = 0
    last_state = None

    try:
        while _running:
            try:
                current_state = GPIO.input(PIR_PIN)
            except Exception as exc:
                print(f"Warning: failed to read GPIO pin {PIR_PIN}: {exc}", file=sys.stderr)
                time.sleep(0.1)
                continue

            if current_state != last_state:
                if current_state == GPIO.HIGH:
                    print("Motion detected!")
