import signal
import sys
import time
import logging

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

try:
    from adafruit_tsl2561 import TSL2561
    from board import SCL, SDA
    from busio import I2C
except ImportError as exc:
    print(f"Missing dependency: {exc}", file=sys.stderr)
    print("Install with: pip install adafruit-circuitpython-tsl2561 gpiozero board", file=sys.stderr)
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("light_to_brightness")

I2C_BUS = 1
TSL2561_ADDR = 0x29
LED_PIN = 18
PWM_FREQ = 1000.0
READ_INTERVAL = 1.0
INTEGRATION_TIME = 402
GAIN_ENABLE = True

_running = True
_pwm = None
_sensor = None
_i2c = None


def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received – shutting down.", signum)
    _running = False


def _cleanup():
    global _pwm, _sensor, _i2c
    if _pwm is not None:
        try:
            _pwm.close()
        except Exception:
            pass
        _pwm = None
    if _sensor is not None:
        try:
            _sensor.deinit()
        except Exception:
            pass
        _sensor = None
    if _i2c is not None:
        try:
            _i2c.deinit()
        except Exception:
            pass
        _i2c = None


def _init_hardware():
    global _i2c, _sensor, _pwm
    try:
        _i2c = I2C(I2C_BUS, SCL=SCL, SDA=SDA)
    except Exception as exc:
        log.error("Failed to initialise I2C bus %d: %s", I2C_BUS, exc)
        return False

    try:
        _sensor = TSL2561(_i2c, address=TSL2561_ADDR)
    except Exception as exc:
        log.error("TSL2561 not detected at 0x%02X on bus %d: %s", TSL2561_ADDR, I2C_BUS, exc)
        return False

    try:
        _pwm = PWMOutputDevice(LED_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except GPIOZeroError as exc:
        log.error("Failed to initialise PWM on GPIO%d: %s", LED_PIN, exc)
        return False
    except Exception as exc:
        log.error("Unexpected error initialising PWM on GPIO%d: %s", LED_PIN, exc)
        return False

    if not _sensor.enabled:
        log.warning("TSL2561 auto-gain disabled – enabling it.")
        try:
            _sensor.enabled = True
        except Exception as exc:
            log.warning("Failed to re-enable auto-gain: %s", exc)

    return True


def _read_lux():
    try:
        return _sensor.lux
    except Exception as exc:
        log.error("I2C read error from TSL2561: %s", exc)
        return None


def _map_lux_to_brightness(lux):
    if lux is None:
        return 0.0
    return max(0.0, min(100.0, lux / 65535.0 * 100.0))


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not _init_hardware():
        _cleanup()
        sys.exit(1)

    log.info("TSL2561 -> PWM on GPIO%d @ %d Hz, integration=%d ms, auto-gain enabled.",
             LED_PIN, PWM_FREQ, INTEGRATION_TIME)

    try:
        while _running:
            lux = _read_lux()
            if lux is None:
                time.sleep(READ_INTERVAL)
                continue

            brightness = _map_lux_to_brightness(lux)
            _pwm.value = brightness / 100.0
            print(f"Lux: {lux:.2f}  Brightness: {brightness:.1f}%")
            time.sleep(READ_INTERVAL)
    except Exception as exc:
        log.exception("Fatal error in main loop: %s", exc)
    finally:
        _cleanup()
        log.info("Program terminated.")


if __name__ == "__main__":
    main()

