import time
import signal
import sys
import RPi.GPIO as GPIO

# GPIO pins wired to the two TCRT5000 infrared line sensors (BCM numbering)
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6

# Sampling interval in seconds
SAMPLE_INTERVAL = 0.5
# Number of samples to collect
NUM_SAMPLES = 10


def read_sensor(pin):
    """Read a TCRT5000 sensor: 0 for black line, 1 for white surface."""
    try:
        return GPIO.input(pin)
    except Exception as exc:
        print(f"Error reading GPIO pin {pin}: {exc}")
        return None


def determine_direction(left_value, right_value):
    """Return a steering direction string based on sensor values."""
    if left_value is None or right_value is None:
        return "sensor error"
    if left_value == right_value:
        return "forward"
    if left_value == 1 and right_value == 0:
        return "turn left"
    if left_value == 0 and right_value == 1:
        return "turn right"
    return "search"


def cleanup_gpio():
    """Safely release GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception:
        pass


def main():
    # Use Broadcom (BCM) pin numbering
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)

    # Configure both sensor pins as inputs with pull-down resistors
    try:
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as exc:
        print(f"Failed to configure GPIO pins: {exc}")
        cleanup_gpio()
        sys.exit(1)

    # Graceful shutdown on SIGINT (Ctrl-C) and SIGTERM
    def signal_handler(signum, frame):
        print("\nInterrupt received, cleaning up...")
        cleanup_gpio()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        for i in range(NUM_SAMPLES):
            left_value = read_sensor(LEFT_SENSOR_PIN)
            right_value = read_sensor(RIGHT_SENSOR_PIN)

            direction = determine_direction(left_value, right_value)
            print(f"Sample {i + 1}: left={left_value if left_value is not None else 'error'} "
                  f"right={right_value if right_value is not None else 'error'} -> {direction}")

            if i < NUM_SAMPLES - 1:
                time.sleep(SAMPLE_INTERVAL)

    except Exception as exc:
        print(f"Unexpected error: {exc}")
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

