#!/usr/bin/env python3
"""
Raspberry Pi driver for the 1.44-inch ST7735S TFT display (128x128).

Wiring (BCM numbering):
  RST  -> GPIO 18
  DC   -> GPIO 22
  LED  -> GPIO 23
  SPI0 -> CE0  (SPI0, CE0), SCLK=GPIO11, MOSI=GPIO10, SDA=GPIO9

The display is driven via a self-contained SPI driver.  The program
initializes the display, displays a character set, text blocks, and
simple geometric shapes, then cleans up GPIO and SPI resources on
exit.
"""

import signal
import sys
import time

import RPi.GPIO as GPIO
import spidev

# ---------------------------------------------------------------------------
# Pin / bus configuration
# ---------------------------------------------------------------------------
RST_PIN = 18
DC_PIN = 22
LED_PIN = 23

SPI_BUS = 0
SPI_DEVICE = 0          # CE0
SPI_MAX_SPEED_HZ = 16_000_000   # 16 MHz – safe for the ST7735S
SPI_MODE = 0b00

# ST7735S constants
ST7735S_WIDTH = 128
ST7735S_HEIGHT = 128

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_spi = None
_running = True


def _cleanup():
    """Release GPIO and SPI resources."""
    global _spi
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if _spi is not None:
        try:
            _spi.close()
        except Exception:
            pass
        _spi = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _spi_open():
    """Open and configure the SPI bus; raise on failure."""
    spi = spidev.SpiDev()
    try:
        spi.open(SPI_BUS, SPI_DEVICE)
    except Exception as exc:
        raise RuntimeError(f"Failed to open SPI bus {SPI_BUS}.{SPI_DEVICE}: {exc}") from exc
    spi.max_speed_hz = SPI_MAX_SPEED_HZ
    spi.mode = SPI_MODE
    spi.bits_per_word = 8
    return spi


def _gpio_setup():
    """Configure GPIO pins; raise on failure."""
    GPIO.setwarnings(False)
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(RST_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(DC_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)


def _spi_write(data):
    """Write a list of bytes to the SPI device."""
    GPIO.output(DC_PIN, GPIO.LOW)
    _spi.xfer2(data)


def _spi_write_cmd(cmd):
    """Send a single command byte."""
    _spi_write([cmd])


def _spi_write_data(data):
    """Send a list of data bytes."""
    _spi_write(data)


