import signal
import sys
import time
import logging

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO can only be used on a Raspberry Pi.")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21
START_SIGNAL = 1
END_SIGNAL = 0
TRANSMIT_DELAY = 0.0005
RECEPTION_TIMEOUT = 1.0

_running = True


def _signal_handler(signum, frame):
    global _running
    logging.info(f"Signal {signum} received, shutting down...")
    _running = False


def _cleanup_gpio():
    try:
        GPIO.cleanup()
        logging.info("GPIO cleanup completed.")
    except Exception as e:
        logging.error(f"Error during GPIO cleanup: {e}")


def _set_gpio(pin, state):
    try:
        GPIO.output(pin, state)
    except Exception as e:
        logging.error(f"Error setting GPIO pin {pin} to {state}: {e}")
        raise


def _toggle_gpio(pin, state):
    _set_gpio(pin, state)
    time.sleep(TRANSMIT_DELAY)


def _read_gpio(pin):
    try:
        return GPIO.input(pin)
    except Exception as e:
        logging.error(f"Error reading GPIO pin {pin}: {e}")
        raise


def _wait_for_signal(pin, timeout=RECEPTION_TIMEOUT):
    start_time = time.time()
    while _running and GPIO.input(pin) == 0:
        if time.time() - start_time > timeout:
            logging.warning(f"Timeout waiting for signal on pin {pin}")
            return False
        time.sleep(0.0001)
    return True


def _send_bit(data, timer_pin):
    _toggle_gpio(DATA_OUT_PIN, 1)
    _toggle_gpio(timer_pin, 1)
    _toggle_gpio(DATA_OUT_PIN, 0)
    _toggle_gpio(timer_pin, 0)


def _receive_bit(timer_pin):
    bit = 0
    while _running and GPIO.input(timer_pin) == 0:
        time.sleep(0.0001)
    if not _running:
        return None
    bit = 1 if GPIO.input(timer_pin) else 0
    while _running and GPIO.input(timer_pin) == 1:
        time.sleep(0.0001)
    return bit


def _send(data):
    for bit in data:
        _send_bit(bit, TIMER_OUT_PIN)


def _receive():
    data = []
    while _running:
        bit = _receive_bit(TIMER_IN_PIN)
        if bit is None:
            break
        data.append(bit)
    return data


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)

        GPIO.setup(DATA_OUT_PIN, GPIO.OUT, initial=0)
        GPIO.setup(TIMER_OUT_PIN, GPIO.OUT, initial=0)
        GPIO.setup(DATA_IN_PIN, GPIO.IN)
        GPIO.setup(TIMER_IN_PIN, GPIO.IN)

        _set_gpio(TIMER_OUT_PIN, 0)

        if not _wait_for_signal(DATA_IN_PIN):
            logging.error("No START_SIGNAL received. Aborting.")
            return

        _set_gpio(TIMER_OUT_PIN, 1)
        _set_gpio(TIMER_OUT_PIN, 0)

        data = _receive()
        if not data:
            logging.error("No data received. Aborting.")
            return

        _send(data)

        received_data = _receive()
        if received_data != data:
            logging.error(f"Data mismatch: sent {data}, received {received_data}")
            return

        logging.info(f"Data transmission/reception successful: {data}")

    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        _cleanup_gpio()


if __name__ == "__main__":
    main()

