import time
import signal
import sys

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

PULSE_PIN = 17
PULSE_DURATION = 0.1

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        pulse = OutputDevice(PULSE_PIN, active_high=True, initial_value=False)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error: Failed to initialize GPIO {PULSE_PIN}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Error: Unexpected error during GPIO initialization: {e}")
        sys.exit(1)

    try:
        while _running:
            pulse.on()
            time.sleep(PULSE_DURATION)
            if not _running:
                break
            pulse.off()
            time.sleep(PULSE_DURATION)
    except KeyboardInterrupt:
        pass
    except Exception as e:
        print(f"Error: {e}")
    finally:
        try:
            pulse.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

