import signal
import threading
import logging
from enum import Enum
from typing import Optional

try:
    from gpiozero import OutputDevice
except ImportError:
    logging.error("gpiozero is not installed. Install with: pip install gpiozero")
    raise

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)


class PinValue(Enum):
    """Allowed values for a GPIO pin."""
    OFF = 0
    HIGH = 1


class OutputPin:
    """Generic output pin on a Raspberry Pi using gpiozero."""

    def __init__(self, pin: int, name: str, initial_value: PinValue = PinValue.OFF):
        if not isinstance(pin, int) or not 0 <= pin <= 27:
            raise ValueError(f"Invalid GPIO pin number: {pin!r}")
        if initial_value not in (PinValue.OFF, PinValue.HIGH):
            raise ValueError(f"Invalid initial_value: {initial_value!r}")

        self.name = name
        self.pin = pin
        self._value = initial_value
        self._device: Optional[OutputDevice] = None

        try:
            self._device = OutputDevice(pin=pin, active_high=True, initial_value=0)
            logger.info("OutputPin '%s' (BCM %d) initialized to %s", name, pin, initial_value)
        except Exception as exc:
            logger.error("Failed to initialize OutputPin '%s' (BCM %d): %s", name, pin, exc)
            self._cleanup()
            raise

    def set_value(self, value: PinValue) -> None:
        if value not in (PinValue.OFF, PinValue.HIGH):
            raise ValueError(f"Invalid value: {value!r}")
        if self._device is None:
            raise RuntimeError("OutputPin not initialized")
        self._value = value
        self._device.value = 1 if value == PinValue.HIGH else 0
        logger.info("%s -> %s", self.name, value)

    def get_value(self) -> PinValue:
        return self._value

    def shutdown(self) -> None:
        if self._device is not None:
            try:
                self._device.close()
            except Exception as exc:
                logger.warning("Error closing OutputDevice for '%s': %s", self.name, exc)
            finally:
                self._device = None
        logger.info("%s shutdown complete", self.name)

    def __repr__(self) -> str:
        return f"OutputPin(name={self.name!r}, pin={self.pin!r}, value={self._value!r})"


class TriggerPin(OutputPin):
    """Output pin that can be driven high for a short pulse."""

    def __init__(self, pin: int, name: str, pulse_high: bool = True):
        if not isinstance(pin, int) or not 0 <= pin <= 27:
            raise ValueError(f"Invalid GPIO pin number: {pin!r}")
        if not isinstance(pulse_high, bool):
            raise ValueError(f"pulse_high must be bool, got {type(pulse_high).__name__}")

        super().__init__(pin, name, initial_value=PinValue.OFF)
        self.pulse_high = pulse_high
        self._lock = threading.Lock()
        self._last_state = None

        if self.pulse_high:
            logger.info("TriggerPin '%s' (BCM %d) initialized for high pulse", name, pin)
        else:
            logger.info("TriggerPin '%s' (BCM %d) initialized (pulse_high=False)", name, pin)

    def trigger(self) -> None:
        if self._device is None:
            raise RuntimeError("TriggerPin not initialized")
        with self._lock:
            if self._last_state is None:
                self.set_value(PinValue.HIGH)
                self._last_state = self.get_value()
            else:
                if self._last_state == PinValue.HIGH:
                    self.set_value(PinValue.OFF)
                else:
                    self.set_value(PinValue.HIGH)
            logger.info("Trigger pulse generated on '%s'", self.name)

    def shutdown(self) -> None:
        super().shutdown()
        if self.pulse_high:
            logger.info("TriggerPin '%s' (BCM %d) will be left in HIGH state", self.name, self.pin)


def _signal_handler(signum, frame):
    logger.info("Signal %d received, shutting down pins", signum)
    raise SystemExit(0)


def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        example_output = OutputPin(pin=21, name="ExampleOutput", initial_value=PinValue.OFF)
        example_trigger = TriggerPin(pin=20, name="ExampleTrigger", pulse_high=True)
    except Exception as exc:
        logger.error("Failed to initialize pins: %s", exc)
        return

    try:
        example_output.set_value(PinValue.HIGH)
        example_trigger.trigger()
        example_output.set_value(PinValue.OFF)
    except Exception as exc:
        logger.error("Runtime error: %s", exc)
    finally:
        example_output.shutdown()
        example_trigger.shutdown()
        logger.info("Program terminated cleanly")


if __name__ == "__main__":
    main()

