SIREN_LED_PIN = 26
SAMPLE_COUNT = 8
SAMPLE_INTERVAL = 0.4
BOUNCE_TIME = 0.05

_running = True

def _handle_sigint(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_sigint)

    try:
        door_sensor = Button(DOOR_SENSOR_PIN, pull_up=False, bounce_time=BOUNCE_TIME)
