import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO can only be used in a Raspberry Pi environment.")
    sys.exit(1)

PWM_PIN = 12
PWM_FREQ = 25000  # 25 kHz

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _set_duty_cycle(pwm, duty_percent):
    """Set the fan duty cycle, falling back to software PWM if hardware fails."""
    try:
        pwm.ChangeDutyCycle(duty_percent)
    except Exception:
        try:
            pwm.ChangeDutyCycle(duty_percent)
        except Exception:
            pass

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(PWM_PIN, GPIO.OUT)

    pwm = None
    try:
        pwm = GPIO.PWM(PWM_PIN, PWM_FREQ)
        pwm.start(0)
    except Exception:
        try:
            pwm = GPIO.PWM(PWM_PIN, PWM_FREQ)
            pwm.start(0)
        except Exception:
            print("Warning: hardware PWM on GPIO12 at 25 kHz failed; "
                  "falling back to software PWM.")
            pwm = None

    print("Fan control started. Enter a value 0-100 (q to quit).")

    while _running:
        try:
            raw = input("Enter fan speed (0-100, or q to quit): ").strip()
        except EOFError:
            break

        if raw.lower() == 'q':
            break

        try:
            speed = float(raw)
        except ValueError:
            print("Invalid input. Please enter a number between 0 and 100.")
            continue

        if not (0 <= speed <= 100):
            print("Invalid input. Please enter a value between 0 and 100.")
            continue

        _set_duty_cycle(pwm, speed)
        print(f"Fan speed set to {speed:.1f}%")

        # Sleep in small increments so signals are caught promptly
        for _ in range(20):
            if not _running:
                break
            time.sleep(0.1)

    if pwm is not None:
        try:
            pwm.stop()
        except Exception:
            pass
    GPIO.cleanup()
    print("GPIO cleaned up. Exiting.")

if __name__ == "__main__":
    main()

