import signal
import sys
import time

try:
    import smbus2 as smbus
except ImportError:
    import smbus

I2C_BUS = 1
I2C_ADDR = 0x23
READ_INTERVAL_S = 1.0
MAX_RETRIES = 3
RETRY_DELAY_S = 0.5

_running = True


def _handle_sigint(signum, frame):
    global _running
    _running = False


def _init_bus():
    try:
        return smbus.SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        return None


def _read_lux(bus):
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            bus.read_i2c_block_data(I2C_ADDR, 0x00, 2)
            return bus.read_i2c_block_data(I2C_ADDR, 0x00, 2)[0] | (0x10000 << 8)
        except OSError as exc:
            if attempt == MAX_RETRIES:
                raise
            time.sleep(RETRY_DELAY_S)
    return None


def main():
    signal.signal(signal.SIGINT, _handle_sigint)
    bus = _init_bus()
    if bus is None:
        sys.exit(1)
    try:
        while _running:
            lux = _read_lux(bus)
            if lux is not None:
                print(f"Lux: {lux:.2f}")
            else:
                print("Error: failed to read BH1750 after multiple retries.", file=sys.stderr)
            time.sleep(READ_INTERVAL_S)
    finally:
        try:
            bus.close()
        except Exception:
            pass
        print("Program terminated.")


if __name__ == "__main__":
