import signal
import sys
import time

try:
    import smbus2 as smbus
except ImportError:
    import smbus

I2C_BUS = 1
BH1750_ADDR = 0x23
MEASURE_CMD = 0x20
REBOOT_CMD = 0x01
CONTINOUS_MODE = 0x10
LOW_POWER_MODE = 0x00
HIGH_POWER_MODE = 0x01
MEASURE_DELAY_S = 0.12
PAUSE_S = 3.0

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _write_cmd(bus, cmd):
    bus.write_byte(BH1750_ADDR, cmd)


def _read_lux(bus):
    _write_cmd(bus, MEASURE_CMD)
    time.sleep(MEASURE_DELAY_S)
    data = bus.read_i2c_block_data(BH1750_ADDR, 0x00, 2)
    raw = (data[0] << 8) | data[1]
    lux = raw / 1.2
    return max(0.0, lux)


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        bus = smbus.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        _write_cmd(bus, REBOOT_CMD)
        time.sleep(0.01)
    except OSError as e:
        print(f"Error: BH1750 not detected at address 0x{BH1750_ADDR:02X} on bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        bus.read_byte(BH1750_ADDR)
    except OSError as e:
        print(f"Error: BH1750 not detected at address 0x{BH1750_ADDR:02X} on bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        bus.read_byte(BH1750_ADDR)
    except OSError as e:
        print(f"Error: I2C communication failed: {e}", file=sys.stderr)
        sys.exit(2)

    print("BH1750 detected. Starting continuous mode.")
    _write_cmd(bus, CONTINOUS_MODE)
    print("Reading illuminance (lux)...")

    try:
        while _running:
            try:
                lux = _read_lux(bus)
            except OSError as e:
                print(f"Error: I2C communication failed: {e}", file=sys.stderr)
                break
            print(f"Illuminance: {lux:.2f} lux")
            if _running:
                time.sleep(PAUSE_S)
    finally:
        try:
            bus.close()
        except Exception:
            pass
        print("Program terminated.")


if __name__ == "__main__":
    main()

