#!/usr/bin/env python3
"""
Rainbow HAT 3-bit binary counter

Touchpads A (GPIO5), B (GPIO6), C (GPIO12) toggle the three
bit states (MSB=4, MSB=2, LSB=1).  The display shows the decimal
value, the APA102 strip shows the value in red/green/blue, and a
buzzer sounds 0.5 s of tone while the onboard green/blue LEDs are
lit accordingly.

Requires the Rainbow HAT (Pimoroni) and a Raspberry Pi.
"""

import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except Exception as exc:  # pragma: no cover - hardware dependent
    print(f"Warning: RPi.GPIO import failed: {exc}", file=sys.stderr)
    GPIO = None

try:
    import smbus2 as smbus
except Exception as exc:
    print(f"Warning: smbus2 import failed: {exc}", file=sys.stderr)
    smbus = None

try:
    import board
    import busio
    import adafruit_rainbowhat
except Exception as exc:
    print(f"Warning: Rainbow HAT library import failed: {exc}", file=sys.stderr)
    board = None
    busio = None
    adafruit_rainbowhat = None

# ---------------------------------------------------------------------------
# Pin assignments (BCM numbering)
# ---------------------------------------------------------------------------
TOUCH_PINS = [5, 6, 12]   # A, B, C
LED_DATA_PIN = 10
LED_CLOCK_PIN = 11
BUZZER_PIN = 13
GREEN_LED_PIN = 7
BLUE_LED_PIN = 8

# ---------------------------------------------------------------------------
# Globals (initialised in setup())
# ---------------------------------------------------------------------------
bit_states = [0, 0, 0]
display = None
rainbow = None
i2c = None
running = True


def cleanup():
    """Turn off all hardware resources cleanly."""
    global display, rainbow, i2c, running
    running = False
    try:
        if display is not None:
            try:
                display.clear()
            except Exception:
                pass
    except Exception as exc:
        print(f"Error clearing display: {exc}", file=sys.stderr)
    try:
        if rainbow is not None:
            try:
                rainbow.clear()
            except Exception as exc:
                print(f"Error clearing APA102 strip: {exc}", file=sys.stderr)
    except Exception as exc:
        print(f"Error clearing APA102 strip: {exc}", file=sys.stderr)
    try:
        if GPIO is not None:
            for pin in (LED_DATA_PIN, LED_CLOCK_PIN, BUZZER_PIN,
                        GREEN_LED_PIN, BLUE_LED_PIN):
                GPIO.output(pin, GPIO.LOW)
    except Exception as exc:
        print(f"Error turning off LEDs: {exc}", file=sys.stderr)
    try:
        if i2c is not None:
            i2c.close()
    except Exception as exc:
        print(f"Error closing I2C bus: {exc}", file=sys.stderr)
    try:
        if GPIO is not None:
            GPIO.cleanup()
    except Exception as exc:
        print(f"Error during GPIO cleanup: {exc}", file=sys.stderr)


def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    print(f"\nReceived signal {signum}, shutting down...")
    cleanup()
    sys.exit(0)


def setup():
    """Initialise hardware peripherals.  Returns True on success."""
    global display, rainbow, i2c, running

    # --- GPIO ---------------------------------------------------------------
    if GPIO is not None:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for pin in TOUCH_PINS + [LED_DATA_PIN, LED_CLOCK_PIN, BUZZER_PIN,
                                  GREEN_LED_PIN, BLUE_LED_PIN]:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)

    # --- Buzzer -------------------------------------------------------------
    try:
        GPIO.setup(BUZZER_PIN, GPIO.OUT)
        GPIO.output(BUZZER_PIN, GPIO.LOW)
    except Exception as exc:
        print(f"Warning: could not initialise buzzer on GPIO{BUZZER_PIN}: {exc}",
              file=sys.stderr)

    # --- Onboard LEDs -------------------------------------------------------
    try:
        GPIO.setup(GREEN_LED_PIN, GPIO.OUT)
        GPIO.setup(BLUE_LED_PIN, GPIO.OUT)
        GPIO.output(GREEN_LED_PIN, GPIO.LOW)
        GPIO.output(BLUE_LED_PIN, GPIO.LOW)
    except Exception as exc:
        print(f"Warning: could not initialise onboard LEDs: {exc}",
              file=sys.stderr)

    # --- APA102 LED strip ----------------------------------------------------
    try:
        import RPi APA102
        strip = RPi APA102.APA102(
            LED_DATA_PIN, LED_CLOCK_PIN,
            frequency=2000000, brightness=0.5, auto_write=False)
        strip.clear()
    except Exception as exc:
        print(f"Warning: could not initialise APA102 strip: {exc}",
              file=sys.stderr)
        strip = None

    # --- I2C / 14-segment display -------------------------------------------
    if smbus is not None:
        try:
            i2c = smbus.SMBus(1)
            display = adafruit_rainbowhat.RainbowHat(i2c)
            display.clear()
        except Exception as exc:
            print(f"Warning: could not initialise I2C display: {exc}",
                  file=sys.stderr)
            display = None

    # --- Rainbow HAT ---------------------------------------------------------
    if board is not None and busio is not None and adafruit_rainbowhat is not None:
        try:
            rainbow = adafruit_rainbowhat.RainbowHat(board.D5, board.D6,
                                                   board.D12, board.D13,
                                                   board.D7, board.D8)
            rainbow.clear()
        except Exception as exc:
            print(f"Warning: could not initialise Rainbow HAT: {exc}",
                  file=sys.stderr)
            rainbow = None

    return True


def update_discrete_leds():
    """Drive the discrete LEDs from bit_states."""
    try:
        GPIO.output(GREEN_LED_PIN, GPIO.HIGH if bit_states[0] else GPIO.LOW)
        GPIO.output(BLUE_LED_PIN, GPIO.HIGH if bit_states[1] else GPIO.LOW)
    except Exception as exc:
        print(f"Error updating onboard LEDs: {exc}", file=sys.stderr)


def update_apa102(value):
    """Show the decimal value on the APA102 strip."""
    if strip is None:
        return
    try:
        if value == 0:
            for i in range(strip.numPixels()):
                strip.setPixelColor(i, strip.Color(255, 255, 255))
        elif value == 7:
            for i in range(strip.numPixels()):
                strip.setPixelColor(i, strip.Color(255, 255, 255))
        else:
            red = 255 if bit_states[0] else 0
            green = 255 if bit_states[1] else 0
            blue = 255 if bit_states[2] else 0
            for i in range(strip.numPixels()):
                strip.setPixelColor(i, strip.Color(red, green, blue))
        strip.show()
    except Exception as exc:
        print(f"Error updating APA102 strip: {exc}", file=sys.stderr)


def play_tone():
    """Sound a 0.5 s tone on the buzzer."""
    try:
        GPIO.output(BUZZER_PIN, GPIO.HIGH)
        time.sleep(0.5)
        GPIO.output(BUZZER_PIN, GPIO.LOW)
    except Exception as exc:
        print(f"Error playing buzzer tone: {exc}", file=sys.stderr)


def handle_touch(channel):
    """Toggle the bit state for the touchpad that pressed."""
    global bit_states
    try:
        if channel == 0:
            bit_states[0] = 1 - bit_states[0]
        elif channel == 1:
            bit_states[1] = 1 - bit_states[1]
        elif channel == 2:
            bit_states[2] = 1 - bit_states[2]
    except Exception as exc:
        print(f"Error toggling touchpad bit: {exc}", file=sys.stderr)
    update_discrete_leds()
    decimal = 0
    for i, bit in enumerate(bit_states):
        decimal += bit << (2 - i)
    update_apa102(decimal)
    play_tone()


def main():
    """Entry point: initialise hardware, wire touch callbacks, run loop."""
    global running

    if not setup():
        print("Hardware initialisation failed. Exiting.", file=sys.stderr)
        cleanup()
        sys.exit(1)

    # Wire touch callbacks
    for idx, pin in enumerate(TOUCH_PINS):
        try:
            GPIO.add_event_detect(pin, GPIO.FALLING,
                                  callback=lambda ch=idx: handle_touch(ch))
        except Exception as exc:
            print(f"Warning: could not add event detect for GPIO{pin}: {exc}",
                  file=sys.stderr)

    # Graceful shutdown on SIGINT / SIGTERM
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    print("Rainbow HAT 3-bit binary counter ready.  Press touchpads A/B/C "
          "to toggle bits (0-7).  Ctrl-C to exit.")
    print("Touchpad A (GPIO5)  ->  MSB (value 4)"
          "\nTouchpad B (GPIO6)  ->  MSB (value 2)"
          "\nTouchpad C (GPIO12) ->  LSB (value 1)")
    print("Press Ctrl-C to exit.\n")

    try:
        while running:
            time.sleep(0.1)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()


if __name__ == "__main__":
    main()

