import argparse
import json
import logging
import os
import signal
import sys
import time
import urllib.request
from collections import deque

import smbus2
import tflite_runtime.interpreter as tflite

try:
    from ina219 import INA219, DeviceRangeError
except ImportError:
    INA219 = None
    DeviceRangeError = Exception

try:
    from waveshare_i2c_vibration import Waveshare_I2C_Vibration
except ImportError:
    Waveshare_I2C_Vibration = None

DEFAULT_CONFIG = {
    "bus_number": 1,
    "x_address": 0x48,
    "y_address": 0x49,
    "z_address": 0x4A,
    "scale_factor": 2.0,
    "shunt_resistance": 0.1,
    "threshold": 0.5,
    "endpoint": "http://example.com/alerts",
    "model_path": "model.tflite",
    "log_file": "vibration_alerts.log",
    "simulate": False,
    "window_size": 5,
    "failure_probability_threshold": 0.8,
}


class SensorReadError(Exception):
    pass


class VibrationSensor:
    def __init__(self, bus_number, x_address, y_address, z_address, scale_factor, shunt_resistance, simulate=False):
        self.bus_number = bus_number
        self.x_address = x_address
        self.y_address = y_address
        self.z_address = z_address
        self.scale_factor = scale_factor
        self.shunt_resistance = shunt_resistance
        self.simulate = simulate
        self.bus = None
        self.x = None
        self.y = None
        self.z = None

        if not self.simulate:
            try:
                self.bus = smbus2.SMBus(bus_number)
            except Exception as e:
                logging.error(f"Failed to open I2C bus {bus_number}: {e}")
                raise SensorReadError(f"Failed to open I2C bus {bus_number}: {e}")

        if not self.simulate:
            try:
                if isinstance(self.x, Waveshare_I2C_Vibration):
                    self.x = self.x.read()
                else:
                    self.x = Waveshare_I2C_Vibration(self.bus, self.x_address)
                    self.x.read()
            except Exception as e:
                logging.error(f"Error reading X-axis sensor: {e}")
                self.close()
                raise SensorReadError(f"Error reading X-axis sensor: {e}")

        if not self.simulate:
            try:
                if isinstance(self.y, Waveshare_I2C_Vibration):
                    self.y = self.y.read()
                else:
                    self.y = Waveshare_I2C_Vibration(self.bus, self.y_address)
                    self.y.read()
            except Exception as e:
                logging.error(f"Error reading Y-axis sensor: {e}")
                self.close()
                raise SensorReadError(f"Error reading Y-axis sensor: {e}")

        if not self.simulate:
            try:
                if isinstance(self.z, Waveshare_I2C_Vibration):
                    self.z = self.z.read()
                else:
                    self.z = Waveshare_I2C_Vibration(self.bus, self.z_address)
                    self.z.read()
            except Exception as e:
                logging.error(f"Error reading Z-axis sensor: {e}")
                self.close()
                raise SensorReadError(f"Error reading Z-axis sensor: {e}")

    def read(self):
        x = self.x.read() if self.x else None
        y = self.y.read() if self.y else None
        z = self.z.read() if self.z else None

        if self.simulate:
            x = self._simulate(x) if x is not None else None
            y = self._simulate(y) if y is not None else None
            z = self._simulate(z) if z is not None else None

        return x, y, z

    def _simulate(self, value):
        return value + (0.1 if value > 0 else -0.1)

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
            self.bus = None


class CurrentSensor:
    def __init__(self, bus_number, shunt_resistance, simulate=False):
        self.bus_number = bus_number
        self.shunt_resistance = shunt_resistance
        self.simulate = simulate
        self.bus = None
        self.current = None

        if not self.simulate:
            try:
                self.bus = smbus2.SMBus(bus_number)
            except Exception as e:
                logging.error(f"Failed to open I2C bus {bus_number}: {e}")
                raise SensorReadError(f"Failed to open I2C bus {bus_number}: {e}")

        if not self.simulate:
            try:
                self.current = INA219(self.shunt_resistance, busnum=self.bus_number, address=None)
                self.current.configure()
            except Exception as e:
                logging.error(f"Error configuring INA219: {e}")
                self.close()
                raise SensorReadError(f"Error configuring INA219: {e}")

    def read(self):
        if self.simulate:
            return self._simulate()

        try:
            return self.current.get_current()
        except DeviceRangeError:
            logging.error("Current sensor out of range.")
            return None
        except Exception as e:
            logging.error(f"Error reading current sensor: {e}")
            return None

    def _simulate(self):
        return 0.1

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
            self.bus = None


def load_config(config_file):
    config = dict(DEFAULT_CONFIG)
    try:
        with open(config_file, "r") as f:
            user_config = json.load(f)
        config.update(user_config)
    except FileNotFoundError:
        logging.warning(f"Configuration file not found: {config_file}. Using defaults.")
    except json.JSONDecodeError:
        logging.error(f"Error decoding configuration file: {config_file}. Using defaults.")
    except Exception as e:
        logging.error(f"Unexpected error loading configuration file: {e}. Using defaults.")
    return config


def run_inference(interpreter, x, y, z):
    try:
        input_details = interpreter.get_input_details()
        output_details = interpreter.get_output_details()

        x_data = [x] if isinstance(x, (list, tuple)) else [x]
        y_data = [y] if isinstance(y, (list, tuple)) else [y]
        z_data = [z] if isinstance(z, (list, tuple)) else [z]

        input_shape = input_details[0]["shape"]
        if len(input_shape) == 4:
            x_data = x_data + [1] * (input_shape[1] - 1)
            y_data = y_data + [1] * (input_shape[2] - 1)
            z_data = z_data + [1] * (input_shape[3] - 1)
        elif len(input_shape) == 3:
            x_data = x_data + [1] * (input_shape[1] - 1)
            y_data = y_data + [1] * (input_shape[2] - 1)
            z_data = z_data + [1] * (input_shape[0] - 1)

        interpreter.set_tensor(input_details[0]["index"], x_data)
        interpreter.set_tensor(input_details[1]["index"], y_data)
        interpreter.set_tensor(input_details[2]["index"], z_data)

        interpreter.invoke()
        output_data = interpreter.get_tensor(output_details[0]["index"])
        return float(output_data[0][0])
    except Exception as e:
        logging.error(f"Error running inference: {e}")
        return None


def send_alert(endpoint, failure_probability):
    try:
        data = {"failure_probability": failure_probability}
        req = urllib.request.Request(endpoint, data=data.encode("utf-8"), method="POST")
        with urllib.request.urlopen(req, timeout=5) as response:
            if response.status == 200:
                logging.info("Alert sent successfully.")
            else:
                logging.warning(f"Alert sent but server returned status {response.status}.")
    except Exception as e:
        logging.error(f"Error sending alert: {e}")


def main():
    parser = argparse.ArgumentParser(description="Vibration monitoring system using TensorFlow Lite.")
    parser.add_argument("--config", type=str, default=None, help="Path to the JSON configuration file.")
    args = parser.parse_args()

    config = load_config(args.config) if args.config else DEFAULT_CONFIG

    logging.basicConfig(
        filename=config["log_file"],
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )

    signal.signal(signal.SIGINT, lambda s, f: sys.exit(0))

    try:
        x_sensor = VibrationSensor(
            config["bus_number"],
            config["x_address"],
            config["y_address"],
            config["z_address"],
            config["scale_factor"],
            config["shunt_resistance"],
            config["simulate"],
        )
        current_sensor = CurrentSensor(
            config["bus_number"],
            config["shunt_resistance"],
            config["simulate"],
        )
    except SensorReadError as e:
        logging.error(f"Failed to initialize sensors: {e}")
        return

    x_history = deque(maxlen=config["window_size"])
    y_history = deque(maxlen=config["window_size"])
    z_history = deque(maxlen=config["window_size"])
    current_history = deque(maxlen=config["window_size"])

    interpreter = None
    try:
        interpreter = tflite.Interpreter(model_path=config["model_path"])
        interpreter.allocate_tensors()
        logging.info("TensorFlow Lite model loaded successfully.")
    except Exception as e:
        logging.error(f"Failed to load TensorFlow Lite model: {e}")
        return

    try:
        while True:
            x, y, z = x_sensor.read()
            x_history.append(x)
            y_history.append(y)
            z_history.append(z)

            current = current_sensor.read()
            current_history.append(current)

            if len(x_history) < config["window_size"]:
                x = sum(x_history) / len(x_history) if x_history else 0
                y = sum(y_history) / len(y_history) if y_history else 0
                z = sum(z_history) / len(z_history) if z_history else 0
            else:
                x = sum(x_history) / config["window_size"]
                y = sum(y_history) / config["window_size"]
                z = sum(z_history) / config["window_size"]

            if current is not None:
                current = current / config["scale_factor"]

            failure_probability = run_inference(interpreter, x, y, z)

            if failure_probability is not None:
                logging.info(f"Failure probability: {failure_probability:.4f}")
                if failure_probability > config["failure_probability_threshold"]:
                    send_alert(config["endpoint"], failure_probability)
            else:
                logging.warning("Inference failed. Skipping alert.")

            time.sleep(1)

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if interpreter is not None:
            try:
                interpreter.deallocate_tensors()
            except Exception:
                pass
        x_sensor.close()
        current_sensor.close()
        logging.info("Program terminated.")


if __name__ == "__main__":
    main()

