        with open(config_file, "r") as f:
            user_config = json.load(f)
        config.update(user_config)
    except FileNotFoundError:
        logging.warning(f"Configuration file not found: {config_file}. Using defaults.")
    except json.JSONDecodeError:
        logging.error(f"Error decoding configuration file: {config_file}. Using defaults.")
    except Exception as e:
        logging.error(f"Unexpected error loading configuration file: {e}. Using defaults.")
    return config


def run_inference(interpreter, x, y, z):
    try:
        input_details = interpreter.get_input_details()
        output_details = interpreter.get_output_details()

        x_data = [x] if isinstance(x, (list, tuple)) else [x]
        y_data = [y] if isinstance(y, (list, tuple)) else [y]
        z_data = [z] if isinstance(z, (list, tuple)) else [z]

        input_shape = input_details[0]["shape"]
        if len(input_shape) == 4:
            x_data = x_data + [1] * (input_shape[1] - 1)
            y_data = y_data + [1] * (input_shape[2] - 1)
            z_data = z_data + [1] * (input_shape[3] - 1)
        elif len(input_shape) == 3:
            x_data = x_data + [1] * (input_shape[1] - 1)
            y_data = y_data + [1] * (input_shape[2] - 1)
            z_data = z_data + [1] * (input_shape[0] - 1)

        interpreter.set_tensor(input_details[0]["index"], x_data)
        interpreter.set_tensor(input_details[1]["index"], y_data)
        interpreter.set_tensor(input_details[2]["index"], z_data)

        interpreter.invoke()
        output_data = interpreter.get_tensor(output_details[0]["index"])
        return float(output_data[0][0])
    except Exception as e:
        logging.error(f"Error running inference: {e}")
        return None


def send_alert(endpoint, failure_probability):
    try:
        data = {"failure_probability": failure_probability}
        req = urllib.request.Request(endpoint, data=data.encode("utf-8"), method="POST")
        with urllib.request.urlopen(req, timeout=5) as response:
            if response.status == 200:
                logging.info("Alert sent successfully.")
            else:
                logging.warning(f"Alert sent but server returned status {response.status}.")
    except Exception as e:
        logging.error(f"Error sending alert: {e}")


def main():
    parser = argparse.ArgumentParser(description="Vibration monitoring system using TensorFlow Lite.")
    parser.add_argument("--config", type=str, default=None, help="Path to the JSON configuration file.")
    args = parser.parse_args()

    config = load_config(args.config) if args.config else DEFAULT_CONFIG

    logging.basicConfig(
        filename=config["log_file"],
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )

    signal.signal(signal.SIGINT, lambda s, f: sys.exit(0))

    try:
        x_sensor = VibrationSensor(
            config["bus_number"],
            config["x_address"],
            config["y_address"],
            config["z_address"],
            config["scale_factor"],
            config["shunt_resistance"],
            config["simulate"],
        )
        current_sensor = CurrentSensor(
            config["bus_number"],
            config["shunt_resistance"],
            config["simulate"],
        )
    except SensorReadError as e:
        logging.error(f"Failed to initialize sensors: {e}")
        return

    x_history = deque(maxlen=config["window_size"])
    y_history = deque(maxlen=config["window_size"])
    z_history = deque(maxlen=config["window_size"])
    current_history = deque(maxlen=config["window_size"])

    interpreter = None
    try:
        interpreter = tflite.Interpreter(model_path=config["model_path"])
        interpreter.allocate_tensors()
        logging.info("TensorFlow Lite model loaded successfully.")
    except Exception as e:
        logging.error(f"Failed to load TensorFlow Lite model: {e}")
        return

    try:
        while True:
            x, y, z = x_sensor.read()
            x_history.append(x)
            y_history.append(y)
            z_history.append(z)

            current = current_sensor.read()
            current_history.append(current)

            if len(x_history) < config["window_size"]:
                x = sum(x_history) / len(x_history) if x_history else 0
                y = sum(y_history) / len(y_history) if y_history else 0
                z = sum(z_history) / len(z_history) if z_history else 0
            else:
                x = sum(x_history) / config["window_size"]
                y = sum(y_history) / config["window_size"]
                z = sum(z_history) / config["window_size"]

            if current is not None:
                current = current / config["scale_factor"]

            failure_probability = run_inference(interpreter, x, y, z)

            if failure_probability is not None:
                logging.info(f"Failure probability: {failure_probability:.4f}")
                if failure_probability > config["failure_probability_threshold"]:
                    send_alert(config["endpoint"], failure_probability)
            else:
                logging.warning("Inference failed. Skipping alert.")

            time.sleep(1)

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if interpreter is not None:
            try:
                interpreter.deallocate_tensors()
            except Exception:
                pass
        x_sensor.close()
        current_sensor.close()
        logging.info("Program terminated.")


if __name__ == "__main__":
    main()

