NUM_READINGS = 5
LOW_THRESHOLD = 20
HIGH_THRESHOLD = 80

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def read_water_level():
    return random.randint(0, 100)


def control_pump(level):
    if level < LOW_THRESHOLD:
        GPIO.output(PUMP_PIN, GPIO.HIGH)
        return "ON"
    elif level > HIGH_THRESHOLD:
        GPIO.output(PUMP_PIN, GPIO.LOW)
        return "OFF"
    else:
        return GPIO.input(PUMP_PIN)


def main():
    global _running

    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)

    GPIO.setup(SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    GPIO.setup(PUMP_PIN, GPIO.OUT, initial=GPIO.LOW)

    try:
        for i in range(NUM_READINGS):
            if not _running:
                break

            level = read_water_level()
            pump_state = control_pump(level)
            sensor_state = GPIO.input(SENSOR_PIN)

            print(f"Reading {i + 1}/{NUM_READINGS} - Water Level: {level}%")
            print(f"  Pump: {pump_state} | Sensor: {'HIGH' if sensor_state else 'LOW'}")

            if i < NUM_READINGS - 1 and _running:
                time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

