import argparse
import csv
import logging
import signal
import sys
import time
from datetime import datetime

try:
    import smbus2
except ImportError:
    print("Error: smbus2 is required. Install with: pip install smbus2", file=sys.stderr)
    sys.exit(1)

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
I2C_BUS = 1
ADXL345_ADDR = 0x53
ADXL345_DEVID = 0x00
ADXL345_ID = 0x00
ADXL345_DEVID_EXPECTED = 0xE5
ADXL345_POWER_CTL = 0x2D
ADXL345_DATA_FORMAT = 0x31
ADXL345_DATAX0 = 0x32
ADXL345_BW_RATE = 0x2C
ADXL345_BW_RATE_MAX = 0x0F
ADXL345_BW_RATE_DEFAULT = 0x0A
ADXL345_BW_RATE_HZ = 0x0A  # 100 Hz

DATA_FORMAT_10BIT = 0x00
DATA_FORMAT_16BIT = 0x08
DATA_FORMAT_16BIT_SCALE = 16384.0

POWER_CTL_MEASURE = 0x08
POWER_CTL_DISABLE = 0x00

# ---------------------------------------------------------------------------
# Globals for signal handling
# ---------------------------------------------------------------------------
_running = True
_bus = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _init_bus():
    """Open the I2C bus and verify the ADXL345 is present and ID is correct."""
    global _bus
    try:
        _bus = smbus2.SMBus(I2C_BUS)
    except OSError as exc:
        logging.error("Cannot open I2C bus %d: %s", I2C_BUS, exc)
        return False

    try:
        devid = _read_u16(ADXL345_ADDR, ADXL345_DEVID)
    except OSError as exc:
        logging.error("ADXL345 not found at 0x%02X on bus %d: %s", ADXL345_ADDR, I2C_BUS, exc)
        try:
            _bus.close()
        except OSError:
            pass
        _bus = None
        return False

    if devid != ADXL345_DEVID_EXPECTED:
        logging.error("ADXL345 ID mismatch: got 0x%02X, expected 0x%02X", devid, ADXL345_DEVID_EXPECTED)
        try:
            _bus.close()
        except OSError:
            pass
        _bus = None
        return False

    logging.info("ADXL345 detected (ID=0x%02X, devid=0x%02X) on bus %d", ADXL345_ADDR, devid, I2C_BUS)
    return True


def _read_u16(addr, register):
    """Read a 16-bit big-endian value from two consecutive registers."""
    try:
        data = _bus.read_i2c_block_data(ADXL345_ADDR, register, 2)
    except OSError as exc:
        raise
    return (data[0] << 8) | data[1]


def _write_u16(addr, register, value):
    """Write a 16-bit big-endian value to two consecutive registers."""
    try:
        _bus.write_i2c_block_data(ADXL345_ADDR, register, [(value >> 8) & 0xFF, value & 0xFF])
    except OSError as exc:
        raise
    return True


def _read_s16(addr, register):
    """Read a signed 16-bit value from two consecutive registers."""
    val = _read_u16(addr, register)
    if val & 0x8000:
        val -= 1 << 16
    return val


def _init_sensor():
    """Configure the ADXL345 for continuous measurement at the default 100 Hz."""
    try:
        _write_u16(ADXL345_ADDR, ADXL345_DATA_FORMAT, DATA_FORMAT_16BIT)
    except OSError as exc:
        raise
    try:
        _write_u16(ADXL345_ADDR, ADXL345_BW_RATE, ADXL345_BW_RATE_DEFAULT)
    except OSError as exc:
        raise
    try:
        _write_u16(ADXL345_ADDR, ADXL345_POWER_CTL, POWER_CTL_MEASURE)
    except OSError as exc:
        raise


def _read_accel():
    """Read x, y, z acceleration in g (signed 16-bit)."""
    try:
        raw = _read_s16(ADXL345_ADDR, ADXL345_DATAX0)
    except OSError as exc:
        raise
    x = raw >> 4
    z = (raw & 0x000F) << 4
    y = (raw & 0xF0) >> 4
    return x, y, z


def _compute_magnitude(x, y, z):
    return (x * x + y * y + z * z) ** 0.5


def _log_sample(timestamp, x, y, z, magnitude, threshold):
    """Append one timestamped acceleration row to the CSV data file."""
    try:
        with open("data.txt", "a", newline="") as fh:
            csv.writer(fh).writerow([timestamp, f"{x:.4f}", f"{y:.4f}", f"{z:.4f}", f"{magnitude:.4f}", f"{threshold:.2f}"])
    except OSError as exc:
        logging.error("Failed to write data row: %s", exc)


def main():
    global _running

    parser = argparse.ArgumentParser(description="ADXL345 accelerometer reader for Raspberry Pi")
    parser.add_argument("--sample_rate", type=float, default=10.0, help="Sampling rate in Hz (default 10)")
    parser.add_argument("--threshold", type=float, default=1.5, help="Acceleration threshold in g (default 1.5)")
    args = parser.parse_args()

    if args.sample_rate <= 0:
        print("Error: --sample_rate must be positive", file=sys.stderr)
        sys.exit(0)

    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not _init_bus():
        sys.exit(0)

    try:
        _init_sensor()
    except OSError as exc:
        logging.error("Failed to initialise ADXL345: %s", exc)
        try:
            _bus.close()
        except OSError:
            pass
        _bus = None
        sys.exit(0)

    logging.info("Starting continuous sampling at %.1f Hz, threshold %.2f g", args.sample_rate, args.threshold)

    try:
        while _running:
            try:
                x, y, z = _read_accel()
                magnitude = _compute_magnitude(x, y, z)
                if magnitude > args.threshold:
                    logging.warning("ALERT: acceleration %.4f g exceeds threshold %.2f g", magnitude, args.threshold)
                _log_sample(datetime.now().isoformat(), x, y, z, magnitude, args.threshold)
            except OSError as exc:
                logging.error("I2C read error: %s", exc)
            except Exception as exc:
                logging.error("Unexpected error: %s", exc)

            if _running:
                sleep_time = 1.0 / args.sample_rate
                time.sleep(sleep_time)
    finally:
        if _bus is not None:
            try:
                _bus.close()
            except OSError:
                pass
            _bus = None
        logging.info("Program terminated.")


if __name__ == "__main__":
    main()

