    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

ALERT_PIN = 18
CHECKS = 5
DELAY_SECONDS = 2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def get_water_quality():
    return random.randint(0, 100)

def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    led = None
    try:
        led = LED(ALERT_PIN)
    except GPIOZeroError as exc:
        print(f"Error: failed to initialize LED on BCM pin {ALERT_PIN}: {exc}")
        sys.exit(1)

    try:
        for i in range(CHECKS):
            if not _running:
                break

            quality = get_water_quality()
            print(f"Water Quality: {quality}%")

            if quality < 50:
                led.on()
                print("Alert: Water quality is low!")
            else:
                led.off()
                print("Water quality is normal.")

            if i < CHECKS - 1 and _running:
                time.sleep(DELAY_SECONDS)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    finally:
        if led is not None:
            try:
                led.off()
                led.close()
            except Exception:
                pass
        print("LED turned off. Exiting gracefully.")

if __name__ == "__main__":
    main()

