#!/usr/bin/env python3
"""
Raspberry Pi Zero W Bird Deterrent System

Drives two KY-006 passive piezo buzzer modules as a bird deterrent.
Optionally lights an indicator LED for each buzzer.
"""

import argparse
import logging
import random
import signal
import sys
import time

from gpiozero import PWMOutputDevice, OutputDevice
from gpiozero.exc import GPIODeviceError, GPIOPinInvalid

# Constants
DEFAULT_LOG_FILE = "bird_deterrent.log"
DEFAULT_BUZZER_FREQUENCY = 20_000  # Hz
DEFAULT_DUTY_CYCLE = 50.0          # percent
DEFAULT_SENSOR_THRESHOLD = 70
DEFAULT_CHECK_INTERVAL = 60         # seconds
DEFAULT_CHIRP_DURATION = 0.3        # seconds
DEFAULT_GAP = 0.1                  # seconds
DEFAULT_MAX_SENSOR_VALUE = 100

# Global state for cleanup
_buzzers = []
_leds = []
_running = True


def parse_arguments():
    """Parse and validate command-line arguments."""
    parser = argparse.ArgumentParser(
        description="Bird Deterrent System for Raspberry Pi Zero W"
    )
    parser.add_argument(
        "--gpio_buzzer1", type=int, required=True,
        help="BCM GPIO pin for buzzer 1 (e.g., 17)"
    )
    parser.add_argument(
        "--gpio_buzzer2", type=int, required=True,
        help="BCM GPIO pin for buzzer 2 (e.g., 18)"
    )
    parser.add_argument(
        "--gpio_led1", type=int, required=True,
        help="BCM GPIO pin for LED 1 (e.g., 22)"
    )
    parser.add_argument(
        "--gpio_led2", type=int, required=True,
        help="BCM GPIO pin for LED 2 (e.g., 23)"
    )
    parser.add_argument(
        "--log_file", type=str, default=DEFAULT_LOG_FILE,
        help="Path to the log file (default: bird_deterrent.log)"
    )
    parser.add_argument(
        "--frequency", type=int, default=DEFAULT_BUZZER_FREQUENCY,
        help="Default buzzer frequency in Hz (default: 20,000)"
    )
    parser.add_argument(
        "--duty_cycle", type=float, default=DEFAULT_DUTY_CYCLE,
        help="Default buzzer duty cycle in percent (default: 50)"
    )
    parser.add_argument(
        "--threshold", type=int, default=DEFAULT_SENSOR_THRESHOLD,
        help="Sensor value threshold to trigger chirping (default: 70)"
    )
    parser.add_argument(
        "--check_interval", type=int, default=DEFAULT_CHECK_INTERVAL,
        help="Time in seconds between sensor checks (default: 60)"
    )
    parser.add_argument(
        "--chirp_duration", type=float, default=DEFAULT_CHIRP_DURATION,
        help="Duration of each chirp in seconds (default: 0.3)"
    )
    parser.add_argument(
        "--gap", type=float, default=DEFAULT_GAP,
        help="Gap between chirps in seconds (default: 0.1)"
    )
    parser.add_argument(
        "--max_sensor_value", type=int, default=DEFAULT_MAX_SENSOR_VALUE,
        help="Maximum simulated sensor value (default: 100)"
    )
    return parser.parse_args()


def setup_logging(log_file):
    """Configure logging to file and console."""
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
        handlers=[
            logging.FileHandler(log_file),
            logging.StreamHandler(sys.stdout),
        ],
    )


def validate_gpio_pins(pins):
    """Validate that all GPIO pins are valid BCM numbers."""
    valid_pins = set(range(2, 27))  # BCM 2-27
    for pin in pins:
        if pin not in valid_pins:
            raise ValueError(
                f"Invalid BCM pin number: {pin}. Must be between 2 and 27."
            )


def initialize_gpio(pins, frequency, duty_cycle):
    """Initialize PWM output devices for buzzers and LEDs."""
    global _buzzers, _leds
    try:
        validate_gpio_pins(pins)
    except ValueError as e:
        logging.error(str(e))
        sys.exit(1)

    _buzzers = []
    _leds = []

    for name, pin in [("buzzer1", pins[0]), ("buzzer2", pins[1]), ("led1", pins[2]), ("led2", pins[3])]:
        try:
            if name == "buzzer1":
                device = PWMOutputDevice(pin, frequency=frequency, initial_value=0)
            elif name == "buzzer2":
                device = PWMOutputDevice(pin, frequency=frequency, initial_value=0)
            elif name == "led1":
                device = OutputDevice(pin, initial_value=False)
            elif name == "led2":
                device = OutputDevice(pin, initial_value=False)
            else:
                raise ValueError(f"Unknown device type: {name}")
            _buzzers.append(device)
            _leds.append(device)
            logging.info(f"Initialized {name} on GPIO {pin}")
        except (GPIOPinInvalid, GPIODeviceError) as e:
            logging.error(f"Failed to initialize {name} on GPIO {pin}: {e}")
            sys.exit(1)
        except Exception as e:
            logging.error(f"Unexpected error initializing {name} on GPIO {pin}: {e}")
            sys.exit(1)

    return _buzzers, _leds


def generate_chirp(buzzer, frequency, duty_cycle, duration, gap):
    """Generate a single chirp with a random frequency and duration."""
    try:
        buzzer.frequency = frequency
        buzzer.duty_cycle = duty_cycle
        time.sleep(duration)
        buzzer.duty_cycle = 0
        time.sleep(gap)
    except Exception as e:
        logging.error(f"Error generating chirp: {e}")
        raise


def trigger_chirp(buzzer, frequency, duty_cycle, duration, gap):
    """Trigger a single chirp on the given buzzer."""
    try:
        generate_chirp(buzzer, frequency, duty_cycle, duration, gap)
    except Exception as e:
        logging.error(f"Error triggering chirp: {e}")


def simulate_sensor_reading(max_value):
    """Simulate a sensor reading as a random integer."""
    return random.randint(0, max_value)


def decide_activation(sensor_value, threshold):
    """Decide whether to activate the buzzer based on sensor value."""
    return sensor_value > threshold


def cleanup(signum=None, frame=None):
    """Clean up GPIO resources and exit."""
    global _running
    _running = False
    logging.info("Cleaning up GPIO resources...")
    for buzzer in _buzzers:
        try:
            buzzer.close()
        except Exception as e:
            logging.error(f"Error closing buzzer: {e}")
    for led in _leds:
        try:
            led.close()
        except Exception as e:
            logging.error(f"Error closing LED: {e}")
    logging.info("Cleanup complete. Exiting.")
    if signum is not None:
        sys.exit(0)


def main():
    """Main function to run the bird deterrent system."""
    global _running
    args = parse_arguments()
    setup_logging(args.log_file)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        buzzer1, buzzer2, led1, led2 = initialize_gpio(
            [args.gpio_buzzer1, args.gpio_buzzer2, args.gpio_led1, args.gpio_led2],
            args.frequency, args.duty_cycle,
        )
    except Exception as e:
        logging.error(f"Failed to initialize GPIO: {e}")
        sys.exit(1)

    logging.info("Bird Deterrent System started.")
    logging.info(
        f"Threshold: {args.threshold}, Interval: {args.check_interval}s, "
        f"Chirp Duration: {args.chirp_duration}s, Gap: {args.gap}s"
    )

    try:
        while _running:
            sensor_value = simulate_sensor_reading(args.max_sensor_value)
            logging.info(f"Simulated sensor value: {sensor_value}")

            if decide_activation(sensor_value, args.threshold):
                logging.info("Bird detected! Activating buzzer.")
                try:
                    trigger_chirp(buzzer1, args.frequency, args.duty_cycle, args.chirp_duration, args.gap)
                    trigger_chirp(buzzer2, args.frequency, args.duty_cycle, args.chirp_duration, args.gap)
                except Exception as e:
                    logging.error(f"Error triggering chirps: {e}")
            else:
                logging.info("No bird detected.")

            # Wait for the specified interval, but allow early exit
            for _ in range(args.check_interval):
                if not _running:
                    break
                time.sleep(1)

    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

