import time
import math
import signal
import sys
import threading
import logging
import argparse

try:
    import smbus2
except ImportError:
    smbus2 = None

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    PWMOutputDevice = None

# Constants
I2C_BUS = 1
MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
GYRO_XOUT_H = 0x43
GYRO_YOUT_H = 0x45
GYRO_ZOUT_H = 0x47
GYRO_SCALE = 131.0
PWM_FREQ = 50
PWM_MAX = 100.0
LOG_FILE = "log.txt"
LOG_INTERVAL = 1.0
LOOP_TIME = 0.01
MOTOR_PINS = {1: 17, 2: 18, 3: 27}

# Global state
kp_x = 1.0
kp_y = 1.0
kp_z = 1.0
running = True
pwm_objects = {}
bus = None
input_lock = threading.Lock()
input_queue = []

def signal_handler(sig, frame):
    global running
    running = False

def read_gyro_data(bus):
    try:
        data = bus.read_i2c_block_data(MPU6050_ADDR, GYRO_XOUT_H, 6)
        gyro_x = (data[0] << 8) | data[1]
        gyro_y = (data[2] << 8) | data[3]
        gyro_z = (data[4] << 8) | data[5]
        if gyro_x >= 0x8000:
            gyro_x -= 0x10000
        if gyro_y >= 0x8000:
            gyro_y -= 0x10000
        if gyro_z >= 0x8000:
            gyro_z -= 0x10000
        return gyro_x / GYRO_SCALE, gyro_y / GYRO_SCALE, gyro_z / GYRO_SCALE
    except IOError as e:
        logging.error(f"I2C read error: {e}")
        return 0.0, 0.0, 0.0

def integrate_gyro(gyro_x, gyro_y, gyro_z, dt):
    return gyro_x * dt, gyro_y * dt, gyro_z * dt

def calculate_angular_displacement(gyro_x, gyro_y, gyro_z, dt):
    return gyro_x * dt, gyro_y * dt, gyro_z * dt

def calculate_pwm(disp_x, disp_y, disp_z, kp_x, kp_y, kp_z):
    pwm_x = abs(kp_x * disp_x)
    pwm_y = abs(kp_y * disp_y)
    pwm_z = abs(kp_z * disp_z)
    pwm_x = min(pwm_x, PWM_MAX)
    pwm_y = min(pwm_y, PWM_MAX)
    pwm_z = min(pwm_z, PWM_MAX)
    return pwm_x, pwm_y, pwm_z

def set_motor_pwm(motor_num, pwm_x, pwm_y, pwm_z):
    if motor_num not in pwm_objects:
        pwm_objects[motor_num] = {}
    if motor_num not in pwm_objects[motor_num]:
        pwm_objects[motor_num][0] = PWMOutputDevice(MOTOR_PINS[motor_num], frequency=PWM_FREQ, initial_value=0)
        pwm_objects[motor_num][1] = PWMOutputDevice(MOTOR_PINS[motor_num], frequency=PWM_FREQ, initial_value=0)
    pwm_objects[motor_num][0].value = pwm_x / PWM_MAX
    pwm_objects[motor_num][1].value = pwm_y / PWM_MAX
    logging.info(f"Motor {motor_num}: X={pwm_x:.2f}, Y={pwm_y:.2f}, Z={pwm_z:.2f}")

def stop_motor(motor_num):
    if motor_num in pwm_objects:
        pwm_objects[motor_num][0].value = 0
        pwm_objects[motor_num][1].value = 0
    logging.info(f"Motor {motor_num} stopped")

def cleanup():
    for motor_num in pwm_objects:
        stop_motor(motor_num)
    if PWMOutputDevice:
        for motor_num in pwm_objects:
            for dev in pwm_objects[motor_num].values():
                dev.close()
    if bus:
        bus.close()
    logging.info("Cleanup complete")

def log_data(disp_x, disp_y, disp_z, pwm_x, pwm_y, pwm_z):
    logging.info(f"Timestamp: {time.strftime('%Y-%m-%d %H:%M:%S')}, X: {disp_x:.2f}, Y: {disp_y:.2f}, Z: {disp_z:.2f}, PWM: X={pwm_x:.2f}, Y={pwm_y:.2f}, Z={pwm_z:.2f}")

def input_thread():
    global kp_x, kp_y, kp_z, running
    while running:
        try:
            command = input("Enter command (kp x, kp y, kp z, quit): ").strip().lower()
            if not command:
                continue
            if "kp x" in command:
                try:
                    kp_x = float(command.split("kp x")[1].strip())
                except ValueError:
                    logging.warning("Invalid kp x value")
            elif "kp y" in command:
                try:
                    kp_y = float(command.split("kp y")[1].strip())
                except ValueError:
                    logging.warning("Invalid kp y value")
            elif "kp z" in command:
                try:
                    kp_z = float(command.split("kp z")[1].strip())
                except ValueError:
                    logging.warning("Invalid kp z value")
            elif command == "quit":
                running = False
            else:
                logging.warning("Invalid command")
        except Exception as e:
            logging.error(f"Input error: {e}")
        time.sleep(0.1)

def main():
    global bus, running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    logging.basicConfig(filename=LOG_FILE, level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
    parser = argparse.ArgumentParser(description="MPU6050 Gyroscope Control")
    parser.add_argument("--kp_x", type=float, default=1.0, help="Proportional gain for X-axis")
    parser.add_argument("--kp_y", type=float, default=1.0, help="Proportional gain for Y-axis")
    parser.add_argument("--kp_z", type=float, default=1.0, help="Proportional gain for Z-axis")
    args = parser.parse_args()
    kp_x = args.kp_x
    kp_y = args.kp_y
    kp_z = args.kp_z
    try:
        if smbus2:
            bus = smbus2.SMBus(I2C_BUS)
            bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0)
            logging.info("MPU6050 initialized")
        else:
            logging.warning("smbus2 not installed, continuing without I2C")
    except IOError as e:
        logging.error(f"Failed to initialize I2C: {e}")
        bus = None
    input_thread = threading.Thread(target=input_thread, daemon=True)
    input_thread.start()
    last_log_time = time.time()
    try:
        while running:
            now = time.time()
            if now - last_log_time >= LOG_INTERVAL:
                last_log_time = now
                disp_x, disp_y, disp_z = 0.0, 0.0, 0.0
                dt = LOOP_TIME
                gyro_x, gyro_y, gyro_z = read_gyro_data(bus)
                if bus:
                    gyro_x, gyro_y, gyro_z = integrate_gyro(gyro_x, gyro_y, gyro_z, dt)
                    disp_x, disp_y, disp_z = calculate_angular_displacement(gyro_x, gyro_y, gyro_z, dt)
                pwm_x, pwm_y, pwm_z = calculate_pwm(disp_x, disp_y, disp_z, kp_x, kp_y, kp_z)
                set_motor_pwm(1, pwm_x, pwm_y, pwm_z)
                set_motor_pwm(2, pwm_x, pwm_y, pwm_z)
                set_motor_pwm(3, pwm_x, pwm_y, pwm_z)
                log_data(disp_x, disp_y, disp_z, pwm_x, pwm_y, pwm_z)
            time.sleep(LOOP_TIME)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        running = False
        time.sleep(0.1)
        stop_motor(1)
        stop_motor(2)
        stop_motor(3)
        if PWMOutputDevice:
            for motor_num in pwm_objects:
                for dev in pwm_objects[motor_num].values():
                    dev.close()
        if bus:
            bus.close()
        logging.info("Program finished")

if __name__ == "__main__":
    main()

