import time
import math
import logging
import signal
import sys
import numpy as np
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

I2C_BUS = 1
MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B
ACCEL_SCALE = 16384.0
THRESHOLD_MAG = 2.5
THRESHOLD_VAR = 0.4
NUM_SAMPLES = 8
SAMPLE_DELAY = 0.01

running = True
bus = None

def signal_handler(signum, frame):
    global running
    logging.info(f"Signal {signum} received, shutting down...")
    running = False

def init_mpu6050(bus):
    try:
        bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0)
        time.sleep(0.1)
        logging.info("MPU6050 initialized successfully")
        return True
    except Exception as e:
        logging.error(f"Failed to initialize MPU6050: {e}")
        return False

def read_accelerometer(bus):
    try:
        data = bus.read_i2c_block_data(MPU6050_ADDR, ACCEL_XOUT_H, 6)
        x = (data[0] << 8) | data[1]
        y = (data[2] << 8) | data[3]
        z = (data[4] << 8) | data[5]
        if x >= 0x8000:
            x -= 0x10000
        if y >= 0x8000:
            y -= 0x10000
        if z >= 0x8000:
            z -= 0x10000
        return x, y, z
    except Exception as e:
        logging.error(f"Failed to read accelerometer data: {e}")
        return None, None, None

def calculate_rms(data):
    if len(data) < 2:
        return 0.0
    squared_sum = sum(x * x for x in data)
    return math.sqrt(squared_sum / len(data))

def calculate_variance(data):
    if len(data) < 2:
        return 0.0
    mean = calculate_rms(data)
    return sum((x - mean) ** 2 for x in data) / len(data)

def detect_defect(magnitude, variance):
    if magnitude > THRESHOLD_MAG or variance > THRESHOLD_VAR:
        return "DEFECTIVE"
    return "PASS"

def main():
    global bus
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

