import time
import logging
import signal
import sys
from gpiozero import PWMOutputDevice

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)


class ServoController:
    """Encapsulates an SG90 servo via a gpiozero PWM output device."""

    def __init__(self, pin: int, frequency: int = 50):
        self.pin = pin
        self.frequency = frequency
        self._device = None
        self._initialized = False
        try:
            self._device = PWMOutputDevice(pin, frequency=frequency)
            self._device.value = 0.0  # 0 % duty cycle -> neutral position
            self._initialized = True
            logger.info("Servo controller initialized on GPIO %d @ %d Hz", pin, frequency)
        except Exception as exc:
            logger.error("Failed to initialize servo on GPIO %d: %s", pin, exc)
            self._cleanup()
            raise

    def move_to(self, angle: float) -> None:
        """Drive the servo to the requested angle (0-180 degrees)."""
        if not self._initialized:
            raise RuntimeError("Servo not initialized")
        if not 0.0 <= angle <= 180.0:
            raise ValueError(f"Angle must be 0-180, got {angle}")
        duty = self._angle_to_duty_cycle(angle)
        try:
            self._device.value = duty
            logger.info("Moved servo to %d degrees (duty %.2f%%)", angle, duty)
        except Exception as exc:
            logger.error("Failed to move servo to %d: %s", angle, exc)
            raise

    def stop(self) -> None:
        """Stop the servo and release the PWM resource."""
        if self._initialized:
            try:
                self._device.value = 0.0
                logger.info("Servo stopped and GPIO released")
            except Exception as exc:
                logger.error("Error stopping servo: %s", exc)
            finally:
                self._cleanup()

    def _angle_to_duty_cycle(self, angle: float) -> float:
        """Convert an angle (0-180) to a gpiozero PWM value (0.0-1.0)."""
        return (angle / 180.0) + 0.5

    def _cleanup(self) -> None:
        """Release the underlying GPIO resource."""
        if self._device is not None:
            try:
                self._device.close()
            except Exception as exc:
                logger.warning("Error closing PWM device: %s", exc)
            finally:
                self._device = None
                self._initialized = False


def run_servo_sweep(controller: ServoController, angles: list) -> None:
    """Sweep the servo through a list of angles in ascending order."""
    for angle in angles:
        controller.move_to(angle)
        time.sleep(0.5)


def main() -> None:
    """Main entry point: sweep 0-180-0-180 in 45-degree steps."""
    servo_controller = None
    try:
        servo_controller = ServoController(pin=18, frequency=50)
        sweep_angles = [0, 45, 90, 135, 180]
        sweep_angles.extend(reversed(sweep_angles))
        logger.info("Starting servo sweep: %s", sweep_angles)
        run_servo_sweep(servo_controller, sweep_angles)
        logger.info("Sweep complete")
    except KeyboardInterrupt:
        logger.info("Interrupted by user")
    except Exception as exc:
        logger.error("Unexpected error: %s", exc)
    finally:
        if servo_controller is not None:
            servo_controller.stop()


if __name__ == "__main__":
    main()

