import RPi.GPIO as GPIO
import time
import sqlite3
import logging
import sys

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# GPIO pin definitions (BCM numbering)
SOLENOID_PINS = [17, 27, 22]  # solenoid 1, 2, 3
MICROSWITCH_PINS = [5, 6, 13]   # microswitch 1, 2, 3
IR_SENSOR_PIN = 4               # IR breakbeam sensor

# Seed types and their corresponding solenoid activation times (seconds)
SEED_TYPES = {
    'A': 0.2,
    'B': 0.2,
    'C': 0.2
}

# Database connection
DATABASE = 'seed_counter.db'
conn = None
cursor = None

def init_database():
    """Initialize the SQLite database and create the seed_count table if it doesn't exist."""
    global conn, cursor
    try:
        conn = sqlite3.connect(DATABASE)
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS seed_count (
                seed_type TEXT PRIMARY KEY,
                count INTEGER DEFAULT 0
            )
        ''')
        conn.commit()
        logging.info("Database initialized successfully.")
    except sqlite3.Error as e:
        logging.error(f"Database initialization failed: {e}")
        sys.exit(1)

def activate_solenoid(solenoid_pin, duration):
    """Activate a solenoid for a specified duration."""
    try:
        GPIO.output(solenoid_pin, GPIO.HIGH)
        logging.info(f"Solenoid {solenoid_pin} activated for {duration} seconds.")
        time.sleep(duration)
        GPIO.output(solenoid_pin, GPIO.LOW)
        logging.info(f"Solenoid {solenoid_pin} deactivated.")
    except Exception as e:
        logging.error(f"Error activating solenoid {solenoid_pin}: {e}")
        GPIO.output(solenoid_pin, GPIO.LOW)

def confirm_switch(pin, timeout=0.5, retries=3):
    """Confirm if a microswitch is closed with a timeout and retries."""
    for attempt in range(retries):
        try:
            if GPIO.input(pin) == GPIO.HIGH:
                logging.info(f"Microswitch {pin} confirmed closed (attempt {attempt + 1}).")
                return True
            else:
                logging.debug(f"Microswitch {pin} not closed (attempt {attempt + 1}).")
                time.sleep(0.1)
        except Exception as e:
            logging.error(f"Error checking microswitch {pin}: {e}")
            return False
    logging.warning(f"Microswitch {pin} did not close after {retries} retries.")
    return False

def detect_seed(ir_pin):
    """Detect a seed using the IR breakbeam sensor."""
    try:
        if GPIO.input(ir_pin) == GPIO.LOW:
            logging.info("Seed detected by IR sensor.")
            return True
        else:
            return False
    except Exception as e:
        logging.error(f"Error detecting seed: {e}")
        return False

def update_database(seed_type):
    """Update the seed count in the database."""
    global cursor, conn
    try:
        cursor.execute("SELECT count(*) FROM seed_count WHERE seed_type = ?", (seed_type,))
        count = cursor.fetchone()[0]
        cursor.execute("UPDATE seed_count SET count = ? WHERE seed_type = ?", (count + 1, seed_type))
        conn.commit()
        logging.info(f"Seed type: {seed_type}, Count: {count + 1}")
    except sqlite3.Error as e:
        logging.error(f"Database update failed: {e}")

def cleanup():
    """Clean up GPIO and database resources."""
    logging.info("Cleaning up resources...")
    try:
        GPIO.output(SOLENOID_PINS, GPIO.LOW)
        GPIO.cleanup()
        logging.info("GPIO cleaned up.")
    except Exception as e:
        logging.error(f"GPIO cleanup failed: {e}")
    finally:
        if conn:
            try:
                conn.close()
                logging.info("Database connection closed.")
            except sqlite3.Error as e:
                logging.error(f"Database close failed: {e}")

def main():
    """Main function to control the solenoid and seed detection."""
    global conn, cursor

    # Initialize GPIO
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for pin in SOLENOID_PINS + MICROSWITCH_PINS + [IR_SENSOR_PIN]:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        logging.info("GPIO initialized successfully.")
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        sys.exit(1)

    # Initialize database
    init_database()

    # Set solenoid cycle time
    solenoid_cycle_time = SEED_TYPES.get('A', 0.2)

