MICROSWITCH_PINS = [5, 6, 13]   # microswitch 1, 2, 3
IR_SENSOR_PIN = 4               # IR breakbeam sensor

# Seed types and their corresponding solenoid activation times (seconds)
SEED_TYPES = {
    'A': 0.2,
    'B': 0.2,
    'C': 0.2
}

# Database connection
DATABASE = 'seed_counter.db'
conn = None
cursor = None

def init_database():
    """Initialize the SQLite database and create the seed_count table if it doesn't exist."""
    global conn, cursor
    try:
        conn = sqlite3.connect(DATABASE)
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS seed_count (
                seed_type TEXT PRIMARY KEY,
                count INTEGER DEFAULT 0
            )
        ''')
        conn.commit()
        logging.info("Database initialized successfully.")
    except sqlite3.Error as e:
        logging.error(f"Database initialization failed: {e}")
        sys.exit(1)

def activate_solenoid(solenoid_pin, duration):
    """Activate a solenoid for a specified duration."""
    try:
        GPIO.output(solenoid_pin, GPIO.HIGH)
        logging.info(f"Solenoid {solenoid_pin} activated for {duration} seconds.")
        time.sleep(duration)
        GPIO.output(solenoid_pin, GPIO.LOW)
        logging.info(f"Solenoid {solenoid_pin} deactivated.")
    except Exception as e:
        logging.error(f"Error activating solenoid {solenoid_pin}: {e}")
        GPIO.output(solenoid_pin, GPIO.LOW)

def confirm_switch(pin, timeout=0.5, retries=3):
    """Confirm if a microswitch is closed with a timeout and retries."""
    for attempt in range(retries):
        try:
            if GPIO.input(pin) == GPIO.HIGH:
                logging.info(f"Microswitch {pin} confirmed closed (attempt {attempt + 1}).")
                return True
            else:
                logging.debug(f"Microswitch {pin} not closed (attempt {attempt + 1}).")
                time.sleep(0.1)
        except Exception as e:
            logging.error(f"Error checking microswitch {pin}: {e}")
            return False
    logging.warning(f"Microswitch {pin} did not close after {retries} retries.")
    return False

def detect_seed(ir_pin):
    """Detect a seed using the IR breakbeam sensor."""
    try:
        if GPIO.input(ir_pin) == GPIO.LOW:
            logging.info("Seed detected by IR sensor.")
            return True
        else:
            return False
    except Exception as e:
        logging.error(f"Error detecting seed: {e}")
        return False

