    global cursor, conn
    try:
        cursor.execute("SELECT count(*) FROM seed_count WHERE seed_type = ?", (seed_type,))
        count = cursor.fetchone()[0]
        cursor.execute("UPDATE seed_count SET count = ? WHERE seed_type = ?", (count + 1, seed_type))
        conn.commit()
        logging.info(f"Seed type: {seed_type}, Count: {count + 1}")
    except sqlite3.Error as e:
        logging.error(f"Database update failed: {e}")

