    """Clean up GPIO and database resources."""
    logging.info("Cleaning up resources...")
    try:
        GPIO.output(SOLENOID_PINS, GPIO.LOW)
        GPIO.cleanup()
        logging.info("GPIO cleaned up.")
    except Exception as e:
        logging.error(f"GPIO cleanup failed: {e}")
    finally:
