import signal
import sys
import time
import logging

from robotic_arm import AngularServo, RoboticArm, exc

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("robotic_arm_demo")

# --- Configuration -----------------------------------------------------------
BASE_PIN = 17
SHOULDER_PIN = 27
GRIPPER_PIN = 22
PWM_FREQ = 50          # Hz
MIN_PULSE_MS = 0.5     # 0 degrees
MAX_PULSE_MS = 2.5     # 90 degrees
SETTLE_DELAY = 0.4     # seconds after each joint move

# --- Globals for cleanup -----------------------------------------------------
_arm = None
_running = True


def _cleanup():
    """Release all servos and clean up GPIO resources."""
    global _arm
    if _arm is not None:
        try:
            for name, servo in _arm.servos.items():
                try:
                    servo.angle = None
                except exc.OutputDeviceBadValue:
                    pass
        except Exception as exc:
            log.warning("Error during servo release: %s", exc)
        try:
            RoboticArm.release()
        except Exception as exc:
            log.warning("Error during RoboticArm.release(): %s", exc)
        _arm = None


def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received – shutting down.", signum)
    _running = False


def _validate_pin(pin: int) -> None:
    if not isinstance(pin, int) or pin < 0:
        raise ValueError(f"Invalid GPIO pin {pin!r}; must be a non-negative integer.")


def _validate_servo(pin: int, name: str) -> None:
    _validate_pin(pin)
    if pin in (BASE_PIN, SHOULDER_PIN, GRIPPER_PIN):
        if not (MIN_PULSE_MS <= 0.5 <= MAX_PULSE_MS):
            raise ValueError(f"Pin {pin} ({name}) out of SG90 pulse-width range.")


def _clamp_angle(angle: float, name: str) -> float:
    """Clamp angle to [-90, 90] and raise ValueError on invalid values."""
    if not isinstance(angle, (int, float)):
        raise ValueError(f"Invalid angle {angle!r} for {name}; must be numeric.")
    return max(-90.0, min(90.0, float(angle)))


def _move_joint(servo: AngularServo, angle: float) -> None:
    """Move a single joint to *angle* (clamped to [-90, 90])."""
    clamped = _clamp_angle(angle, servo.name)
    try:
        servo.angle = clamped
    except exc.OutputDeviceBadValue as exc:
        log.error("Failed to set angle for %s: %s", servo.name, exc)
        raise
    except Exception as exc:
        log.error("Unexpected error moving %s: %s", servo.name, exc)
        raise


def _settle(servo: AngularServo) -> None:
    """Wait for the servo to reach its target position."""
    time.sleep(SETTLE_DELAY)


def go_to_pose(base_angle: float, shoulder_angle: float, gripper_angle: float) -> None:
    """Move the arm to the specified pose and log each step."""
    log.info("Moving to pose: base=%s, shoulder=%s, gripper=%s",
             _clamp_angle(base_angle, "base"), _clamp_angle(shoulder_angle, "shoulder"),
             _clamp_angle(gripper_angle, "gripper"))
    try:
        _move_joint(_arm.servos["base"], base_angle)
        _settle(_arm.servos["base"])
        _move_joint(_arm.servos["shoulder"], shoulder_angle)
        _settle(_arm.servos["shoulder"])
        _move_joint(_arm.servos["gripper"], gripper_angle)
        _settle(_arm.servos["gripper"])
    except exc.OutputDeviceBadValue as exc:
        log.error("Servo error during pose move: %s", exc)
        raise
    except Exception as exc:
        log.error("Unexpected error during pose move: %s", exc)
        raise


def run_demo_sequence() -> None:
    """Demonstrate a sequence of poses: (0,0,0), (45,-30,20), (-45,30,-20), (0,0,0)."""
    poses = [
        (0, 0, 0),
        (45, -30, 20),
        (-45, 30, -20),
        (0, 0, 0),
    ]
    for base, shoulder, gripper in poses:
        if not _running:
            log.info("Demo interrupted by signal.")
            return
        try:
            go_to_pose(base, shoulder, gripper)
        except Exception as exc:
            log.error("Error during pose: %s", exc)
            return
    log.info("Demo sequence completed.")


def main() -> int:
    global _arm

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _arm = RoboticArm()
        _arm.servos = {
            "base": AngularServo(BASE_PIN, PWM_FREQ),
            "shoulder": AngularServo(SHOULDER_PIN, PWM_FREQ),
            "gripper": AngularServo(GRIPPER_PIN, PWM_FREQ),
        }
    except exc.RuntimeError as exc:
        log.error("GPIO allocation failed: %s", exc)
        return 1
    except Exception as exc:
        log.error("Unexpected error initializing servos: %s", exc)
        return 1

    try:
        run_demo_sequence()
    except Exception as exc:
        log.error("Fatal error: %s", exc)
        return 1
    finally:
        _cleanup()
    return 0


if __name__ == "__main__":
    sys.exit(main())

