            self._initialized = True
        except Exception as e:
            self.close()
            raise RuntimeError(f"GPIO setup failed: {e}") from e

    def _setup_pwm(self):
        try:
            self.left_pwm = GPIO.PWM(self.left_enable_pin, PWM_FREQUENCY)
            self.right_pwm = GPIO.PWM(self.right_enable_pin, PWM_FREQUENCY)
            self.left_pwm.start(0)
            self.right_pwm.start(0)
        except Exception as e:
            self.close()
            raise RuntimeError(f"PWM setup failed: {e}") from e

    def set_speed(self, speed):
        """Sets the speed of the motors.

        Args:
            speed: A float between -1.0 (full reverse) and 1.0 (full forward).
