def motor_controller(left_forward_pin, left_backward_pin,
                     left_enable_pin, right_forward_pin, right_backward_pin,
                     right_enable_pin):
    """Context manager for MotorController."""
    controller = MotorController(
        left_forward_pin, left_backward_pin,
        left_enable_pin, right_forward_pin, right_backward_pin,
        right_enable_pin
    )
    try:
        yield controller
    finally:
