class ModbusRtuServo:
    """Encapsulates Modbus RTU communication and register access for a servo motor."""

    def __init__(
        self,
        port: str = "/dev/serial0",
        baudrate: int = 115200,
        timeout: float = 1.0,
        unit_id: int = 1,
    ) -> None:
        self.client: Optional[ModbusSerialClient] = None
        self.unit_id = unit_id
        self._closed = False

        if ModbusSerialClient is None:
            logger.warning(
                "pymodbus not installed; running in mock mode (no UART access)."
            )
            return

        try:
            self.client = ModbusSerialClient(
                port=port,
                baudrate=baudrate,
                parity="N",
                stopbits=1,
                bytesize=8,
                timeout=timeout,
            )
            if not self.client.connect():
                logger.warning(
                    "Failed to open %s; continuing in mock mode.", port
                )
                self.client = None
        except Exception as exc:
            logger.warning(
                "Modbus RTU init failed on %s: %s; mock mode enabled.", port, exc
            )
            self.client = None

