    # Low-level register access
    # ------------------------------------------------------------------
    def _read_holding_register(
        self,
        register: int,
        functioncode: int = ModbusException.FC3,
        count: int = 1,
    ) -> Optional[int]:
        """Read a single or multiple holding registers; return None on error."""
        if self.client is None:
            logger.warning("No UART client available; cannot read register %d.", register)
            return None
        try:
            return self.client.read_holding_registers(
                register=register,
                count=count,
                slave=self.unit_id,
                functioncode=functioncode,
            )
        except ModbusException as exc:
            logger.error("Modbus read error (reg 0x%04X): %s", register, exc)
            return None
        except OSError as exc:
            logger.error("OS error during Modbus read: %s", exc)
            return None

    def _write_holding_register(
        self,
        register: int,
        value: int,
        functioncode: int = ModbusException.FC6,
    ) -> bool:
        """Write a single holding register; return True on success."""
        if self.client is None:
            logger.warning("No UART client available; cannot write register %d.", register)
            return False
        try:
            self.client.write_holding_registers(
                register=register,
                values=[value],
                slave=self.unit_id,
                functioncode=functioncode,
            )
            return True
        except ModbusException as exc:
            logger.error("Modbus write error (reg 0x%04X): %s", register, exc)
            return False
        except OSError as exc:
            logger.error("OS error during Modbus write: %s", exc)
            return False

