    # Public register map
    # ------------------------------------------------------------------
    def read_register(
        self,
        register: int,
        functioncode: int = ModbusException.FC3,
        count: int = 1,
    ) -> Optional[int]:
        """Read a register via the standard Modbus RTU API."""
        return self._read_holding_register(register, functioncode, count)

    def write_register(
        self,
        register: int,
        value: int,
        functioncode: int = ModbusException.FC6,
    ) -> bool:
        """Write a register via the standard Modbus RTU API."""
        return self._write_holding_register(register, value, functioncode)

    # ------------------------------------------------------------------
    # Single-register helpers
    # ------------------------------------------------------------------
    def read_single_register(self, register: int) -> Optional[int]:
        """Convenience wrapper for reading a single holding register."""
        return self.read_register(register, ModbusException.FC3, count=1)

    def write_single_register(self, register: int, value: int) -> bool:
        """Convenience wrapper for writing a single holding register."""
        return self.write_register(register, value, ModbusException.FC6)

    # ------------------------------------------------------------------
    # Multiple-register helpers
    # ------------------------------------------------------------------
    def read_multiple_registers(self, register: int, count: int) -> Optional[list]:
        """Read multiple holding registers via the standard Modbus RTU API."""
        return self._read_holding_register(register, ModbusException.FC3, count)

    def write_multiple_registers(self, register: int, values: list) -> bool:
        """Write multiple holding registers via the standard Modbus RTU API."""
        if len(values) != count:
            logger.error("write_multiple_registers expects %d values, got %d.", count, len(values))
            return False
        return self._write_holding_register(register, values[0], ModbusException.FC16)

    # ------------------------------------------------------------------
    # Cleanup
    # ------------------------------------------------------------------
    def close(self) -> None:
        """Release the UART resource if it is open."""
        if self.client is not None:
            try:
                if self.client.is_socket_open():
                    self.client.close()
            except Exception as exc:
                logger.warning("Error closing Modbus client: %s", exc)
            finally:
                self.client = None

    def __del__(self) -> None:
        self.close()


# ----------------------------------------------------------------------
# Signal handling for clean shutdown
# ----------------------------------------------------------------------
_servo_instance: Optional[ModbusRtuServo] = None


def _signal_handler(signum, frame) -> None:
