import time
import signal
import sys
import logging
from typing import Optional

try:
    import board
    import busio
    from adafruit_pca9685 import PCA9685
except ImportError as exc:
    print(f"Missing dependency: {exc}", file=sys.stderr)
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)

BASE = 0
DROP = 1
SEEK = 2
GRAB = 4

METAL = 135
PLASTIC = 180
PAPER = 90
GRIPPER_OPEN = 90
GRIPPER_CLOSE = 120
DROP_ANGLE = 160
COLLECT_ANGLE = 100
DEFAULT_ANGLE = 90

MIN_ANGLE = 0
MAX_ANGLE = 180
STEP_SIZE = 5
DELAY = 0.04
DROP_STEP_SIZE = 2
DROP_DELAY = 0.01


class ServoController:
    """Robust PCA9685-based servo controller for a sorting arm."""

    def __init__(self, address: int = 0x40):
        self._pca: Optional[PCA9685] = None
        self._i2c: Optional[busio.I2C] = None
        self._channels: list[int] = []
        try:
            self._i2c = busio.I2C(board.SCL, board.SDA)
            self._pca = PCA9685(self._i2c, address=address)
            self._pca.frequency = 1600
            self._channels = [self._pca.channels[i] for i in range(16)]
            logger.info("PCA9685 initialized at 0x%02X on I2C bus 1.", address)
        except Exception as exc:
            logger.error("Failed to initialize PCA9685 at 0x%02X: %s", address, exc)
            self.close()
            raise

    def move_servo(self, channel: int, target_angle: int, step_size: int = STEP_SIZE, delay: float = DELAY) -> None:
        """Move a servo smoothly toward *target_angle* (0-180)."""
        if not 0 <= channel < 16:
            raise ValueError(f"Invalid channel {channel}; must be 0-15.")
        if not MIN_ANGLE <= target_angle <= MAX_ANGLE:
            raise ValueError(f"Invalid target angle {target_angle}; must be {MIN_ANGLE}-{MAX_ANGLE}.")
        if step_size <= 0:
            raise ValueError("step_size must be positive.")
        if delay < 0:
            raise ValueError("delay must be non-negative.")
        if step_size == 0:
            self._channels[channel].duty_cycle = 0
            return
        step = step_size if target_angle > MIN_ANGLE else -step_size
        current = self._get_angle(channel)
        if current is None:
            current = MIN_ANGLE
        current = max(MIN_ANGLE, min(MAX_ANGLE, current))
        angle = current + step
        while abs(angle - target_angle) > 1:
            angle = max(MIN_ANGLE, min(MAX_ANGLE, angle))
            self._channels[channel].duty_cycle = int((angle / MAX_ANGLE) * 0xFFFF)
            time.sleep(delay)
        self._channels[channel].duty_cycle = int((target_angle / MAX_ANGLE) * 0xFFFF)

    def _get_angle(self, channel: int) -> Optional[int]:
        """Return the current angle of *channel* or None if unavailable."""
        if self._pca is None:
            return None
        try:
            return self._pca.channels[channel].angle
        except Exception:
            return None

    def seek(self, angle: int) -> None:
        self.move_servo(SEEK, angle)

    def deseek(self, angle: int) -> None:
        self.move_servo(SEEK, angle)

    def drop(self, angle: int) -> None:
        self.move_servo(DROP, angle)

    def pick(self, angle: int) -> None:
        self.move_servo(GRAB, angle)

    def grab(self, angle: int) -> None:
        self.move_servo(GRAB, angle)

    def release(self, angle: int) -> None:
        self.move_servo(GRAB, angle)

    def collect_object_steps(self, seek_angle: int) -> None:
        """Sequence: seek -> grab -> drop -> pick -> deseek."""
        self.seek(seek_angle)
        self.pick(COLLECT_ANGLE)
        self.drop(DROP_ANGLE)
        self.release(COLLECT_ANGLE)
        self.deseek(seek_angle)

    def drop_object_steps(self, drop_angle: int) -> None:
        """Sequence: move drop servo to *drop_angle* -> release gripper -> return to 100°."""
        self.move_servo(DROP, drop_angle, step_size=DROP_STEP_SIZE, delay=DROP_DELAY)
        self.release(GRIPPER_CLOSE)
        self.move_servo(DROP, 100)

    def get_pos_x(self, x_center: int) -> int:
        """Map 0-320 px to 0-180°, clamped."""
        return max(MIN_ANGLE, min(MAX_ANGLE, int((x_center / 320.0) * (MAX_ANGLE - MIN_ANGLE))))

    def get_pos_y(self, y_center: int) -> int:
        """Map 0-320 px to 0-180°, clamped."""
        return max(MIN_ANGLE, min(MAX_ANGLE, int((y_center / 320.0) * (MAX_ANGLE - MIN_ANGLE))))

    def collect_object(self, x_center: int, y_center: int, drop_angle: int) -> None:
        """Full collect sequence: base -> seek -> collect -> drop -> base."""
        base = self.get_pos_x(x_center)
        seek = self.get_pos_y(y_center)
        self.base_move_steps(base)
        self.collect_object_steps(seek)
        self.drop_object_steps(drop_angle)
        self.base_move_steps(DEFAULT_ANGLE)

    def base_move_steps(self, angle: int) -> None:
        self.move_servo(BASE, angle)

    def close(self) -> None:
        """Release all servos and clean up I2C resources."""
        if self._pca is not None:
            for ch in self._channels:
                try:
                    ch.duty_cycle = 0
                except Exception:
                    pass
        if self._i2c is not None:
            try:
                self._i2c.deinit()
            except Exception:
                pass
            self._i2c = None
        self._pca = None
        logger.info("ServoController closed.")


def _signal_handler(signum, frame):
    logger.info("Signal %d received, shutting down.", signum)
    sys.exit(0)


def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        controller = ServoController(address=0x40)
    except Exception:
        sys.exit(1)
    try:
        controller.collect_object(x_center=160, y_center=240, drop_angle=PLASTIC)
    except Exception as exc:
        logger.error("Error during object collection: %s", exc)
    finally:
        controller.close()


if __name__ == "__main__":
    main()

