import curses
import signal
import sys
import time

try:
    from smbus2 import SMBus
except ImportError:
    from smbus import SMBus

try:
    from adafruit_pca9685 import PCA9685
except ImportError:
    print("Error: adafruit-circuitpython-pca9685 not installed.")
    sys.exit(0)

PWM_FREQUENCY = 60
I2C_BUS = 1
PCA9685_ADDR = 0x40
PWM_CHANNEL_ESC = 0
PWM_CHANNEL_STEERING = 1
THROTTLE_STOP = 400
CALIBRATION_INCREMENT = 20
CALIBRATION_DELAY = 0.1
STEERING_CENTER = 500
STEERING_MIN = 380
STEERING_MAX = 620

running = True
esc = None
pca = None
curses_term = None


def signal_handler(signum, frame):
    global running
    running = False


def init_pca9685(bus, address):
    try:
        pca = PCA9685(bus, address=address)
        pca.frequency = PWM_FREQUENCY
        return pca
    except Exception as e:
        print(f"Error initializing PCA9685: {e}")
        return None


def set_pwm(pca, channel, value):
    try:
        pca.channels[channel].duty_cycle = value
    except Exception as e:
        print(f"Error setting PWM on channel {channel}: {e}")


def calibrate_esc(pca, start, stop, increment, delay):
    print("Calibrating ESC...")
    for value in range(start, stop + 1, increment):
        set_pwm(pca, PWM_CHANNEL_ESC, value)
        time.sleep(delay)
    set_pwm(pca, PWM_CHANNEL_ESC, stop)
    print("ESC calibration complete.")


def reset_esc(pca):
    set_pwm(pca, PWM_CHANNEL_ESC, THROTTLE_STOP)


def reset_steering(pca):
    set_pwm(pca, PWM_CHANNEL_STEERING, STEERING_CENTER)


def cleanup(pca, curses_term):
    reset_esc(pca)
    reset_steering(pca)
    if pca is not None:
        try:
            pca.deinit()
        except Exception:
            pass
    if curses_term is not None:
        curses_term.nocbreak()
        curses_term.keypad(False)
        curses_term.timeout(-1)
        curses_term.refresh()
        curses.endwin()


def main(stdscr):
    global esc, pca, curses_term

    curses_term = stdscr
    curses.noecho()
    curses.cbreak()
    stdscr.keypad(True)
    stdscr.timeout(100)

    try:
        bus = SMBus(I2C_BUS)
    except Exception as e:
        print(f"Error opening I2C bus {I2C_BUS}: {e}")
        return

    pca = init_pca9685(bus, PCA9685_ADDR)
    if pca is None:
        try:
            bus.close()
        except Exception:
            pass
        return

    esc = pca.channels[PWM_CHANNEL_ESC]
    set_pwm(pca, PWM_CHANNEL_ESC, THROTTLE_STOP)
    set_pwm(pca, PWM_CHANNEL_STEERING, STEERING_CENTER)

    try:
        calibrate_esc(pca, 200, 600, CALIBRATION_INCREMENT, CALIBRATION_DELAY)
    except Exception as e:
        print(f"Error during ESC calibration: {e}")
        try:
            bus.close()
        except Exception:
            pass
        return

    curses_term.addstr(0, 0, "Raspberry Pi ESC & Steering Demo")
    curses_term.addstr(1, 0, "UP/DOWN: Throttle  LEFT/RIGHT: Steering")
    curses_term.addstr(2, 0, "q: reset, x: exit")
    curses_term.refresh()

    while running:
        key = curses_term.getch()
        if key == ord('q'):
            reset_esc(pca)
            reset_steering(pca)
            break
        elif key == ord('x'):
            running = False
            break
        elif key == curses.KEY_UP:
            val = min(THROTTLE_STOP + CALIBRATION_INCREMENT, THROTTLE_STOP + CALIBRATION_INCREMENT * 3)
            set_pwm(pca, PWM_CHANNEL_ESC, val)
        elif key == curses.KEY_DOWN:
            val = max(200, THROTTLE_STOP - CALIBRATION_INCREMENT)
            set_pwm(pca, PWM_CHANNEL_ESC, val)
        elif key == curses.KEY_LEFT:
            val = max(STEERING_MIN, STEERING_CENTER - CALIBRATION_INCREMENT)
            set_pwm(pca, PWM_CHANNEL_STEERING, val)
        elif key == curses.KEY_RIGHT:
            val = min(STEERING_MAX, STEERING_CENTER + CALIBRATION_INCREMENT)
            set_pwm(pca, PWM_CHANNEL_STEERING, val)
        curses_term.refresh()

    cleanup(pca, curses_term)


def main_loop():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        curses.wrapper(main)
    except Exception as e:
        print(f"Error in curses wrapper: {e}")
    finally:
        running = False
        cleanup(esc, curses_term)


if __name__ == "__main__":
    try:
        main_loop()
    except KeyboardInterrupt:
        pass

