    pca = init_pca9685(bus, PCA9685_ADDR)
    if pca is None:
        try:
            bus.close()
        except Exception:
            pass
        return

    esc = pca.channels[PWM_CHANNEL_ESC]
    set_pwm(pca, PWM_CHANNEL_ESC, THROTTLE_STOP)
    set_pwm(pca, PWM_CHANNEL_STEERING, STEERING_CENTER)

    try:
        calibrate_esc(pca, 200, 600, CALIBRATION_INCREMENT, CALIBRATION_DELAY)
    except Exception as e:
        print(f"Error during ESC calibration: {e}")
        try:
            bus.close()
        except Exception:
            pass
        return

    curses_term.addstr(0, 0, "Raspberry Pi ESC & Steering Demo")
    curses_term.addstr(1, 0, "UP/DOWN: Throttle  LEFT/RIGHT: Steering")
    curses_term.addstr(2, 0, "q: reset, x: exit")
    curses_term.refresh()

    while running:
        key = curses_term.getch()
        if key == ord('q'):
            reset_esc(pca)
            reset_steering(pca)
            break
        elif key == ord('x'):
            running = False
            break
        elif key == curses.KEY_UP:
            val = min(THROTTLE_STOP + CALIBRATION_INCREMENT, THROTTLE_STOP + CALIBRATION_INCREMENT * 3)
            set_pwm(pca, PWM_CHANNEL_ESC, val)
        elif key == curses.KEY_DOWN:
            val = max(200, THROTTLE_STOP - CALIBRATION_INCREMENT)
            set_pwm(pca, PWM_CHANNEL_ESC, val)
        elif key == curses.KEY_LEFT:
            val = max(STEERING_MIN, STEERING_CENTER - CALIBRATION_INCREMENT)
