import time
import signal
import sys
from typing import Optional

try:
    from adafruit_servokit import ServoKit
except ImportError:
    print("Error: adafruit-circuitpython-servokit is not installed.")
    print("Install it with: pip install adafruit-circuitpython-servokit")
    sys.exit(1)

# Constants
SERVO_CHANNEL = 0
GRAB_ANGLE = 90
RELEASE_ANGLE = 150
TARGET_ANGLE = 150
STEP_DEGREES = 5
STEP_DELAY = 0.04
MIN_ANGLE = 0
MAX_ANGLE = 180
I2C_BUS = 1
PCA9685_ADDRESS = 0x40

# Global kit reference for signal handler
_kit: Optional[ServoKit] = None


def _cleanup() -> None:
    """Release resources if the kit was initialized."""
    global _kit
    if _kit is not None:
        try:
            for ch in range(16):
                _kit.servo[ch].angle = None
        except Exception:
            pass
        _kit = None


def _signal_handler(signum, frame) -> None:
    """Handle SIGINT/SIGTERM for clean shutdown."""
    print(f"\nReceived signal {signum}, exiting...")
    _cleanup()
    sys.exit(0)


def initialize_servokit() -> ServoKit:
    """Initialize the ServoKit on I2C bus 1 at address 0x40."""
    try:
        return ServoKit(channels=16, address=PCA9685_ADDRESS, i2c=None)
    except OSError as e:
        raise OSError(f"Failed to initialize ServoKit on I2C bus {I2C_BUS} "
                      f"at address 0x{PCA9685_ADDRESS:02X}: {e}")
    except ValueError as e:
        raise ValueError(f"Invalid ServoKit parameters: {e}")


def validate_channel(channel: int) -> None:
    """Validate that the channel is within the allowed range (0-15)."""
    if not isinstance(channel, int) or not (0 <= channel <= 15):
        raise ValueError(f"Invalid channel {channel}; must be an integer between 0 and 15.")


def validate_angle(angle: int) -> None:
    """Validate that the angle is within the allowed range (0-180)."""
    if not isinstance(angle, int) or not (0 <= angle <= 180):
        raise ValueError(f"Invalid angle {angle}; must be an integer between 0 and 180.")


def move_servo(kit: ServoKit, channel: int, target_angle: int) -> None:
    """Move the specified servo channel toward target_angle in 5-degree steps."""
    validate_channel(channel)
    validate_angle(target_angle)

    current_angle = kit.servo[channel].angle
    if current_angle is None:
        current_angle = MIN_ANGLE

    if current_angle < target_angle:
        step = STEP_DEGREES if target_angle - current_angle >= STEP_DEGREES else -STEP_DEGREES
    else:
        step = STEP_DEGREES if current_angle > target_angle else -STEP_DEGREES

    try:
        while current_angle != target_angle:
            current_angle += step
            current_angle = max(MIN_ANGLE, min(MAX_ANGLE, current_angle))
            kit.servo[channel].angle = current_angle
            time.sleep(STEP_DELAY)
    except OSError as e:
        raise OSError(f"I2C communication error moving servo on channel {channel}: {e}")
    except ValueError as e:
        raise ValueError(f"Invalid angle value during servo movement: {e}")


def grab_object(kit: ServoKit, channel: int = SERVO_CHANNEL, grab_angle: int = GRAB_ANGLE) -> None:
    """Move the specified servo channel to the grab angle."""
    validate_channel(channel)
    validate_angle(grab_angle)
    move_servo(kit, channel, grab_angle)


def release_object(kit: ServoKit, channel: int = SERVO_CHANNEL, release_angle: int = RELEASE_ANGLE) -> None:
    """Move the specified servo channel to the release angle."""
    validate_channel(channel)
    validate_angle(release_angle)
    move_servo(kit, channel, release_angle)


def main() -> None:
    """Main entry point: grab, release, and demonstrate movement."""
    global _kit

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _kit = initialize_servokit()
        print("ServoKit initialized on I2C bus 1 at address 0x40.")

        grab_object(_kit, SERVO_CHANNEL, GRAB_ANGLE)
        print("Object grabbed.")

        release_object(_kit, SERVO_CHANNEL, RELEASE_ANGLE)
        print("Object released.")

        # Demonstrate movement
        for angle in range(0, 181, STEP_DEGREES):
            move_servo(_kit, SERVO_CHANNEL, angle)
            time.sleep(STEP_DELAY)

    except (OSError, ValueError) as e:
        print(f"Error: {e}")
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

