import logging
import time
import signal
import paho.mqtt.client as mqtt

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
logger = logging.getLogger(__name__)

REPORT_TOPIC = "city/reports"
NOISE_TOPIC = "city/noise"
TRAFFIC_TOPIC = "city/traffic"
BROKER = "localhost"
PORT = 1883
KEEPALIVE = 60
RUN_SECONDS = 5

_running = True


def _signal_handler(signum, frame):
    global _running
    logger.info("Signal %s received, shutting down...", signum)
    _running = False


def classify_report(report_text):
    """Classify a text report as noise, traffic, or other."""
    if report_text is None or not report_text.strip():
        return "other"
    if "car" in report_text.lower() and "traffic" in report_text.lower():
        return "traffic"
    if "sirens" in report_text.lower() or "police" in report_text.lower():
        return "noise"
    return "other"


def handle_message(mqtt_client, userdata, message):
    """Decode and classify an MQTT incoming message."""
    try:
        report_text = message.payload.decode("utf-8", errors="replace")
    except Exception as e:
        logger.error("Failed to decode message payload: %s", e)
        return

    classification = classify_report(report_text)
    logger.info("Classification: %s, Report: %s", classification, report_text[:50] + ("..." if len(report_text) > 50 else ""))

    if classification == "noise":
        userdata["noise_count"] += 1
    elif classification == "traffic":
        userdata["traffic_count"] += 1
    else:
        userdata["other_count"] += 1


def on_connect(mqtt_client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        logger.info("Connected to MQTT broker at %s:%d", BROKER, PORT)
        mqtt_client.subscribe(REPORT_TOPIC)
        logger.info("Subscribed to %s", REPORT_TOPIC)
    else:
        logger.error("Connection failed with reason code: %s", reason_code)


def on_disconnect(mqtt_client, userdata, flags, reason_code, properties):
    logger.warning("Disconnected from MQTT broker (reason code: %s)", reason_code)


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    userdata = {"noise_count": 0, "traffic_count": 0, "other_count": 0}

    mqtt_client = mqtt.Client(
        callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
        client_id="urban_monitor",
        userdata=userdata,
    )
    mqtt_client.on_connect = on_connect
    mqtt_client.on_disconnect = on_disconnect

    try:
        mqtt_client.connect(BROKER, PORT, KEEPALIVE)
    except Exception as e:
        logger.error("Failed to connect to MQTT broker: %s", e)
        return

    try:
        mqtt_client.loop_start()
        logger.info("MQTT client loop started. Monitoring for %d seconds...", RUN_SECONDS)
        while _running and mqtt_client.is_connected():
            time.sleep(0.5)
        logger.info("MQTT client loop stopped.")
    except Exception as e:
        logger.error("MQTT client error: %s", e)
    finally:
        try:
            mqtt_client.loop_stop()
        except Exception:
            pass
        try:
            mqtt_client.disconnect()
        except Exception:
            pass
        logger.info("Classification counts after %d seconds: %s", RUN_SECONDS, userdata)
        logger.info("Noise: %d, Traffic: %d, Other: %d", userdata["noise_count"], userdata["traffic_count"], userdata["other_count"])


if __name__ == "__main__":
    main()

