import time
import logging
import signal
import sys
from ina219 import INA219, DeviceRangeError

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

I2C_BUS = 1
SUPPLY_VCC = 5.0
SHUNT_RESISTOR_SUPPLY = 0.00725
SHUNT_RESISTOR_BATT = 0.005
CALIBRATION = 4096

running = True
i2c = None


def signal_handler(signum, frame):
    global running
    running = False


def close_i2c():
    global i2c
    if i2c is not None:
        try:
            i2c.deinitialize()
        except Exception:
            pass
        i2c = None


def read_ina219(i2c_bus, shunt_resistor, supply_vcc, calibration):
    try:
        ina = INA219(shunt_resistor, bus=i2c_bus, address=None)
        ina.configure()
        ina.recalibrate(calibration)
        return ina
    except (DeviceRangeError, OSError, ValueError) as e:
        logging.error(f"Failed to initialize INA219 on I2C bus {i2c_bus}: {e}")
        return None


def read_supply_power(ina):
    try:
        return ina.power()
    except (DeviceRangeError, OSError) as e:
        logging.error(f"Error reading supply power: {e}")
        return None


def read_battery_power(ina):
    try:
        return ina.power()
    except (DeviceRangeError, OSError) as e:
        logging.error(f"Error reading battery power: {e}")
        return None


def main():
    global i2c
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        i2c = smbus.SMBus(I2C_BUS)
    except OSError as e:
        logging.error(f"Failed to open I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    ina_supply = read_ina219(i2c, SHUNT_RESISTOR_SUPPLY, SUPPLY_VCC, CALIBRATION)
    ina_battery = read_ina219(i2c, SHUNT_RESISTOR_BATT, SUPPLY_VCC, CALIBRATION)

    if ina_supply is None or ina_battery is None:
        logging.warning("One or both INA219 sensors failed to initialize. Continuing anyway.")

    try:
        while running:
            if ina_supply is not None:
                supply_power = read_supply_power(ina_supply)
                if supply_power is not None:
                    logging.info(f"Supply Power: {supply_power:.2f} mW")
            if ina_battery is not None:
                battery_power = read_battery_power(ina_battery)
                if battery_power is not None:
                    logging.info(f"Battery Power: {battery_power:.2f} mW")
            time.sleep(5)
    finally:
        close_i2c()
        logging.info("Program terminated.")


if __name__ == "__main__":
    main()

