import smbus2


class I2CDevice:
    """Generic I2C device helper for Raspberry Pi using smbus2."""

    def __init__(self, address, bus_number=1):
        self.address = address
        self.bus = None
        try:
            self.bus = smbus2.SMBus(bus_number)
        except OSError as exc:
            raise RuntimeError(
                f"Failed to open I2C bus {bus_number}: {exc}"
            ) from exc

