import time
import serial
import RPi.GPIO as GPIO

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_INTERVAL = 1.0

_running = True
_serial_conn = None
_alarm_active = False


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _serial_conn, _alarm_active
    if _serial_conn is not None:
        try:
            _serial_conn.close()
        except Exception:
            pass
        _serial_conn = None
    try:
        GPIO.output(ALARM_PIN, GPIO.LOW)
    except Exception:
        pass
    try:
        GPIO.cleanup()
    except Exception:
        pass
    _alarm_active = False


def _open_serial():
    try:
        conn = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
        if not conn.is_open:
            raise IOError(f"Serial port {SERIAL_PORT} did not open")
        return conn
    except serial.SerialException as exc:
        print(f"Error: cannot open serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None
    except IOError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return None


def _read_radiation_level(conn):
    try:
        raw = conn.readline()
    except serial.SerialException as exc:
        print(f"Serial I/O error: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"OS error: {exc}", file=sys.stderr)
        return None

    if not raw:
        return None

    try:
        text = raw.decode('ascii', errors='replace').strip()
    except Exception as exc:
        print(f"Decode error: {exc}", file=sys.stderr)
        return None

    if not text:
        return None

    try:
        radiation = float(text)
    except ValueError:
        print(f"Invalid data received (not numeric): {text!r}", file=sys.stderr)
        return None

    return radiation


def main():
    global _serial_conn, _alarm_active

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(ALARM_PIN, GPIO.OUT, initial=GPIO.LOW)

    _serial_conn = _open_serial()
    if _serial_conn is None:
        _cleanup()
        sys.exit(1)

    try:
        while _running:
            radiation_level = _read_radiation_level(_serial_conn)

            if radiation_level is not None:
                print(f"Radiation Level: {radiation_level:.2f} µSv/h")
                _alarm_active = radiation_level > RADIATION_THRESHOLD
                if _alarm_active and not _alarm_active:
                    print("ALARM: Radiation level exceeds threshold!")
                elif not _alarm_active and _alarm_active:
                    print("ALARM: Radiation level within safe limits.")
            else:
                print("Skipping read due to I/O or parse error.")

            time.sleep(READ_INTERVAL)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

