import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'gps_coordinates_log.txt'

running = True

def signal_handler(signum, frame):
    global running
    running = False

def initialize_serial(port, baudrate, timeout):
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        ser.reset_input_buffer()
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None

def parse_gpgga_data(data):
    if not data.startswith('$GPGGA'):
        return None
    try:
        parts = data.split(',')
        if len(parts) < 15:
            return None
        fix_quality = parts[6]
        if fix_quality == '1':
            lat = parts[2]
            lat_dir = parts[3]
            lon = parts[4]
            lon_dir = parts[5]
            alt = parts[9]
            return lat, lat_dir, lon, lon_dir, alt
        return None
    except (ValueError, IndexError) as e:
        print(f"Error parsing GPGGA data: {e}", file=sys.stderr)
        return None

def log_coordinates(log_file, latitude, latitude_dir, longitude, longitude_dir, altitude):
    timestamp = datetime.now().isoformat(timespec='seconds')
    log_entry = f"{timestamp} - Latitude: {latitude} {latitude_dir}, Longitude: {longitude} {longitude_dir}, Altitude: {altitude} m\n"
    try:
        with open(log_file, 'a') as f:
            f.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ser = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if ser is None:
        sys.exit(1)

    try:
        while running:
            try:
                raw_line = ser.readline()
                if not raw_line:
                    continue
                line = raw_line.decode('ascii', errors='replace').strip()
                if line:
                    parsed = parse_gpgga_data(line)
                    if parsed:
                        latitude, latitude_dir, longitude, longitude_dir, altitude = parsed
                        print(f"Latitude: {latitude} {latitude_dir}, Longitude: {longitude} {longitude_dir}, Altitude: {altitude} m")
                        log_coordinates(LOG_FILE, latitude, latitude_dir, longitude, longitude_dir, altitude)
            except serial.SerialException as e:
                print(f"Serial communication error: {e}", file=sys.stderr)
                break
            except Exception as e:
                print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if ser and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

