import serial
import time
import sys

PORT = '/dev/ttyUSB0'
BAUD = 9600
TIMEOUT = 1
READ_INTERVAL = 1


def read_oximeter_data(ser):
    """Read one line from the serial port and parse heart rate / SpO2."""
    raw = ser.readline()
    if not raw:
        return None
    line = raw.decode('ascii', errors='replace').strip()
    if not line:
        return None
    parts = line.split(',')
    if len(parts) != 2:
        raise ValueError(f"Expected 2 fields, got {len(parts)}: '{line}'")
    return parts[0].strip(), parts[1].strip()


def main():
    ser = None
    try:
        ser = serial.Serial(
            port=PORT,
            baudrate=BAUD,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
        print(f"Opened {PORT} @ {BAUD} baud. Reading pulse oximeter data...")
        while True:
            try:
                hr, spo2 = read_oximeter_data(ser)
            except ValueError as e:
                print(f"Warning: data format error: {e}", file=sys.stderr)
                continue
            except serial.SerialException as e:
                print(f"Warning: serial read error: {e}", file=sys.stderr)
                continue
            if hr and spo2:
                print(f"Heart Rate: {hr} bpm, SpO2: {spo2} %")
            time.sleep(READ_INTERVAL)
    except serial.SerialException as e:
        print(f"Error: could not open serial port {PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")


if __name__ == '__main__':
    main()

