import serial
import time
import sys

BLUETOOTH_DEVICE = '/dev/rfcomm4'
BLUETOOTH_BAUDRATE = 38400
TRANSMIT_DELAY = 0.1


def send_command(command: str) -> None:
    """Send a prefixed command over the Bluetooth RFCOMM link.

    Args:
        command: The command string to send (must start with 'X ').

    Raises:
        RuntimeError: If the serial connection cannot be opened or
            data is not transmitted successfully.
    """
    try:
        bluetooth_link = serial.Serial(
            port=BLUETOOTH_DEVICE,
            baudrate=BLUETOOTH_BAUDRATE,
            timeout=1,
        )
    except serial.SerialException as exc:
        raise RuntimeError(f"Failed to open Bluetooth device {BLUETOOTH_DEVICE}: {exc}") from exc

    try:
        payload = f"X {command}\n"
        bytes_written = bluetooth_link.write(payload.encode('utf-8'))
        if bytes_written != len(payload):
            raise RuntimeError(
                f"Incomplete write: expected {len(payload)} bytes, wrote {bytes_written}"
            )
        bluetooth_link.flush()
        time.sleep(TRANSMIT_DELAY)
    except serial.SerialException as exc:
        raise RuntimeError(f"Failed to transmit command '{command}': {exc}") from exc
    finally:
        try:
            bluetooth_link.close()
        except Exception:
            pass


def main() -> None:
    """Continuously prompt the user for commands and send them over Bluetooth."""
    try:
        while True:
            try:
                user_input = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_input.strip().lower() == "exit":
                break

            command_to_send = f"X {user_input}"
            try:
                send_command(command_to_send)
            except RuntimeError as exc:
                print(f"Error: {exc}", file=sys.stderr)
                break

    except KeyboardInterrupt:
        print("\nInterrupted by user, exiting.")
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()

